@import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,400;0,500;0,600;0,700;1,500;1,600&family=Montserrat:wght@400;500;600;700;800&family=Playfair+Display:ital,wght@0,400;0,500;0,600;0,700;1,400;1,500;1,600;1,700&family=Outfit:wght@300;400;500;600;700;800&display=swap');

:root {
  --bg: #05070a;
  --panel: #0a1120;
  --text: #ffffff;
  --muted: #9ca3af;
  --gold: #c5a059;
  --line: rgba(255, 255, 255, 0.15);
  /* Service cards: eyebrow + REQUEST DETAILS button share the same light blue */
  --service-light-blue: #a5c8e8;
  --service-light-blue-hover: #bdd6f4;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* ── Scroll Reveal ── */

.reveal {
  opacity: 0;
  transform: translateY(40px);
  transition: opacity 0.8s cubic-bezier(0.16, 1, 0.3, 1),
              transform 0.8s cubic-bezier(0.16, 1, 0.3, 1);
}

.reveal.revealed {
  opacity: 1;
  transform: translateY(0);
}

.reveal-delay-1 { transition-delay: 0.1s; }
.reveal-delay-2 { transition-delay: 0.2s; }
.reveal-delay-3 { transition-delay: 0.3s; }
.reveal-delay-4 { transition-delay: 0.4s; }

.reveal-left {
  opacity: 0;
  transform: translateX(-40px);
  transition: opacity 0.8s cubic-bezier(0.16, 1, 0.3, 1),
              transform 0.8s cubic-bezier(0.16, 1, 0.3, 1);
}

.reveal-left.revealed {
  opacity: 1;
  transform: translateX(0);
}

.reveal-right {
  opacity: 0;
  transform: translateX(40px);
  transition: opacity 0.8s cubic-bezier(0.16, 1, 0.3, 1),
              transform 0.8s cubic-bezier(0.16, 1, 0.3, 1);
}

.reveal-right.revealed {
  opacity: 1;
  transform: translateX(0);
}

.reveal-scale {
  opacity: 0;
  transform: scale(0.92);
  transition: opacity 0.8s cubic-bezier(0.16, 1, 0.3, 1),
              transform 0.8s cubic-bezier(0.16, 1, 0.3, 1);
}

.reveal-scale.revealed {
  opacity: 1;
  transform: scale(1);
}

.staggered-text {
  white-space: pre-wrap;
  word-wrap: break-word;
}

.staggered-text.staggered-text--block {
  display: block;
}

.staggered-text.staggered-text--flex {
  display: flex;
  flex-wrap: wrap;
}

/* ── end Scroll Reveal ── */

/* ── Preloader ── */

.preloader {
  position: fixed;
  inset: 0;
  z-index: 9999;
  background: #05070a;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  transition: opacity 0.8s cubic-bezier(0.4, 0, 0.2, 1),
              transform 0.8s cubic-bezier(0.4, 0, 0.2, 1);
}

.preloader-exit {
  opacity: 0;
  transform: scale(1.06);
  pointer-events: none;
}

.preloader-glow {
  position: absolute;
  border-radius: 50%;
  filter: blur(100px);
  pointer-events: none;
}

.preloader-glow-1 {
  width: 500px;
  height: 500px;
  background: radial-gradient(circle, rgba(143,186,255,0.2) 0%, transparent 70%);
  top: -10%;
  left: 20%;
  animation: preGlow1 4s ease-in-out infinite;
}

.preloader-glow-2 {
  width: 400px;
  height: 400px;
  background: radial-gradient(circle, rgba(74,144,226,0.14) 0%, transparent 70%);
  bottom: -5%;
  right: 15%;
  animation: preGlow2 5s ease-in-out infinite;
}

.preloader-glow-3 {
  width: 300px;
  height: 300px;
  background: radial-gradient(circle, rgba(143,186,255,0.12) 0%, transparent 70%);
  top: 40%;
  right: 30%;
  animation: preGlow3 3.5s ease-in-out infinite;
}

@keyframes preGlow1 {
  0%, 100% { transform: translate(0, 0) scale(1); opacity: 0.6; }
  50%      { transform: translate(30px, 20px) scale(1.2); opacity: 1; }
}

@keyframes preGlow2 {
  0%, 100% { transform: translate(0, 0) scale(1); opacity: 0.5; }
  50%      { transform: translate(-20px, -15px) scale(1.15); opacity: 0.9; }
}

@keyframes preGlow3 {
  0%, 100% { transform: translate(0, 0) scale(0.9); opacity: 0.4; }
  50%      { transform: translate(15px, -25px) scale(1.1); opacity: 0.8; }
}

.preloader-content {
  position: relative;
  text-align: center;
  animation: preBreathe 3s ease-in-out infinite;
}

@keyframes preBreathe {
  0%, 100% { transform: scale(1); }
  50%      { transform: scale(1.035); }
}

.preloader-logo-wrap {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0.1rem;
  margin-bottom: 1.5rem;
}

/* Radiant halo behind the emblem for a premium, luminous feel */
.preloader-logo-halo {
  position: absolute;
  top: 50%;
  left: 50%;
  width: clamp(300px, 46vh, 560px);
  height: clamp(300px, 46vh, 560px);
  transform: translate(-50%, -50%);
  border-radius: 50%;
  pointer-events: none;
  background:
    radial-gradient(circle, rgba(143, 186, 255, 0.32) 0%, rgba(74, 144, 226, 0.14) 38%, transparent 68%);
  filter: blur(14px);
  animation: preHaloPulse 3.2s ease-in-out infinite;
}

.preloader-logo-img {
  position: relative;
  display: block;
  width: auto;
  max-width: min(78vw, 360px);
  height: auto;
  max-height: clamp(180px, 34vh, 340px);
  object-fit: contain;
  margin: 0 auto;
  filter:
    brightness(1.18) saturate(1.12)
    drop-shadow(0 0 22px rgba(143, 186, 255, 0.55))
    drop-shadow(0 8px 40px rgba(74, 144, 226, 0.4));
  transform-origin: center;
  will-change: transform, filter, opacity;
  animation:
    preLogoIn 1.1s cubic-bezier(0.22, 1, 0.36, 1) both,
    preLogoFloat 4.5s ease-in-out 1.1s infinite,
    preLogoGlow 3.2s ease-in-out 1.1s infinite;
}

@keyframes preLogoIn {
  0% {
    opacity: 0;
    transform: scale(0.78) translateY(14px);
    filter: brightness(1.6) saturate(1.2) drop-shadow(0 0 40px rgba(143, 186, 255, 0.9));
  }
  100% {
    opacity: 1;
    transform: scale(1) translateY(0);
  }
}

@keyframes preLogoFloat {
  0%, 100% { transform: translateY(0); }
  50%      { transform: translateY(-10px); }
}

@keyframes preLogoGlow {
  0%, 100% {
    filter:
      brightness(1.14) saturate(1.1)
      drop-shadow(0 0 18px rgba(143, 186, 255, 0.45))
      drop-shadow(0 8px 34px rgba(74, 144, 226, 0.32));
  }
  50% {
    filter:
      brightness(1.28) saturate(1.18)
      drop-shadow(0 0 30px rgba(143, 186, 255, 0.8))
      drop-shadow(0 10px 48px rgba(74, 144, 226, 0.5));
  }
}

@keyframes preHaloPulse {
  0%, 100% { opacity: 0.55; transform: translate(-50%, -50%) scale(0.95); }
  50%      { opacity: 1;    transform: translate(-50%, -50%) scale(1.08); }
}

@media (prefers-reduced-motion: reduce) {
  .preloader-logo-img {
    animation: preLogoIn 0.6s ease both;
  }
  .preloader-logo-halo {
    animation: none;
  }
}

/* ── Preloader wordmark ── */
.preloader-wordmark {
  position: relative;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  margin: clamp(1.1rem, 2.4vw, 1.7rem) 0 0.55rem;
  padding: 0 0.2em;
  font-family: 'Montserrat', sans-serif;
  font-weight: 700;
  font-size: clamp(1.35rem, 4.2vw, 2.35rem);
  line-height: 1;
  letter-spacing: 0.24em;
  text-transform: uppercase;
  overflow: hidden;
}

.preloader-wordmark__letter {
  display: inline-block;
  background: linear-gradient(180deg, #ffffff 0%, #cfe2ff 55%, #7fa8ee 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  opacity: 0;
  transform: translateY(90%) scale(0.9);
  filter: blur(6px);
  will-change: transform, opacity, filter;
  animation: preWordIn 0.7s cubic-bezier(0.22, 1, 0.36, 1) forwards,
    preWordGlow 3.4s ease-in-out infinite;
  text-shadow: 0 0 18px rgba(143, 186, 255, 0.25);
}

.preloader-wordmark__letter--accent {
  background: linear-gradient(180deg, #eaf3ff 0%, #8fbaff 55%, #4a90e2 100%);
  -webkit-background-clip: text;
  background-clip: text;
}

.preloader-wordmark__space {
  display: inline-block;
  width: 0.5em;
}

.preloader-wordmark__shine {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    100deg,
    transparent 38%,
    rgba(255, 255, 255, 0.55) 50%,
    transparent 62%
  );
  transform: translateX(-130%);
  animation: preWordShine 3.6s ease-in-out 1.4s infinite;
  pointer-events: none;
  mix-blend-mode: screen;
}

@keyframes preWordIn {
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
    filter: blur(0);
  }
}

@keyframes preWordGlow {
  0%, 100% { text-shadow: 0 0 16px rgba(143, 186, 255, 0.2); }
  50% { text-shadow: 0 0 26px rgba(143, 186, 255, 0.55); }
}

@keyframes preWordShine {
  0% { transform: translateX(-130%); }
  55%, 100% { transform: translateX(130%); }
}

@media (prefers-reduced-motion: reduce) {
  .preloader-wordmark__letter {
    opacity: 1;
    transform: none;
    filter: none;
    animation: none;
  }

  .preloader-wordmark__shine {
    display: none;
  }
}

.preloader-tagline {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.85rem;
  margin: 1.15rem 0 0;
  font-family: 'Montserrat', sans-serif;
  font-size: clamp(0.72rem, 1.5vw, 0.82rem);
  font-weight: 600;
  letter-spacing: 0.28em;
  text-transform: uppercase;
  color: rgba(190, 220, 255, 0.92);
  text-shadow:
    0 0 22px rgba(100, 170, 255, 0.45),
    0 1px 0 rgba(0, 0, 0, 0.35);
  opacity: 0;
  animation: preTaglineIn 0.9s cubic-bezier(0.22, 1, 0.36, 1) 1.35s forwards;
}

.preloader-tagline__text {
  white-space: nowrap;
}

.preloader-tagline__rule {
  display: block;
  width: clamp(1.75rem, 4vw, 2.75rem);
  height: 1px;
  background: linear-gradient(
    90deg,
    transparent 0%,
    rgba(140, 195, 255, 0.85) 45%,
    rgba(200, 230, 255, 0.95) 50%,
    rgba(140, 195, 255, 0.85) 55%,
    transparent 100%
  );
  box-shadow: 0 0 10px rgba(100, 170, 255, 0.55);
  flex-shrink: 0;
}

@keyframes preTaglineIn {
  from {
    opacity: 0;
    transform: translateY(10px);
    letter-spacing: 0.4em;
  }
  to {
    opacity: 1;
    transform: translateY(0);
    letter-spacing: 0.28em;
  }
}

@media (prefers-reduced-motion: reduce) {
  .preloader-tagline {
    opacity: 1;
    animation: none;
  }
}

@media (max-width: 520px) {
  .preloader-tagline {
    letter-spacing: 0.16em;
    gap: 0.55rem;
  }

  .preloader-tagline__text {
    white-space: normal;
    max-width: 16rem;
    line-height: 1.45;
  }
}

.preloader-bar-wrap {
  position: absolute;
  bottom: 6%;
  left: 50%;
  transform: translateX(-50%);
  width: min(400px, 70%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.6rem;
}

.preloader-bar {
  width: 100%;
  height: 2px;
  background: rgba(255,255,255,0.08);
  border-radius: 2px;
  overflow: hidden;
}

.preloader-fill {
  height: 100%;
  border-radius: 2px;
  background: linear-gradient(90deg, #4a90e2, #8fbaff);
  transition: width 0.08s linear;
  box-shadow: 0 0 12px rgba(143,186,255,0.45);
}

.preloader-pct {
  font-family: 'Montserrat', sans-serif;
  font-size: 0.65rem;
  font-weight: 600;
  letter-spacing: 0.15em;
  color: rgba(255,255,255,0.3);
}

/* ── end Preloader ── */

* {
  box-sizing: border-box;
}

html {
  overflow-x: hidden;
  max-width: 100%;
  scroll-behavior: smooth;
  background: var(--bg);
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }
}

html,
body,
#root {
  margin: 0;
  min-height: 100%;
  min-height: 100dvh;
}

body,
#root {
  overflow-x: hidden;
  max-width: 100%;
  position: relative;
  background: var(--bg);
}

img,
video {
  max-width: 100%;
  height: auto;
}

body {
  font-family: 'Montserrat', sans-serif;
  color: var(--text);
}

/* Homepage (App): editorial display + refined UI type */
.home-page {
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-rendering: optimizeLegibility;
  font-feature-settings: 'kern' 1, 'liga' 1;
}

.home-page .nav-links a {
  font-family: 'Outfit', sans-serif;
  font-weight: 600;
  letter-spacing: 0.12em;
}

/* Home: marquee bar — glassy navy/gold bridge to photo hero (not bright blue strip) */
.home-page .marquee-wrap {
  background: linear-gradient(
    180deg,
    rgba(5, 10, 20, 0.94) 0%,
    rgba(10, 18, 34, 0.9) 42%,
    rgba(5, 8, 16, 0.96) 100%
  );
  backdrop-filter: blur(18px) saturate(1.2);
  -webkit-backdrop-filter: blur(18px) saturate(1.2);
  border-bottom: 1px solid rgba(197, 160, 89, 0.14);
  box-shadow:
    0 8px 28px rgba(0, 0, 0, 0.42),
    inset 0 1px 0 rgba(255, 255, 255, 0.05);
}

.home-page .marquee-row {
  min-height: 44px;
  padding: 0.35rem 0;
}

.home-page .marquee-overflow {
  mask-image: linear-gradient(
    90deg,
    transparent 0%,
    #000 8%,
    #000 92%,
    transparent 100%
  );
  -webkit-mask-image: linear-gradient(
    90deg,
    transparent 0%,
    #000 8%,
    #000 92%,
    transparent 100%
  );
}

.home-page .marquee-track {
  gap: 0.75rem;
  animation-duration: 22s;
}

.home-page .marquee-wrap .pill {
  padding: 0.4rem 1.05rem;
  border-radius: 999px;
  font-size: 0.6rem;
  font-weight: 600;
  letter-spacing: 0.13em;
  border: 1px solid rgba(255, 255, 255, 0.14);
  background: linear-gradient(
    155deg,
    rgba(255, 255, 255, 0.08) 0%,
    rgba(12, 22, 40, 0.45) 55%,
    rgba(4, 10, 22, 0.58) 100%
  );
  color: rgba(220, 230, 244, 0.9);
  text-shadow: none;
  box-shadow:
    0 2px 12px rgba(0, 0, 0, 0.2),
    inset 0 1px 0 rgba(255, 255, 255, 0.07);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  transition:
    border-color 0.28s ease,
    color 0.28s ease,
    box-shadow 0.28s ease;
}

.home-page .marquee-wrap .pill:hover {
  border-color: rgba(197, 160, 89, 0.42);
  color: rgba(255, 252, 245, 0.98);
  box-shadow:
    0 2px 16px rgba(0, 0, 0, 0.25),
    0 0 20px rgba(197, 160, 89, 0.08),
    inset 0 1px 0 rgba(255, 255, 255, 0.1);
}

/* Hero H1: optical alignment + clear two-line rhythm (Komodromos Group | of Companies) */
.home-page #home.hero-section {
  padding-top: clamp(5rem, 10vh, 7.5rem);
  min-height: 100vh;
  min-height: 100dvh;
}

/* Home hero: full-viewport cover image; .hero-content / scroll hint stay above (z-index) */
.home-page #home .hero-bg.hero-bg--static {
  background:
    radial-gradient(ellipse 110% 85% at 72% 18%, rgba(22, 52, 98, 0.4) 0%, transparent 55%),
    radial-gradient(ellipse 90% 65% at 18% 78%, rgba(197, 160, 89, 0.1) 0%, transparent 50%),
    linear-gradient(168deg, rgba(5, 10, 20, 0.35) 0%, rgba(5, 7, 10, 0.5) 45%, rgba(5, 10, 22, 0.55) 100%),
    url('/images/services/hero-section/hero-section-premium.webp') center / cover no-repeat #05070a;
}

.home-page #home .hero-content {
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: flex-start;
  align-items: center;
  min-height: 0;
  padding-block: clamp(0.5rem, 2vh, 1.25rem);
  padding-inline: clamp(0.75rem, 2.5vw, 1.5rem);
  text-align: center;
  box-sizing: border-box;
}

/* Headline + CTA: keep CTA in first viewport (no bottom anchoring) */
.home-page #home .hero-text {
  flex: 0 1 auto;
  display: flex;
  flex-direction: column;
  justify-content: flex-start;
  align-items: center;
  text-align: center;
  align-self: stretch;
  width: 100%;
  max-width: min(56rem, 100%);
  min-height: 0;
  margin: 0 auto;
  padding-top: clamp(0.5rem, 2vh, 1.25rem);
  box-sizing: border-box;
}

/* Home hero: frosted “KOMODROMOS GROUP / OF COMPANIES” block over the photo */
.home-page .hero-title-glass {
  display: flex;
  justify-content: center;
  align-items: center;
  width: 100%;
  max-width: min(44rem, 100%);
  margin-left: auto;
  margin-right: auto;
  font-weight: 400;
  line-height: 1.02;
  letter-spacing: 0.02em;
  text-align: center;
  box-sizing: border-box;
}

.home-page .hero-title-glass__inner {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  width: 100%;
  max-width: 38rem;
  margin-left: auto;
  margin-right: auto;
  gap: clamp(0.5rem, 1.6vh, 0.75rem);
  padding: clamp(1.5rem, 3.4vh, 2.4rem) clamp(1.75rem, 4.5vw, 3.25rem);
  box-sizing: border-box;
  background: linear-gradient(
    155deg,
    rgba(255, 255, 255, 0.1) 0%,
    rgba(12, 20, 36, 0.38) 45%,
    rgba(5, 10, 20, 0.48) 100%
  );
  border: 1px solid rgba(255, 255, 255, 0.16);
  border-radius: 18px;
  box-shadow:
    0 12px 40px rgba(0, 0, 0, 0.35),
    0 0 0 1px rgba(0, 0, 0, 0.2) inset,
    inset 0 1px 0 rgba(255, 255, 255, 0.1);
  backdrop-filter: blur(16px) saturate(1.25);
  -webkit-backdrop-filter: blur(16px) saturate(1.25);
}

@supports not ((backdrop-filter: blur(1px)) or (-webkit-backdrop-filter: blur(1px))) {
  .home-page .hero-title-glass__inner {
    background: rgba(8, 14, 26, 0.72);
  }
}

.home-page .hero-title-glass__kg {
  display: block;
  width: 100%;
  font-family: 'Playfair Display', 'Cormorant Garamond', Georgia, serif;
  font-size: clamp(2.75rem, 7.5vw, 4.25rem);
  font-weight: 500;
  letter-spacing: 0.04em;
  line-height: 1.1;
  text-transform: none;
  background: linear-gradient(
    165deg,
    rgba(255, 255, 255, 0.98) 0%,
    #f2e6d0 32%,
    #c5a059 70%,
    #9a7a42 100%
  );
  background-size: 140% 140%;
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

.home-page .hero-title-glass__line2 {
  display: block;
  width: 100%;
  font-family: 'Montserrat', system-ui, sans-serif;
  font-size: clamp(0.72rem, 1.9vw, 0.95rem);
  font-weight: 600;
  letter-spacing: 0.34em;
  text-transform: uppercase;
  color: rgba(230, 236, 248, 0.88);
}

/* Tablet: glass card and type scale for centered hero title */
@media (min-width: 640px) {
  .home-page .hero-title-glass {
    max-width: min(48rem, 100%);
  }

  .home-page .hero-title-glass__inner {
    max-width: 42rem;
    padding: clamp(1.65rem, 3.2vh, 2.1rem) clamp(2rem, 4vw, 2.75rem);
  }

  .home-page .hero-title-glass__kg {
    font-size: clamp(3rem, 4.2vw, 3.75rem);
  }
}

/* Desktop and large: full-width centering + larger headline */
@media (min-width: 1024px) {
  .home-page #home .hero-text {
    max-width: min(60rem, 100%);
  }

  .home-page .hero-title-glass {
    max-width: min(52rem, 100%);
  }

  .home-page .hero-title-glass__inner {
    max-width: 48rem;
    padding: 2.2rem 3.25rem 2.35rem;
    border-radius: 20px;
  }

  .home-page .hero-title-glass__kg {
    font-size: clamp(3.35rem, 3.6vw, 4.5rem);
  }

  .home-page .hero-title-glass__line2 {
    font-size: 0.88rem;
    letter-spacing: 0.3em;
  }
}

/* Desktop / tablet: scroll hint pinned to bottom of hero, centered, above fixed corner FABs */
@media (min-width: 641px) {
  .home-page #home .hero-cta-wrap,
  .home-page #home .hero-scroll-hint-wrap {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: flex-end;
    margin-top: auto;
    margin-left: auto;
    margin-right: auto;
    margin-bottom: 0;
    align-self: center;
    width: 100%;
    max-width: min(56rem, 100%);
    padding-top: 0.35rem;
