}

.home-page .hero-scroll-hint__chevG {
  transform-box: fill-box;
  transform-origin: 50% 0%;
  will-change: transform, opacity, filter;
  animation: heroScrollChevWave 1.05s cubic-bezier(0.38, 0, 0.2, 1) infinite;
}

.home-page .hero-scroll-hint__chevG--1 {
