.home-page .hero-scroll-hint__chevG--2 .hero-scroll-hint__chev {
  animation-delay: 0.12s;
}

.home-page .hero-scroll-hint__chevG--3 .hero-scroll-hint__chev {
  animation-delay: 0.24s;
}

/* Whole icon: light pulse (chevron groups do the main motion) */
@keyframes heroScrollHintBundle {
  0%,
  100% {
    transform: scale(1);
  }
  50% {
    transform: scale(1.07);
  }
}

/* Staggered “waterfall” down the chevrons */
@keyframes heroScrollChevWave {
  0%,
  100% {
    transform: translateY(0) scaleY(1);
    opacity: 0.6;
  }
  30% {
    transform: translateY(4px) scaleY(0.88);
    opacity: 0.85;
  }
  55% {
    transform: translateY(14px) scaleY(1.12);
    opacity: 1;
  }
  75% {
    transform: translateY(6px) scaleY(0.95);
    opacity: 0.9;
  }
}

@keyframes heroScrollChevGlow {
  0%,
  100% {
    opacity: 0.5;
  }
  50% {
    opacity: 1;
  }
}

