/* TaxNex Cyprus landing (/services/tax) — premium emerald & ivory */
.taxnex-root {
  --txg-950: #04261c;
  --txg-900: #063a2c;
  --txg-800: #0a4a3a;
  --txg-700: #0d5c46;
  --txg-500: #0f9d72;
  --txg-400: #34d399;
  --txg-mist: #ecfdf5;
  --txg-paper: #ffffff;
  --txg-premium-ink: #043d30;
  --txg-premium-heading: #044032;
  --txg-premium-body: #14523f;
  --txg-premium-muted: #2d6a4f;
  --txg-premium-accent: #0d9488;
  --taxnex-font-legacy: Arial, Helvetica, sans-serif;
  width: 100%;
  max-width: 100%;
  box-sizing: border-box;
  font-family: var(--taxnex-font-legacy);
  background:
    radial-gradient(ellipse 120% 85% at 50% -15%, rgba(167, 243, 208, 0.38) 0%, transparent 58%),
    radial-gradient(ellipse 65% 50% at 100% 25%, rgba(209, 250, 229, 0.55) 0%, transparent 48%),
    radial-gradient(ellipse 55% 45% at 0% 70%, rgba(204, 251, 241, 0.45) 0%, transparent 42%),
    linear-gradient(180deg, #fafdfb 0%, #f4fdf8 38%, #ecfdf5 72%, #e6fcf4 100%);
}

.taxnex-root *:not([class*='taxnex-']) {
  font-family: var(--taxnex-font-legacy) !important;
}

/* Taxisnet-style paragraph typography (txt10-like) — skip BEM paragraphs (hero, cards, etc.). */
.taxnex-root p:not([class*='taxnex-']) {
  font-family: Arial, Helvetica, sans-serif !important;
  font-size: 12px !important;
  font-weight: 400 !important;
  line-height: 1.4 !important;
  letter-spacing: 0 !important;
}

.taxnex-chrome {
  position: sticky;
  top: 72px;
  z-index: 23;
}

.page:has(.taxnex-root) .taxnex-chrome .tax-page-promo-bar {
  border-bottom-color: rgba(45, 212, 191, 0.28);
}

.taxnex-topbar {
  position: relative;
  z-index: 4;
  background: linear-gradient(180deg, #ffffff 0%, #f9fdfb 100%);
  border-bottom: 1px solid rgba(13, 148, 136, 0.2);
  box-shadow:
    0 1px 0 rgba(236, 253, 245, 0.98),
    0 8px 24px -12px rgba(6, 78, 59, 0.06);
}

.taxnex-topbar__inner.taxnex-topbar__inner--nav {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  column-gap: clamp(0.5rem, 1.5vw, 0.85rem);
  padding-left: max(0.5rem, env(safe-area-inset-left, 0px));
  padding-right: max(0.35rem, env(safe-area-inset-right, 0px));
}

.taxnex-topbar__actions {
  grid-column: 1;
  grid-row: 1;
  justify-self: start;
  z-index: 2;
  display: inline-flex;
  align-items: center;
  gap: clamp(0.35rem, 1vw, 0.55rem);
  flex-wrap: nowrap;
}

.taxnex-topbar__actions .lang-switch {
  flex-shrink: 0;
  border-color: rgba(45, 212, 191, 0.4);
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.96) 0%, rgba(236, 253, 245, 0.92) 100%);
  box-shadow:
    0 8px 18px rgba(6, 78, 59, 0.1),
    0 0 0 1px rgba(255, 255, 255, 0.7) inset;
}

.taxnex-topbar__actions .lang-switch__btn {
  color: #0f513d;
}

.taxnex-topbar__actions .lang-switch__btn:hover,
.taxnex-topbar__actions .lang-switch__btn:focus-visible {
  color: #04261c;
  background: rgba(167, 243, 208, 0.35);
}

.taxnex-topbar__actions .lang-switch__btn--active {
  background:
    linear-gradient(120deg, rgba(255, 255, 255, 0.38) 0%, rgba(255, 255, 255, 0) 40%),
    linear-gradient(180deg, rgba(167, 243, 208, 0.95) 0%, rgba(110, 231, 183, 0.9) 100%);
  color: #022c22;
  box-shadow:
    0 8px 16px rgba(6, 95, 70, 0.18),
    0 0 0 1px rgba(255, 255, 255, 0.72) inset;
}

.taxnex-topbar__inner--nav .taxnex-topbar__address {
  grid-column: 1 / -1;
  grid-row: 1;
  justify-self: center;
  max-width: min(48rem, calc(100% - 14rem));
}

.taxnex-topbar__inner--nav .taxnex-topbar__socials {
  grid-column: 3;
  grid-row: 1;
  justify-self: end;
  z-index: 2;
}

.taxnex-nav__toggle {
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  gap: 0.5rem;
  min-height: 2.35rem;
  padding: 0.35rem 0.7rem 0.35rem 0.55rem;
  border-radius: 10px;
  border: 1px solid rgba(13, 148, 136, 0.38);
  background: linear-gradient(180deg, #ffffff 0%, #ecfdf5 100%);
  color: #0f766e;
  cursor: pointer;
  box-shadow:
    0 4px 14px rgba(6, 95, 70, 0.12),
    inset 0 1px 0 rgba(255, 255, 255, 0.9);
  transition:
    border-color 0.22s ease,
    background 0.22s ease,
    box-shadow 0.22s ease;
}

.taxnex-nav__toggle:hover,
.taxnex-nav__toggle:focus-visible {
  border-color: rgba(13, 148, 136, 0.55);
  background: linear-gradient(180deg, #f0fdf9 0%, #d1fae5 100%);
  box-shadow: 0 6px 18px rgba(6, 95, 70, 0.18);
}

.taxnex-nav__toggle-label {
  font-family: 'Montserrat', sans-serif;
  font-size: 0.62rem;
  font-weight: 800;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  line-height: 1;
  white-space: nowrap;
}

.taxnex-nav__toggle-icon {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 4px;
  width: 1.15rem;
  height: 1rem;
}

.taxnex-nav__toggle-icon span {
  display: block;
  width: 100%;
  height: 2px;
  border-radius: 2px;
  background: #0f766e;
  transition:
    transform 0.28s cubic-bezier(0.22, 1, 0.36, 1),
    opacity 0.2s ease;
  transform-origin: center;
}

.taxnex-nav__toggle--open .taxnex-nav__toggle-icon span:nth-child(1) {
  transform: translateY(6px) rotate(45deg);
}

.taxnex-nav__toggle--open .taxnex-nav__toggle-icon span:nth-child(2) {
  opacity: 0;
}

.taxnex-nav__toggle--open .taxnex-nav__toggle-icon span:nth-child(3) {
  transform: translateY(-6px) rotate(-45deg);
}

.taxnex-nav__backdrop {
  position: fixed;
  inset: 0;
  z-index: 200;
  border: 0;
  margin: 0;
  padding: 0;
  background:
    radial-gradient(ellipse 60% 50% at 20% 20%, rgba(13, 148, 136, 0.22) 0%, transparent 55%),
    rgba(2, 18, 14, 0.55);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.35s ease;
}

.taxnex-nav__backdrop--visible {
  opacity: 1;
  pointer-events: auto;
}

.taxnex-nav__panel {
  --tx-nav-ink: #043d30;
  --tx-nav-teal: #0f766e;
  --tx-nav-bright: #14b8a6;
  position: fixed;
  top: 0;
  left: 0;
  z-index: 201;
  display: flex;
  flex-direction: column;
  width: min(100vw, 22.5rem);
  max-width: 100%;
  height: 100dvh;
  padding:
    max(0.9rem, env(safe-area-inset-top, 0px))
    max(1rem, env(safe-area-inset-right, 0px))
    max(1.15rem, env(safe-area-inset-bottom, 0px))
    max(1rem, env(safe-area-inset-left, 0px));
  box-sizing: border-box;
  border-right: 1px solid rgba(45, 212, 191, 0.28);
  background:
    radial-gradient(ellipse 90% 40% at 0% 0%, rgba(45, 212, 191, 0.16) 0%, transparent 55%),
    radial-gradient(ellipse 70% 35% at 100% 100%, rgba(16, 185, 129, 0.12) 0%, transparent 50%),
    linear-gradient(168deg, #ffffff 0%, #f0fdf9 38%, #ecfdf5 72%, #e6faf3 100%);
  box-shadow:
    16px 0 48px rgba(4, 40, 32, 0.22),
    inset 0 1px 0 rgba(255, 255, 255, 0.85);
  overflow: hidden;
  animation: taxnexNavPanelIn 0.42s cubic-bezier(0.22, 1, 0.36, 1) both;
}

.taxnex-nav__panel--open {
  transform: none;
}

.taxnex-nav__panel::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: linear-gradient(
    90deg,
    transparent 0%,
    rgba(20, 184, 166, 0.35) 12%,
    rgba(45, 212, 191, 0.95) 50%,
    rgba(20, 184, 166, 0.35) 88%,
    transparent 100%
  );
  pointer-events: none;
}

.taxnex-nav__panel-head {
  position: relative;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.85rem;
  margin-bottom: 1.05rem;
  padding: 0.15rem 0 0.95rem;
  border-bottom: 1px solid rgba(13, 148, 136, 0.18);
}

.taxnex-nav__panel-brand {
  display: flex;
  flex-direction: column;
  gap: 0.28rem;
  min-width: 0;
}

.taxnex-nav__panel-eyebrow {
  font-family: 'Playfair Display', 'Cormorant Garamond', Georgia, serif;
  font-size: 1.15rem;
  font-weight: 700;
  letter-spacing: 0.02em;
  line-height: 1.1;
  color: var(--tx-nav-ink);
}

.taxnex-nav__panel-title {
  margin: 0;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--tx-nav-teal);
}

.taxnex-nav__close {
  position: relative;
  display: grid;
  place-items: center;
  flex-shrink: 0;
  width: 2.35rem;
  height: 2.35rem;
  border: 1px solid rgba(13, 148, 136, 0.28);
  border-radius: 12px;
  background:
    linear-gradient(160deg, rgba(255, 255, 255, 0.98) 0%, rgba(236, 253, 245, 0.95) 100%);
  color: var(--tx-nav-teal);
  cursor: pointer;
  box-shadow:
    0 6px 16px rgba(6, 95, 70, 0.1),
    inset 0 1px 0 rgba(255, 255, 255, 0.9);
  transition:
    border-color 0.22s ease,
    background 0.22s ease,
    transform 0.22s ease,
    box-shadow 0.22s ease;
}

.taxnex-nav__close span {
  position: absolute;
  width: 0.95rem;
  height: 1.5px;
  border-radius: 2px;
  background: currentColor;
}

.taxnex-nav__close span:first-child {
  transform: rotate(45deg);
}

.taxnex-nav__close span:last-child {
  transform: rotate(-45deg);
}

.taxnex-nav__close:hover,
.taxnex-nav__close:focus-visible {
  border-color: rgba(13, 148, 136, 0.5);
  background: linear-gradient(160deg, #ecfdf5 0%, #d1fae5 100%);
  transform: scale(1.04);
  box-shadow: 0 8px 20px rgba(6, 95, 70, 0.16);
}

.taxnex-nav__links {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: 0.42rem;
  min-height: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
  padding-right: 0.15rem;
  scrollbar-width: thin;
  scrollbar-color: rgba(13, 148, 136, 0.35) transparent;
}

.taxnex-nav__link {
  --nav-i: 0;
  position: relative;
  display: flex;
  align-items: center;
  min-height: 2.75rem;
  padding: 0.6rem 0.9rem;
  border-radius: 12px;
  border: 1px solid rgba(16, 185, 129, 0.2);
  background:
    linear-gradient(145deg, rgba(255, 255, 255, 0.96) 0%, rgba(240, 253, 249, 0.88) 100%);
  font-family: 'Montserrat', sans-serif;
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  text-decoration: none;
  line-height: 1.3;
  color: var(--tx-nav-ink);
  box-shadow:
    0 4px 12px rgba(6, 78, 59, 0.05),
    inset 0 1px 0 rgba(255, 255, 255, 0.85);
  opacity: 0;
  transform: translateX(-12px);
  animation: taxnexNavLinkIn 0.45s cubic-bezier(0.22, 1, 0.36, 1) forwards;
  animation-delay: calc(0.05s + (var(--nav-i) * 0.035s));
  transition:
    background 0.25s ease,
    border-color 0.25s ease,
    transform 0.25s cubic-bezier(0.22, 1, 0.36, 1),
    box-shadow 0.25s ease,
    color 0.25s ease;
}

.taxnex-nav__link::before {
  content: '';
  position: absolute;
  left: 0;
  top: 20%;
  bottom: 20%;
  width: 3px;
  border-radius: 0 3px 3px 0;
  background: linear-gradient(180deg, #2dd4bf, #0d9488);
  opacity: 0;
  transform: scaleY(0.4);
  transition:
    opacity 0.25s ease,
    transform 0.25s ease;
}

.taxnex-nav__link-label {
  position: relative;
  z-index: 1;
}

.taxnex-nav__link:hover,
.taxnex-nav__link:focus-visible {
  border-color: rgba(13, 148, 136, 0.42);
  background:
    linear-gradient(145deg, #ffffff 0%, #d1fae5 100%);
  color: #022c22;
  transform: translateX(4px);
  box-shadow:
    0 8px 20px rgba(6, 95, 70, 0.12),
    inset 0 1px 0 rgba(255, 255, 255, 0.95);
}

.taxnex-nav__link:hover::before,
.taxnex-nav__link:focus-visible::before {
  opacity: 1;
  transform: scaleY(1);
}

.taxnex-nav__link--cta {
  margin-top: 0.35rem;
  border-color: rgba(6, 95, 70, 0.4);
  background:
    linear-gradient(120deg, rgba(255, 255, 255, 0.18) 0%, transparent 42%),
    linear-gradient(145deg, #14b8a6 0%, #0d9488 42%, #059669 78%, #047857 100%);
  color: #ffffff;
  box-shadow:
    0 12px 28px rgba(6, 95, 70, 0.28),
    inset 0 1px 0 rgba(255, 255, 255, 0.28);
}

.taxnex-nav__link--cta::before {
  display: none;
}

.taxnex-nav__link--cta:hover,
.taxnex-nav__link--cta:focus-visible {
  color: #ffffff;
  background:
    linear-gradient(120deg, rgba(255, 255, 255, 0.22) 0%, transparent 42%),
    linear-gradient(145deg, #0f766e 0%, #0d9488 45%, #047857 100%);
  transform: translateX(4px);
  box-shadow:
    0 16px 32px rgba(6, 95, 70, 0.34),
    inset 0 1px 0 rgba(255, 255, 255, 0.32);
}

.taxnex-nav__link--sub {
  min-height: 2.45rem;
  font-size: 0.64rem;
  letter-spacing: 0.06em;
  text-transform: none;
  font-weight: 600;
  color: #065f46;
}

.taxnex-nav__group {
  margin-top: 0.55rem;
  padding-top: 0.75rem;
  border-top: 1px solid rgba(13, 148, 136, 0.16);
}

.taxnex-nav__group-label {
  margin: 0 0 0.55rem;
  padding-inline: 0.25rem;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.6rem;
  font-weight: 800;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--tx-nav-teal);
}

.taxnex-nav__group-links {
  display: flex;
  flex-direction: column;
  gap: 0.38rem;
}

.taxnex-nav__lang {
  margin-top: auto;
  padding-top: 1rem;
  display: flex;
  justify-content: center;
}

@keyframes taxnexNavPanelIn {
  from {
    opacity: 0.72;
    transform: translateX(-104%);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

@keyframes taxnexNavLinkIn {
