  .taxnex-nav__link {
    animation: none;
    opacity: 1;
    transform: none;
  }

  .taxnex-nav__link:hover,
  .taxnex-nav__link:focus-visible,
  .taxnex-nav__link--cta:hover,
  .taxnex-nav__link--cta:focus-visible,
