}

.taxnex-topbar__inner {
  display: flex;
  min-height: 2.45rem;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 0.65rem 0.85rem;
  padding: 0.5rem 1rem;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.61rem;
  font-weight: 600;
