  height: clamp(30px, 3.2vw, 38px);
}

.taxnex-services-scroll-rail--right .taxnex-services-scroll-rail__chevs {
  animation-delay: 0.32s;
}

.taxnex-services-scroll-rail__chevs--tail {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.06rem;
  margin-top: 0.15rem;
  opacity: 0.95;
  filter:
    drop-shadow(0 4px 20px rgba(16, 185, 129, 0.82))
    drop-shadow(0 0 14px rgba(52, 211, 153, 0.5))
    drop-shadow(0 2px 0 rgba(255, 255, 255, 0.95));
