.taxnex-office-root .taxnex-btn--primary {
  color: #031910;
  background: linear-gradient(148deg, #d1fae5 0%, #6ee7b7 22%, #14b8a6 52%, #059669 88%, #047857 100%);
  border: 1px solid rgba(167, 243, 208, 0.65);
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.55) inset,
    0 16px 42px rgba(0, 48, 36, 0.45),
    0 0 0 1px rgba(52, 211, 153, 0.35);
  animation: taxnex-pay-led-blobs 2.85s ease-in-out infinite;
  transition:
    transform 0.32s cubic-bezier(0.22, 1, 0.36, 1),
    background 0.32s ease,
    border-color 0.32s ease,
    box-shadow 0.32s ease,
    color 0.32s ease,
    filter 0.32s ease;
}

.taxnex-office-root .taxnex-btn--primary::before {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: linear-gradient(
    105deg,
    transparent 0%,
    rgba(255, 255, 255, 0.45) 42%,
    transparent 58%
  );
  transform: translateX(-120%);
  transition: transform 0.55s cubic-bezier(0.22, 1, 0.36, 1);
  pointer-events: none;
}

.taxnex-office-root .taxnex-btn--primary:hover::before,
.taxnex-office-root .taxnex-btn--primary:focus-visible::before {
  transform: translateX(120%);
}

.taxnex-office-root .taxnex-office-plan:nth-child(1) .taxnex-btn--primary,
.taxnex-office-root .taxnex-regco-duo-card:nth-child(1) .taxnex-btn--primary {
  animation-delay: 0s;
}

.taxnex-office-root .taxnex-office-plan:nth-child(2) .taxnex-btn--primary {
  animation-delay: 0.38s;
}

.taxnex-office-root .taxnex-office-plan:nth-child(3) .taxnex-btn--primary {
  animation-delay: 0.76s;
}

.taxnex-office-root .taxnex-office-flex__cta.taxnex-btn--primary {
  animation-delay: 0.2s;
}

.taxnex-office-root .taxnex-btn--primary:hover,
.taxnex-office-root .taxnex-btn--primary:focus-visible {
  animation: none;
  transform: translateY(-5px) scale(1.03);
  background: linear-gradient(148deg, #ecfdf5 0%, #6ee7b7 26%, #10b981 56%, #047857 100%);
  border-color: rgba(236, 253, 245, 0.9);
  color: #021a12;
