    border-color 0.32s ease,
    box-shadow 0.32s ease,
    color 0.32s ease,
    filter 0.32s ease;
}

@keyframes taxnex-office-outline-glow {
  0%,
  100% {
    box-shadow:
      0 1px 0 rgba(255, 255, 255, 0.9) inset,
      0 12px 28px -10px rgba(6, 78, 59, 0.2),
      0 0 0 1px rgba(52, 211, 153, 0.35),
