  isolation: isolate;
  background:
    radial-gradient(ellipse 100% 70% at 0% 0%, rgba(55, 130, 210, 0.22) 0%, transparent 55%),
    radial-gradient(ellipse 90% 60% at 100% 15%, rgba(40, 100, 180, 0.18) 0%, transparent 52%),
    radial-gradient(ellipse 80% 50% at 50% 100%, rgba(197, 160, 89, 0.1) 0%, transparent 55%),
    linear-gradient(
      168deg,
      #02050c 0%,
      #05152a 14%,
      #071c38 32%,
      #061428 55%,
      #04121f 78%,
      #02060d 100%
    );
}

.home-page #services::before {
  content: '';
  position: absolute;
  inset: -12% -8% -8% -8%;
  z-index: 0;
  pointer-events: none;
  background:
    radial-gradient(ellipse 55% 40% at 18% 28%, rgba(100, 190, 255, 0.32) 0%, transparent 58%),
    radial-gradient(ellipse 48% 46% at 78% 62%, rgba(197, 160, 89, 0.22) 0%, transparent 55%),
    radial-gradient(ellipse 42% 36% at 45% 48%, rgba(60, 140, 220, 0.2) 0%, transparent 50%);
  filter: blur(1px);
  animation: homeServicesBgAura 20s ease-in-out infinite alternate;
}

.home-page #services::after {
  content: '';
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  background: linear-gradient(
    180deg,
    rgba(2, 5, 12, 0) 0%,
    rgba(5, 18, 38, 0.35) 48%,
    rgba(1, 3, 8, 0.2) 100%
  );
  opacity: 0.85;
}

.home-page #services > .container {
  position: relative;
  z-index: 1;
}

@keyframes homeServicesBgAura {
  0% {
    transform: translate(0, 0) scale(1);
    opacity: 0.92;
  }
  25% {
    transform: translate(2.5%, 1.2%) scale(1.04);
  }
  50% {
    transform: translate(-1.5%, 2.5%) scale(1.02);
  }
  75% {
    transform: translate(1.8%, -1.2%) scale(1.05);
  }
  100% {
    transform: translate(0, 0) scale(1);
    opacity: 1;
  }
}

@media (prefers-reduced-motion: reduce) {
  .home-page #services::before {
    animation: none;
  }
}

.service-list {
  display: grid;
  gap: clamp(1.7rem, 2.8vw, 2.35rem);
}

.service-card {
  position: relative;
  isolation: isolate;
  border: 1px solid rgba(120, 166, 210, 0.34);
  background: linear-gradient(160deg, rgba(8, 16, 30, 0.97) 0%, rgba(4, 9, 18, 0.99) 100%);
  border-radius: 14px;
  overflow: hidden;
  box-shadow:
    0 12px 38px rgba(0, 0, 0, 0.32),
    0 0 0 1px rgba(255, 255, 255, 0.03) inset;
  transition:
    border-color 0.45s cubic-bezier(0.22, 1, 0.36, 1),
    box-shadow 0.45s cubic-bezier(0.22, 1, 0.36, 1);
}

/* Service cards: stronger entrance (blur + 3D) + merged transitions; scoped so contact-card reveal-scale stays default. */
.service-list .service-card.reveal-scale {
  opacity: 0;
  transform: perspective(1200px) translateY(72px) scale(0.88) rotateX(9deg);
  transform-origin: center top;
  filter: blur(12px);
  transition:
    opacity 1.1s cubic-bezier(0.22, 1, 0.36, 1),
    transform 1.1s cubic-bezier(0.22, 1, 0.36, 1),
    filter 1s cubic-bezier(0.22, 1, 0.36, 1),
    border-color 0.45s cubic-bezier(0.22, 1, 0.36, 1),
    box-shadow 0.45s cubic-bezier(0.22, 1, 0.36, 1);
}

.service-list .service-card.reveal-scale.revealed {
  opacity: 1;
  transform: perspective(1200px) translateY(0) scale(1) rotateX(0deg);
  filter: blur(0);
}

.service-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 2px;
  z-index: 3;
  background: linear-gradient(
    90deg,
    transparent 0%,
    rgba(90, 155, 220, 0.15) 25%,
    rgba(185, 225, 255, 0.95) 50%,
    rgba(90, 155, 220, 0.15) 75%,
    transparent 100%
  );
  background-size: 240% 100%;
  animation: serviceCardTopScan 5s ease-in-out infinite;
  opacity: 0.9;
  pointer-events: none;
}

.service-card::after {
  content: '';
  position: absolute;
  inset: 0;
  z-index: 1;
  background:
    radial-gradient(80% 56% at 8% 16%, rgba(165, 200, 232, 0.13) 0%, transparent 62%),
    radial-gradient(70% 52% at 92% 84%, rgba(200, 169, 106, 0.1) 0%, transparent 64%);
  opacity: 0.7;
  transform: scale(1.08);
  transition:
    opacity 0.45s cubic-bezier(0.22, 1, 0.36, 1),
    transform 0.7s cubic-bezier(0.22, 1, 0.36, 1);
  pointer-events: none;
}

@keyframes serviceCardTopScan {
  0%,
  100% {
    background-position: 0% 50%;
  }
  50% {
    background-position: 100% 50%;
  }
}

.service-list .service-card.reveal-scale:nth-child(1) {
  transition-delay: 0.06s;
}
.service-list .service-card.reveal-scale:nth-child(2) {
  transition-delay: 0.14s;
}
.service-list .service-card.reveal-scale:nth-child(3) {
  transition-delay: 0.22s;
}
.service-list .service-card.reveal-scale:nth-child(4) {
  transition-delay: 0.3s;
}
.service-list .service-card.reveal-scale:nth-child(5) {
  transition-delay: 0.38s;
}
.service-list .service-card.reveal-scale:nth-child(6) {
  transition-delay: 0.46s;
}
.service-list .service-card.reveal-scale:nth-child(7) {
  transition-delay: 0.54s;
}
.service-list .service-card.reveal-scale:nth-child(8) {
  transition-delay: 0.62s;
}
.service-list .service-card.reveal-scale:nth-child(9) {
  transition-delay: 0.7s;
}
.service-list .service-card.reveal-scale:nth-child(10) {
  transition-delay: 0.78s;
}
.service-list .service-card.reveal-scale:nth-child(11) {
  transition-delay: 0.86s;
}

