}

@media (prefers-reduced-motion: reduce) {
  .service-card::before {
    animation: none;
    background: linear-gradient(
      90deg,
      transparent,
      rgba(165, 215, 255, 0.5),
      transparent
    );
    background-size: 100% 100%;
    opacity: 0.65;
  }

  .service-card:hover::before {
    animation: none;
  }

  .service-card::after,
  .service-card:hover::after {
    transform: none;
    opacity: 0.85;
  }

  .service-card.reveal-scale.revealed:hover {
    transform: scale(1);
    filter: none;
  }

  .service-card:hover .service-img {
    transform: none;
  }

  .service-card:hover .service-card-badge {
    transform: none;
  }

  .service-card:hover .service-text h3,
  .service-card:hover .service-text > p:not(.service-eyebrow),
  .service-card:hover .service-text .tags,
  .service-card:hover .service-text .action {
    transform: none;
  }

  .service-list .service-card.reveal-scale {
    transition-delay: 0s !important;
    filter: none;
    transform: scale(0.97);
  }

  .service-list .service-card.reveal-scale.revealed {
    transform: scale(1);
  }
}

