/* ── Hamburger ── */

.nav-backdrop {
  display: none;
}

.hamburger {
  display: none;
  background: none;
  border: none;
  padding: 6px;
  cursor: pointer;
  flex-direction: column;
  gap: 5px;
  z-index: 52;
}

.hamburger span {
  display: block;
  width: 24px;
  height: 2px;
  background: #fff;
  border-radius: 2px;
  transition: transform 0.35s cubic-bezier(0.4, 0, 0.2, 1),
              opacity 0.25s;
  transform-origin: center;
}

.hamburger-open span:nth-child(1) {
  transform: translateY(7px) rotate(45deg);
}

.hamburger-open span:nth-child(2) {
  opacity: 0;
}

.hamburger-open span:nth-child(3) {
  transform: translateY(-7px) rotate(-45deg);
}

.nav-mobile-socials,
.nav-mobile-header {
  display: none;
}

@media (max-width: 980px) {
  .nav-backdrop {
    display: block;
    position: fixed;
    inset: 0;
    z-index: 50;
    margin: 0;
    padding: 0;
    border: none;
    background: rgba(2, 6, 14, 0.62);
    backdrop-filter: blur(4px);
    -webkit-backdrop-filter: blur(4px);
    opacity: 0;
    visibility: hidden;
    pointer-events: none;
    cursor: pointer;
    transition:
      opacity 0.35s ease,
      visibility 0s linear 0.35s;
  }

  .nav-backdrop.nav-backdrop--open {
    opacity: 1;
    visibility: visible;
    pointer-events: auto;
    transition: visibility 0s linear 0s;
  }

  .hamburger {
    display: flex;
