/* ── Floating Social Hub ── */

.social-hub {
  position: fixed;
  right: 1.25rem;
  bottom: 1.25rem;
  z-index: 9986;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 0.75rem;
  font-family: 'Montserrat', system-ui, sans-serif;
  pointer-events: none;
}

.social-hub > * {
  pointer-events: auto;
}

.social-hub-backdrop {
  position: fixed;
  inset: 0;
  z-index: 9984;
  border: none;
  padding: 0;
  margin: 0;
  background: rgba(2, 6, 14, 0.55);
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
  cursor: pointer;
  animation: socialHubFadeIn 0.35s ease forwards;
}

@keyframes socialHubFadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

.social-hub-panel {
  position: relative;
  z-index: 9985;
  width: min(320px, calc(100vw - 2.5rem));
  max-height: min(70vh, 520px);
  overflow: auto;
  padding: 1.35rem 1.35rem 1.15rem;
  border-radius: 16px;
  background: linear-gradient(
    155deg,
    rgba(14, 24, 44, 0.97) 0%,
    rgba(6, 12, 24, 0.98) 45%,
    rgba(8, 16, 32, 0.96) 100%
  );
  border: 1px solid rgba(120, 165, 210, 0.22);
  box-shadow:
    0 24px 60px rgba(0, 0, 0, 0.55),
    0 0 0 1px rgba(255, 255, 255, 0.04) inset,
    0 -1px 40px rgba(74, 144, 226, 0.08);
  backdrop-filter: blur(20px) saturate(1.3);
  -webkit-backdrop-filter: blur(20px) saturate(1.3);
  opacity: 0;
  visibility: hidden;
  transform: translateY(12px) scale(0.96);
  transform-origin: bottom right;
  transition:
    opacity 0.4s cubic-bezier(0.16, 1, 0.3, 1),
    transform 0.45s cubic-bezier(0.16, 1, 0.3, 1),
    visibility 0.45s;
  pointer-events: none;
}

.social-hub--open .social-hub-panel {
  opacity: 1;
  visibility: visible;
  transform: translateY(0) scale(1);
  pointer-events: auto;
}

.social-hub-panel::before {
  content: '';
  position: absolute;
  top: 0;
  left: 10%;
  right: 10%;
  height: 1px;
  background: linear-gradient(
    90deg,
    transparent,
    rgba(197, 160, 89, 0.25),
    rgba(165, 200, 232, 0.35),
    rgba(197, 160, 89, 0.25),
    transparent
  );
  border-radius: 1px;
}

.social-hub-panel-head {
  margin: 0 0 1.1rem;
  padding-bottom: 1rem;
  border-bottom: 1px solid rgba(100, 140, 180, 0.12);
  position: relative;
}

.social-hub-panel-head::after {
  content: '';
  position: absolute;
  bottom: -1px;
  left: 0;
  width: 42%;
  height: 1px;
  background: linear-gradient(
    90deg,
    rgba(197, 160, 89, 0.55),
    rgba(120, 175, 230, 0.35),
    transparent
  );
  border-radius: 1px;
  opacity: 0.85;
}

.social-hub-eyebrow {
  margin: 0 0 0.55rem;
  font-family: 'Outfit', sans-serif;
  font-size: 0.58rem;
  font-weight: 700;
  letter-spacing: 0.42em;
  text-transform: uppercase;
  color: var(--service-light-blue);
  text-shadow: 0 0 22px rgba(120, 175, 220, 0.35);
}

.social-hub-heading {
  margin: 0 0 0.55rem;
  font-family: 'Outfit', sans-serif;
  font-size: clamp(0.78rem, 2.8vw, 0.88rem);
  font-weight: 800;
  letter-spacing: 0.42em;
  text-transform: uppercase;
  line-height: 1.35;
}

.social-hub-heading-gradient {
  display: inline-block;
  background: linear-gradient(
    105deg,
    #eaf4fc 0%,
    var(--service-light-blue-hover) 28%,
    #8eb8dc 52%,
    var(--service-light-blue) 72%,
    #d8ebf8 100%
  );
  background-size: 220% 100%;
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  filter: drop-shadow(0 1px 14px rgba(140, 185, 228, 0.35));
  animation: socialHubHeadingFlow 10s ease-in-out infinite;
}

.social-hub-sub {
  margin: 0;
  font-size: 0.76rem;
  line-height: 1.55;
  font-weight: 500;
  letter-spacing: 0.02em;
}

.social-hub-sub-muted {
  color: rgba(168, 184, 206, 0.88);
}

.social-hub-sub-brand {
  font-family: 'Playfair Display', serif;
  font-style: italic;
  font-weight: 600;
  font-size: 0.84rem;
  letter-spacing: 0.02em;
  background: linear-gradient(
    125deg,
    #f0f7fc 0%,
    var(--service-light-blue) 38%,
    #7ba8d4 62%,
    var(--service-light-blue-hover) 85%,
    #dceaf6 100%
  );
  background-size: 200% 120%;
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  animation: socialHubBrandGlow 12s ease-in-out infinite;
}

@keyframes socialHubHeadingFlow {
  0%, 100% {
    background-position: 0% 50%;
  }
  50% {
    background-position: 100% 50%;
  }
}

@keyframes socialHubBrandGlow {
  0%, 100% {
    background-position: 0% 40%;
    filter: brightness(1);
  }
  33% {
    background-position: 70% 60%;
    filter: brightness(1.06);
  }
  66% {
    background-position: 100% 40%;
    filter: brightness(1.03);
  }
}

@media (prefers-reduced-motion: reduce) {
  .social-hub-heading-gradient,
  .social-hub-sub-brand {
    animation: none;
    background-position: 35% 50%;
  }
}

