@keyframes social-hub-fab-float {
  0%,
  100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-10px);
  }
}

.social-hub-fab {
  position: relative;
  z-index: 9986;
  font-family: inherit;
  font-size: 18px;
  display: grid;
  grid-template-columns: auto 0fr;
  align-items: center;
  justify-content: center;
  column-gap: 0;
  width: auto;
  min-height: 0;
  padding: 0.8em 1.2em;
  border: none;
  border-radius: 16px;
  cursor: pointer;
  color: #fff;
  background: linear-gradient(
    90deg,
    #1877f0 0%,
    #1d5df7 50%,
    #0e3dc8 100%
  );
  box-shadow:
    0 5px 10px rgba(0, 0, 0, 0.2),
    0 0 0 1px rgba(197, 160, 89, 0.38) inset;
  transition:
    transform 0.3s ease,
    grid-template-columns 0.3s ease,
    box-shadow 0.3s ease;
  animation: social-hub-fab-float 2.8s ease-in-out infinite;
}

.social-hub-fab:hover {
  animation: none;
  transform: translateY(-3px);
  grid-template-columns: auto 1fr;
  box-shadow:
    0 8px 15px rgba(0, 0, 0, 0.3),
    0 0 0 1px rgba(197, 160, 89, 0.45) inset;
}

.social-hub-fab:active {
  animation: none;
  transform: scale(0.95);
}

.social-hub--open .social-hub-fab {
  animation: none;
  transform: translateY(0);
  grid-template-columns: auto 1fr;
  background: linear-gradient(90deg, #1877f0 0%, #1d5df7 50%, #0e3dc8 100%);
  box-shadow:
    0 8px 15px rgba(0, 0, 0, 0.3),
    0 0 0 1px rgba(197, 160, 89, 0.45) inset;
}

.social-hub-fab-inner {
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  border-radius: 50%;
  background-color: rgba(255, 255, 255, 0.2);
  flex-shrink: 0;
  transition:
    all 0.3s ease;
}

.social-hub-fab-icon {
  position: relative;
  width: 22px;
  height: 22px;
  transition: all 0.3s ease;
}

.social-hub-fab:hover .social-hub-fab-inner {
  background-color: rgba(255, 255, 255, 0.5);
  margin-right: 0.5em;
  animation: socialHubFabBounce 1.2s ease-in-out;
}

@keyframes socialHubFabBounce {
  0%,
  100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-8px);
  }
}

.social-hub-fab-text {
  overflow: hidden;
  display: block;
  margin-left: 0.4em;
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  white-space: nowrap;
  transition: all 0.3s ease;
}

@media (max-width: 520px) {
  .social-hub-fab {
    padding: 0.75rem;
    border-radius: 50%;
    grid-template-columns: auto 0fr;
  }

  .social-hub-fab:hover,
  .social-hub--open .social-hub-fab {
    grid-template-columns: auto 0fr;
  }

  .social-hub-fab-text {
    display: none;
