.storage-features-wrap {
  margin: clamp(2.5rem, 6vw, 3.75rem) auto 0;
  width: 100%;
  max-width: min(1260px, 100%);
}

/* Break out of .container so the collage uses full viewport width */
.storage-parallax-bleed {
  width: 100vw;
  max-width: 100vw;
  margin-left: calc(50% - 50vw);
  margin-right: calc(50% - 50vw);
  position: relative;
}

#storage-parallax,
#storage-offers,
#storage-extra-services,
#storage-features,
#storage-rates,
#storage-tips,
#storage-contact {
  scroll-margin-top: calc(72px + 52px + 0.85rem);
}

@media (max-width: 640px) {
  #storage-parallax,
  #storage-offers,
  #storage-extra-services,
  #storage-features,
  #storage-rates,
  #storage-tips,
  #storage-contact {
    scroll-margin-top: calc(64px + 52px + 0.75rem);
  }
}

.storage-features-heading {
  font-family: 'Montserrat', sans-serif;
  font-weight: 700;
  font-size: clamp(1.15rem, 2.2vw, 1.45rem);
  letter-spacing: 0.06em;
  text-align: center;
  color: rgba(255, 255, 255, 0.92);
  margin: 0 0 clamp(1.5rem, 3vw, 2rem);
}

/* Parallax card collage (pointer-driven depth, scattered layout) */
.storage-parallax {
  width: 100%;
  max-width: none;
  margin: 0 auto;
}

.storage-parallax-bleed .storage-parallax__frame {
  border-radius: 0;
  border-left: none;
  border-right: none;
  border-top: none;
  box-shadow:
    0 32px 80px rgba(0, 0, 0, 0.58),
    inset 0 1px 0 rgba(255, 255, 255, 0.06);
}

.storage-parallax__frame {
  position: relative;
  padding: 0;
  border-radius: clamp(14px, 1.6vw, 20px);
  overflow: hidden;
  background: linear-gradient(
    168deg,
    rgba(10, 22, 40, 0.99) 0%,
    rgba(4, 8, 14, 1) 52%,
    rgba(2, 5, 10, 1) 100%
  );
  border: 1px solid rgba(157, 216, 255, 0.22);
  box-shadow:
    0 24px 64px rgba(0, 0, 0, 0.52),
    inset 0 1px 0 rgba(255, 255, 255, 0.08),
    0 0 48px rgba(74, 166, 227, 0.08);
  transition:
    border-color 0.35s ease,
    box-shadow 0.35s ease;
}

.storage-parallax:hover .storage-parallax__frame {
  border-color: rgba(186, 224, 255, 0.42);
  box-shadow:
    0 28px 72px rgba(0, 0, 0, 0.58),
    0 0 0 1px rgba(157, 216, 255, 0.18),
    0 0 48px rgba(109, 188, 244, 0.14),
    inset 0 1px 0 rgba(255, 255, 255, 0.1);
}

.storage-parallax__accent {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  z-index: 20;
  background: linear-gradient(
    90deg,
    transparent 0%,
    rgba(197, 160, 89, 0.55) 20%,
    rgba(157, 216, 255, 0.95) 50%,
    rgba(197, 160, 89, 0.55) 80%,
    transparent 100%
  );
  background-size: 200% 100%;
  animation: storageParallaxAccentSheen 12s ease-in-out infinite;
  opacity: 0.98;
  pointer-events: none;
  box-shadow: 0 0 24px rgba(157, 216, 255, 0.28);
}

.storage-parallax__ambient {
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  background:
    radial-gradient(ellipse 55% 45% at 12% 18%, rgba(109, 188, 244, 0.18) 0%, transparent 62%),
    radial-gradient(ellipse 48% 42% at 88% 82%, rgba(197, 160, 89, 0.14) 0%, transparent 58%),
    radial-gradient(ellipse 80% 55% at 50% 110%, rgba(74, 142, 184, 0.12) 0%, transparent 68%);
  animation: storageParallaxAmbientDrift 18s ease-in-out infinite alternate;
}

@keyframes storageParallaxAccentSheen {
  0%,
  100% {
    background-position: 0% 50%;
  }
  50% {
    background-position: 100% 50%;
  }
}

@keyframes storageParallaxAmbientDrift {
  0% {
    transform: scale(1) translate3d(0, 0, 0);
    opacity: 0.88;
  }
  100% {
    transform: scale(1.04) translate3d(0, -1.5%, 0);
    opacity: 1;
  }
}

.storage-parallax__stage {
  position: relative;
  width: 100%;
  min-height: clamp(620px, 78vh, 880px);
  height: auto;
  padding: clamp(1.75rem, 3.5vw, 2.75rem) 0 clamp(4.5rem, 6vw, 5.25rem);
  background:
    radial-gradient(ellipse 80% 65% at 14% 28%, rgba(109, 188, 244, 0.16) 0%, transparent 58%),
    radial-gradient(ellipse 65% 55% at 86% 72%, rgba(197, 160, 89, 0.12) 0%, transparent 55%),
    radial-gradient(ellipse 100% 85% at 50% 40%, rgba(25, 40, 58, 0.5) 0%, transparent 72%),
    linear-gradient(180deg, #060b12 0%, #04070d 48%, #030509 100%);
  overflow: hidden;
  touch-action: auto;
  cursor: grab;
}

.storage-parallax__stage:active {
  cursor: grabbing;
}

.storage-parallax__edge {
  position: absolute;
  top: 0;
  bottom: clamp(4.5rem, 6vw, 5.25rem);
  width: clamp(72px, 12vw, 180px);
  z-index: 12;
  pointer-events: none;
  transition: opacity 0.45s cubic-bezier(0.22, 1, 0.36, 1);
}

.storage-parallax__edge--left {
  left: 0;
  background: linear-gradient(
    90deg,
    rgba(5, 8, 14, 0.98) 0%,
    rgba(5, 8, 14, 0.72) 42%,
    transparent 100%
  );
}

.storage-parallax__edge--right {
  right: 0;
  background: linear-gradient(
    270deg,
    rgba(5, 8, 14, 0.98) 0%,
    rgba(5, 8, 14, 0.72) 42%,
    transparent 100%
  );
}

.storage-parallax__stage.is-at-start .storage-parallax__edge--left {
  opacity: 0;
}

.storage-parallax__stage.is-at-end .storage-parallax__edge--right {
  opacity: 0;
}

.storage-parallax__scroll-hint {
  position: absolute;
  top: clamp(0.85rem, 2vw, 1.15rem);
  right: clamp(1rem, 3vw, 2rem);
  z-index: 14;
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  padding: 0.42rem 0.75rem 0.42rem 0.85rem;
  border-radius: 999px;
  border: 1px solid rgba(157, 216, 255, 0.28);
  background: linear-gradient(
    135deg,
    rgba(12, 26, 46, 0.88) 0%,
    rgba(8, 18, 34, 0.92) 100%
  );
  box-shadow:
    0 10px 28px rgba(0, 0, 0, 0.32),
    inset 0 1px 0 rgba(255, 255, 255, 0.08);
  pointer-events: none;
  animation: storageParallaxHintPulse 2.4s ease-in-out infinite;
}

.storage-parallax__scroll-hint-text {
  font-family: 'Montserrat', sans-serif;
  font-size: clamp(0.58rem, 0.9vw, 0.68rem);
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: rgba(218, 192, 138, 0.96);
}

.storage-parallax__scroll-hint-icon {
  color: rgba(157, 216, 255, 0.95);
  animation: storageParallaxHintNudge 1.6s ease-in-out infinite;
}

.storage-parallax__scroll-hint-swipe {
  display: inline-flex;
  align-items: center;
  gap: 0.15rem;
  color: rgba(157, 216, 255, 0.95);
}

.storage-parallax__scroll-hint-swipe svg:first-child {
  animation: storageParallaxSwipeLeft 1.5s ease-in-out infinite;
}

.storage-parallax__scroll-hint-swipe svg:last-child {
  animation: storageParallaxSwipeRight 1.5s ease-in-out infinite;
}

@keyframes storageParallaxSwipeLeft {
  0%,
  100% {
    transform: translateX(2px);
    opacity: 0.55;
  }
  50% {
    transform: translateX(-3px);
    opacity: 1;
  }
}

@keyframes storageParallaxSwipeRight {
  0%,
  100% {
    transform: translateX(-2px);
    opacity: 0.55;
  }
  50% {
    transform: translateX(3px);
    opacity: 1;
  }
}

@keyframes storageParallaxHintPulse {
  0%,
  100% {
    opacity: 0.82;
    transform: translateY(0);
  }
  50% {
    opacity: 1;
    transform: translateY(-2px);
  }
}

@keyframes storageParallaxHintNudge {
  0%,
  100% {
    transform: translateX(0);
  }
  50% {
    transform: translateX(4px);
  }
}

/* Horizontal gallery strip */
.storage-parallax__track {
  display: flex;
  flex-direction: row;
  flex-wrap: nowrap;
  align-items: stretch;
  gap: clamp(20px, 2.8vw, 32px);
  width: 100%;
  min-height: clamp(480px, 62vh, 680px);
  overflow-x: auto;
  overflow-y: hidden;
  padding: clamp(1rem, 2vw, 1.5rem) clamp(4.5rem, 8vw, 6.5rem);
  padding-inline-end: clamp(5rem, 9vw, 7rem);
  scroll-padding-inline: clamp(4.5rem, 8vw, 6.5rem);
  scroll-snap-type: x proximity;
  scroll-behavior: auto;
  -webkit-overflow-scrolling: touch;
  overscroll-behavior-x: contain;
  overscroll-behavior-y: auto;
  touch-action: auto;
  scrollbar-width: none;
  -ms-overflow-style: none;
  outline: none;
}

.storage-parallax__track:focus-visible {
  box-shadow: inset 0 0 0 2px rgba(157, 216, 255, 0.35);
}

.storage-parallax__track::-webkit-scrollbar {
  display: none;
}

.storage-parallax__rail {
  position: absolute;
  top: 0;
  bottom: 0;
  z-index: 16;
  width: clamp(3.35rem, 5.5vw, 4.75rem);
  display: flex;
  align-items: stretch;
  pointer-events: none;
}

.storage-parallax__rail--prev {
  left: 0;
}

.storage-parallax__rail--next {
  right: 0;
}

.storage-parallax__nav {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  border: none;
  border-radius: 0;
  background: linear-gradient(
    90deg,
    rgba(4, 8, 14, 0.94) 0%,
    rgba(4, 8, 14, 0.72) 55%,
    rgba(4, 8, 14, 0.18) 100%
  );
  color: rgba(235, 244, 255, 0.96);
  box-shadow: inset -1px 0 0 rgba(157, 216, 255, 0.1);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  cursor: pointer;
  pointer-events: auto;
  transform: none;
  transition:
    background 0.32s ease,
    color 0.32s ease,
    opacity 0.32s ease,
    box-shadow 0.32s ease;
}

.storage-parallax__rail--next .storage-parallax__nav {
  background: linear-gradient(
    270deg,
    rgba(4, 8, 14, 0.94) 0%,
    rgba(4, 8, 14, 0.72) 55%,
    rgba(4, 8, 14, 0.18) 100%
  );
  box-shadow: inset 1px 0 0 rgba(157, 216, 255, 0.1);
}

.storage-parallax__nav-mark {
  position: absolute;
  top: 50%;
  width: 2px;
  height: clamp(2.4rem, 8vh, 4.5rem);
  border-radius: 999px;
  background: linear-gradient(
    180deg,
    transparent 0%,
    rgba(157, 216, 255, 0.85) 50%,
    transparent 100%
  );
  transform: translateY(-50%);
  opacity: 0.55;
  transition: opacity 0.32s ease, box-shadow 0.32s ease;
}

.storage-parallax__nav--prev .storage-parallax__nav-mark {
  right: clamp(0.55rem, 1vw, 0.85rem);
}

.storage-parallax__nav--next .storage-parallax__nav-mark {
  left: clamp(0.55rem, 1vw, 0.85rem);
}

.storage-parallax__nav:hover:not(:disabled):not(.is-disabled) {
  color: rgba(242, 209, 141, 0.98);
  background: linear-gradient(
    90deg,
    rgba(10, 18, 32, 0.96) 0%,
    rgba(10, 18, 32, 0.78) 55%,
    rgba(10, 18, 32, 0.24) 100%
  );
}

.storage-parallax__rail--next .storage-parallax__nav:hover:not(:disabled):not(.is-disabled) {
  background: linear-gradient(
    270deg,
    rgba(10, 18, 32, 0.96) 0%,
    rgba(10, 18, 32, 0.78) 55%,
    rgba(10, 18, 32, 0.24) 100%
  );
}

.storage-parallax__nav:hover:not(:disabled):not(.is-disabled) .storage-parallax__nav-mark {
  opacity: 1;
  box-shadow: 0 0 18px rgba(197, 160, 89, 0.45);
}

.storage-parallax__nav:focus-visible {
  outline: none;
  box-shadow:
    inset 0 0 0 2px rgba(157, 216, 255, 0.35),
    inset -1px 0 0 rgba(157, 216, 255, 0.1);
}

.storage-parallax__rail--next .storage-parallax__nav:focus-visible {
  box-shadow:
    inset 0 0 0 2px rgba(157, 216, 255, 0.35),
    inset 1px 0 0 rgba(157, 216, 255, 0.1);
}

.storage-parallax__nav:disabled,
.storage-parallax__nav.is-disabled {
  opacity: 0.34;
  cursor: default;
  pointer-events: none;
}

.storage-parallax__footer {
  position: absolute;
  left: 50%;
  bottom: clamp(1.35rem, 2.8vw, 2rem);
  z-index: 14;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.65rem;
  width: min(100% - 2.5rem, 28rem);
  transform: translateX(-50%);
  pointer-events: none;
}

.storage-parallax__counter {
  display: inline-flex;
  align-items: baseline;
  gap: 0.35rem;
  margin: 0;
  font-family: 'Montserrat', sans-serif;
  font-size: clamp(0.62rem, 0.95vw, 0.72rem);
  font-weight: 700;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: rgba(186, 224, 255, 0.72);
}

.storage-parallax__counter-current {
  color: rgba(242, 209, 141, 0.98);
  font-size: clamp(0.82rem, 1.2vw, 0.95rem);
  letter-spacing: 0.16em;
}

.storage-parallax__counter-sep {
  opacity: 0.45;
}

.storage-parallax__progress {
  position: relative;
  width: 100%;
  height: 2px;
  border-radius: 999px;
  background: rgba(8, 14, 24, 0.75);
  border: 1px solid rgba(157, 216, 255, 0.1);
  overflow: hidden;
  pointer-events: none;
}

.storage-parallax__progress-fill {
  display: block;
  width: 100%;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(
    90deg,
    rgba(197, 160, 89, 0.95) 0%,
    rgba(157, 216, 255, 1) 55%,
    rgba(218, 192, 138, 0.95) 100%
  );
  box-shadow: 0 0 18px rgba(109, 188, 244, 0.35);
  transform-origin: left center;
  transition: transform 0.12s linear;
  will-change: transform;
}

.storage-parallax__fog {
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  background: radial-gradient(
    ellipse 95% 90% at 50% 50%,
    transparent 35%,
    rgba(2, 4, 8, 0.55) 100%
  );
  mix-blend-mode: multiply;
}

.storage-parallax__card {
  position: relative;
  flex: 0 0 auto;
  width: clamp(460px, 46vw, 820px);
  max-width: min(820px, 92vw);
  scroll-snap-align: center;
  transform-origin: center center;
  will-change: transform;
}

.storage-parallax__card-inner {
  position: relative;
  width: 100%;
  border-radius: clamp(12px, 2vw, 18px);
  overflow: hidden;
  border: 1px solid rgba(157, 216, 255, 0.16);
  box-shadow:
    0 18px 48px rgba(0, 0, 0, 0.55),
    0 0 0 1px rgba(255, 255, 255, 0.05),
    inset 0 1px 0 rgba(255, 255, 255, 0.08);
  background: #0a1018;
  transition:
    box-shadow 0.35s ease,
    border-color 0.35s ease,
    transform 0.35s cubic-bezier(0.22, 1, 0.36, 1);
}

.storage-parallax__card-inner::before {
  content: '';
  position: absolute;
  top: 0;
  left: 10%;
  right: 10%;
  height: 2px;
  z-index: 2;
  border-radius: 2px;
  background: linear-gradient(
    90deg,
    transparent,
    rgba(197, 160, 89, 0.75) 35%,
    rgba(157, 216, 255, 0.9) 65%,
    transparent
  );
  pointer-events: none;
}

.storage-parallax__card:hover .storage-parallax__card-inner {
  border-color: rgba(186, 224, 255, 0.35);
  box-shadow:
    0 22px 56px rgba(0, 0, 0, 0.62),
    0 0 0 1px rgba(157, 216, 255, 0.22),
    0 0 32px rgba(109, 188, 244, 0.14),
    inset 0 1px 0 rgba(255, 255, 255, 0.1);
}

.storage-parallax__card-img {
  display: block;
  width: 100%;
  aspect-ratio: 16 / 10;
  height: auto;
  min-height: clamp(320px, 44vh, 520px);
  object-fit: cover;
  object-position: center;
}

.storage-parallax__card-scrim {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    180deg,
    transparent 0%,
    transparent 48%,
    rgba(2, 6, 12, 0.55) 82%,
    rgba(2, 6, 12, 0.88) 100%
  );
  pointer-events: none;
}

.storage-parallax__card-title {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 1;
  margin: 0;
  padding: clamp(0.85rem, 1.8vw, 1.1rem) clamp(0.85rem, 2vw, 1.1rem);
  font-family: 'Montserrat', sans-serif;
  font-size: clamp(0.68rem, 1.2vw, 0.88rem);
  font-weight: 800;
  letter-spacing: 0.12em;
  line-height: 1.25;
  text-transform: uppercase;
  color: rgba(255, 252, 246, 0.98);
  text-shadow:
    0 1px 3px rgba(0, 0, 0, 0.85),
    0 0 18px rgba(0, 0, 0, 0.5);
  background: linear-gradient(
    180deg,
    transparent 0%,
    rgba(5, 8, 14, 0.55) 38%,
    rgba(5, 8, 14, 0.92) 100%
  );
}

@media (max-width: 640px) {
  .storage-parallax-bleed {
    width: 100vw;
    max-width: 100vw;
    margin-left: calc(50% - 50vw);
    margin-right: calc(50% - 50vw);
  }

  .storage-parallax__frame {
    border-radius: 0;
    border-left: none;
    border-right: none;
  }

  .storage-parallax__stage,
  .storage-parallax__stage--mobile {
    min-height: auto;
    padding: 0 0 clamp(4rem, 8vw, 4.75rem);
    overflow: hidden;
  }

  .storage-parallax__fog,
  .storage-parallax__edge {
    display: none;
  }

  .storage-parallax__scroll-hint {
    top: auto;
    bottom: clamp(4.35rem, 8vw, 5rem);
    left: 50%;
    right: auto;
    transform: translateX(-50%);
  }

  .storage-parallax__scroll-hint--swipe {
    padding: 0.4rem 0.85rem;
    gap: 0.45rem;
  }

  .storage-parallax__scroll-hint--swipe .storage-parallax__scroll-hint-text {
    letter-spacing: 0.18em;
  }

  .storage-parallax__track {
    min-height: clamp(300px, 78vw, 400px);
    height: clamp(300px, 78vw, 400px);
    gap: 0;
    padding-inline: 0;
    padding-inline-end: 0;
    scroll-padding-inline: 0;
    scroll-snap-type: x mandatory;
    align-items: stretch;
  }

  .storage-parallax__card {
    flex: 0 0 100%;
    width: 100%;
    max-width: none;
    padding: 0;
    box-sizing: border-box;
    scroll-snap-align: start;
    scroll-snap-stop: always;
  }

  .storage-parallax__card-inner {
    display: flex;
    flex-direction: column;
    height: 100%;
    min-height: clamp(280px, 74vw, 380px);
    border-radius: 0;
    border-left: none;
    border-right: none;
    box-shadow: none;
  }

  .storage-parallax__card-inner::before {
    left: 0;
    right: 0;
  }

  .storage-parallax__card-img {
    flex: 1 1 auto;
    width: 100%;
    height: 100%;
    min-height: clamp(280px, 74vw, 380px);
    max-height: none;
    aspect-ratio: unset;
    object-fit: cover;
    object-position: center;
    background: #070c14;
  }

  .storage-parallax__card-scrim {
    background: linear-gradient(
      180deg,
      transparent 0%,
      transparent 70%,
      rgba(2, 6, 12, 0.4) 88%,
      rgba(2, 6, 12, 0.72) 100%
    );
  }

  .storage-parallax__card-title {
    font-size: clamp(0.58rem, 2.8vw, 0.68rem);
    padding: 0.55rem 0.6rem 0.65rem;
  }

  .storage-parallax__rail {
    width: clamp(2.75rem, 11vw, 3.35rem);
  }

