  min-height: 0;
  list-style: none;
}

.storage-spotlight__frame {
  position: relative;
  display: block;
  width: 100%;
  aspect-ratio: 3 / 2;
  overflow: hidden;
  margin: 0;
  padding: 0;
  border: none;
  border-radius: clamp(12px, 1.35vw, 16px);
  background: #060a12;
  font: inherit;
  color: inherit;
  text-align: left;
  cursor: zoom-in;
  box-shadow:
    0 16px 40px rgba(0, 0, 0, 0.34),
