}

.storage-tip-detail__nav-card {
  display: grid;
  grid-template-columns: minmax(0, 7.5rem) minmax(0, 1fr);
  align-items: stretch;
  min-height: 5.5rem;
  overflow: hidden;
  border-radius: clamp(12px, 1.4vw, 14px);
  border: 1px solid rgba(157, 216, 255, 0.2);
  background: linear-gradient(
    145deg,
    rgba(16, 36, 62, 0.75) 0%,
