  height: 100%;
  min-height: 100%;
  object-fit: contain;
  object-position: center center;
  padding: 0.35rem;
  box-sizing: border-box;
  transition: transform 0.5s cubic-bezier(0.22, 1, 0.36, 1);
}

.storage-tip-detail__nav-card-body {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 0.35rem;
  padding: clamp(0.85rem, 1.8vw, 1.1rem);
  min-width: 0;
}

.storage-tip-detail__nav-card--next .storage-tip-detail__nav-card-body {
  text-align: right;
  align-items: flex-end;
}

.storage-tip-detail__nav-label {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  font-family: 'Montserrat', sans-serif;
  font-size: clamp(0.58rem, 0.85vw, 0.64rem);
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: rgba(218, 192, 138, 0.88);
}

.storage-tip-detail__nav-card-title {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  overflow: hidden;
  font-family: 'Cormorant Garamond', 'Playfair Display', Georgia, serif;
  font-size: clamp(1rem, 1.45vw, 1.15rem);
  font-weight: 600;
  line-height: 1.25;
  letter-spacing: 0.01em;
  color: rgba(255, 252, 246, 0.98);
}

@media (hover: hover) {
  .storage-tip-detail__nav-card:hover {
    border-color: rgba(197, 160, 89, 0.45);
    box-shadow:
      0 20px 48px rgba(0, 0, 0, 0.38),
      0 0 28px rgba(197, 160, 89, 0.12);
    transform: translateY(-3px);
  }

