    transform: scale(1.03);
  }
}

@media (max-width: 720px) {
  .storage-tip-detail__nav-cards {
    grid-template-columns: 1fr;
  }

  .storage-tip-detail__nav-cards--single {
    max-width: none;
  }

  .storage-tip-detail__nav-card,
  .storage-tip-detail__nav-card--next {
    grid-template-columns: minmax(0, 6.5rem) minmax(0, 1fr);
  }

  .storage-tip-detail__nav-card--next .storage-tip-detail__nav-card-body {
    order: 2;
    text-align: left;
    align-items: flex-start;
  }

  .storage-tip-detail__nav-card--next .storage-tip-detail__nav-card-media {
    order: 1;
  }
}

.storage-price-card {
  position: relative;
  z-index: 1;
  padding: 1.35rem 1.25rem 1.5rem;
  border-radius: clamp(8px, 1vw, 12px);
  transform-style: preserve-3d;
  backface-visibility: hidden;
  background: linear-gradient(
    160deg,
    rgba(32, 62, 98, 0.55) 0%,
    rgba(14, 32, 56, 0.88) 45%,
    rgba(8, 16, 30, 0.96) 100%
  );
  border: 1px solid rgba(148, 196, 235, 0.38);
  box-shadow:
    0 12px 32px rgba(0, 0, 0, 0.35),
    inset 0 1px 0 rgba(255, 255, 255, 0.08);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  transition:
    border-color 0.35s cubic-bezier(0.22, 1, 0.36, 1),
    box-shadow 0.35s cubic-bezier(0.22, 1, 0.36, 1),
    transform 0.35s cubic-bezier(0.22, 1, 0.36, 1),
    background 0.35s ease;
}

.storage-price-card::before {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  pointer-events: none;
  background: radial-gradient(
    ellipse 120% 80% at 50% -20%,
    rgba(157, 216, 255, 0.14) 0%,
    transparent 62%
  );
  opacity: 0;
  transition: opacity 0.35s ease;
}

.storage-price-card:hover {
  border-color: rgba(186, 224, 255, 0.72);
  background: linear-gradient(
    160deg,
    rgba(40, 72, 112, 0.62) 0%,
    rgba(18, 40, 68, 0.9) 48%,
    rgba(10, 20, 38, 0.98) 100%
  );
  box-shadow:
    0 20px 48px rgba(0, 0, 0, 0.45),
    0 0 28px rgba(109, 188, 244, 0.12),
    inset 0 1px 0 rgba(255, 255, 255, 0.12);
  transform: translateY(-4px);
}

.storage-price-card:hover::before {
  opacity: 1;
}

.storage-price-card:nth-child(odd) {
  border-color: rgba(197, 160, 89, 0.32);
}

.storage-price-card:nth-child(odd):hover {
  border-color: rgba(218, 192, 138, 0.65);
