  position: relative;
  z-index: 1;
  font-family: 'Montserrat', sans-serif;
  font-size: clamp(0.62rem, 0.9vw, 0.68rem);
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: rgba(242, 209, 141, 0.98);
  white-space: nowrap;
}

.storage-extra-services__swipe-arrows {
  position: relative;
  z-index: 1;
  display: inline-flex;
  align-items: center;
  gap: 0.1rem;
  color: rgba(157, 216, 255, 0.95);
}

.storage-extra-services__swipe-arrows svg {
  flex-shrink: 0;
  opacity: 0.45;
  animation: storage-extra-swipe-arrow 1.6s ease-in-out infinite;
}

.storage-extra-services__swipe-arrows svg:nth-child(2) {
  animation-delay: 0.18s;
}

.storage-extra-services__swipe-arrows svg:nth-child(3) {
  animation-delay: 0.36s;
}

.storage-extra-services__feature-link:hover .storage-extra-services__swipe {
  border-color: rgba(218, 192, 138, 0.62);
