  color: rgba(255, 252, 246, 0.99);
}

@keyframes storage-extra-swipe-sheen {
  0%,
  72%,
  100% {
    transform: translateX(-120%);
  }
  38% {
    transform: translateX(120%);
  }
}

@keyframes storage-extra-swipe-arrow {
  0%,
  100% {
    opacity: 0.35;
    transform: translateX(0);
  }
  50% {
    opacity: 1;
    transform: translateX(3px);
  }
}

@media (prefers-reduced-motion: reduce) {
  .storage-extra-services__swipe::before,
  .storage-extra-services__swipe-arrows svg {
    animation: none;
  }

  .storage-extra-services__feature-link:hover,
