/* Service cards here omit reveal-scale: IntersectionObserver uses the window, so slides
   laid out past the viewport edge never received .revealed and stayed opacity:0. */
.consulting-service-cards-carousel {
  position: relative;
  width: 100%;
  padding: 0 clamp(0.5rem, 2.5vw, 1.5rem);
  margin-top: 0;
}

.consulting-service-cards-carousel__viewport {
  overflow-x: auto;
  overflow-y: hidden;
  scroll-snap-type: x mandatory;
  scroll-padding-inline: 0.2rem;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: thin;
  scrollbar-color: rgba(165, 200, 232, 0.35) transparent;
  padding-bottom: 0.35rem;
}

.consulting-service-cards-carousel__viewport:focus-visible {
  outline: 2px solid rgba(165, 200, 232, 0.85);
  outline-offset: 4px;
}

.consulting-service-cards-carousel__viewport::-webkit-scrollbar {
  height: 6px;
}

.consulting-service-cards-carousel__viewport::-webkit-scrollbar-thumb {
  background: rgba(165, 200, 232, 0.28);
  border-radius: 3px;
}

.consulting-service-cards-carousel__track {
  display: flex;
  gap: clamp(1rem, 2vw, 1.35rem);
  width: max-content;
  min-height: 1px;
}

.consulting-service-cards-carousel__track .consulting-service-card {
  scroll-snap-align: start;
  flex: 0 0 min(400px, calc(100vw - 2rem));
}

@media (min-width: 640px) {
  .consulting-service-cards-carousel__track .consulting-service-card {
    flex: 0 0 min(420px, calc(100vw - 3.5rem));
  }
}

@media (min-width: 1024px) {
  .consulting-service-cards-carousel__track .consulting-service-card {
    flex: 0 0 420px;
  }
}

.consulting-service-cards-carousel .consulting-service-card--carousel {
  padding: 1.85rem 1.5rem 1.65rem;
  gap: 1.15rem;
  min-height: 220px;
}

.consulting-service-cards-carousel .consulting-service-card__title {
  font-size: 0.95rem;
}

.consulting-service-cards-carousel__nav {
  position: absolute;
  top: 50%;
  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 42px;
  height: 42px;
  padding: 0;
  border-radius: 50%;
  border: 1px solid rgba(255, 255, 255, 0.14);
  background: rgba(8, 12, 22, 0.92);
  color: rgba(255, 255, 255, 0.92);
  cursor: pointer;
  transform: translateY(-50%);
  transition:
    background 0.2s ease,
    border-color 0.2s ease,
    opacity 0.2s ease,
    color 0.2s ease;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.35);
}

.consulting-service-cards-carousel__nav:hover:not(:disabled) {
  background: rgba(20, 28, 44, 0.98);
  border-color: rgba(165, 200, 232, 0.35);
  color: #fff;
}

.consulting-service-cards-carousel__nav:focus-visible {
  outline: 2px solid rgba(165, 200, 232, 0.85);
  outline-offset: 2px;
}

.consulting-service-cards-carousel__nav:disabled {
  opacity: 0.28;
  cursor: default;
}

.consulting-service-cards-carousel__nav--prev {
  left: 0;
}

.consulting-service-cards-carousel__nav--next {
  right: 0;
}

.consulting-service-cards-carousel__dots {
  display: flex;
