.consulting-service-card {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 1rem;
  padding: 1.6rem 1.35rem 1.5rem;
  border-radius: 12px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  background: linear-gradient(
    165deg,
    rgba(16, 22, 36, 0.95) 0%,
    rgba(5, 8, 14, 0.98) 100%
  );
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.32);
  overflow: visible;
  isolation: isolate;
  transition:
    border-color 0.45s cubic-bezier(0.16, 1, 0.3, 1),
    transform 0.45s cubic-bezier(0.16, 1, 0.3, 1),
    box-shadow 0.45s cubic-bezier(0.16, 1, 0.3, 1);
}

/* Entrance: merge reveal-scale final state with card hover baseline */
.consulting-page .consulting-service-card.reveal-scale.revealed {
  transform: translateY(0) scale(1);
}

.consulting-service-card::before {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  padding: 1px;
  background: linear-gradient(
    125deg,
    rgba(165, 200, 232, 0.15) 0%,
    rgba(197, 160, 89, 0.12) 35%,
    rgba(165, 200, 232, 0.08) 70%,
    rgba(255, 255, 255, 0.04) 100%
  );
  background-size: 220% 220%;
  -webkit-mask:
    linear-gradient(#fff 0 0) content-box,
    linear-gradient(#fff 0 0);
  mask:
    linear-gradient(#fff 0 0) content-box,
    linear-gradient(#fff 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
  opacity: 0.45;
  pointer-events: none;
  z-index: 0;
  animation: consulting-card-border-flow 8s ease-in-out infinite;
}

.consulting-service-card::after {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  opacity: 0;
  background: radial-gradient(
    circle at 30% 0%,
    rgba(197, 160, 89, 0.14) 0%,
    transparent 55%
  );
  transition: opacity 0.45s cubic-bezier(0.16, 1, 0.3, 1);
  pointer-events: none;
  z-index: 0;
}

.consulting-service-card > * {
  position: relative;
  z-index: 1;
}

.consulting-service-card:hover {
  border-color: rgba(165, 200, 232, 0.38);
  transform: translateY(-8px) scale(1.02);
  box-shadow:
    0 20px 56px rgba(0, 0, 0, 0.45),
    0 0 0 1px rgba(165, 200, 232, 0.12),
    0 0 40px rgba(165, 200, 232, 0.08);
}

.consulting-service-card:hover::before {
  opacity: 0.85;
  animation-duration: 4s;
}

.consulting-service-card:hover::after {
  opacity: 1;
}

@keyframes consulting-card-border-flow {
  0%,
  100% {
    background-position: 0% 50%;
  }
  50% {
    background-position: 100% 50%;
  }
}

@media (prefers-reduced-motion: reduce) {
  .consulting-service-card::before {
    animation: none;
    opacity: 0.35;
  }

  .consulting-service-card:hover {
    transform: translateY(-2px) scale(1.01);
  }

  .consulting-service-card:hover .consulting-service-card__icon {
    transform: none;
