    transform 0.35s cubic-bezier(0.22, 1, 0.36, 1),
    border-color 0.35s ease,
    box-shadow 0.35s ease,
    filter 0.35s ease;
  will-change: transform;
  animation: wedding-highlight-tile-float 7s ease-in-out infinite;
}

.wedding-highlight-tiles__tile::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(
    116deg,
    transparent 0%,
    rgba(165, 200, 232, 0.08) 40%,
    rgba(200, 169, 106, 0.05) 56%,
