.wedding-why {
  background:
    radial-gradient(ellipse 65% 50% at 0% 20%, rgba(63, 127, 255, 0.12) 0%, transparent 55%),
    linear-gradient(180deg, #f7faff 0%, #ffffff 100%);
}

.wedding-why__grid {
  gap: clamp(1rem, 2.2vw, 1.35rem);
  max-width: 980px;
}

.wedding-why__card {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 1rem 1.15rem;
  align-items: start;
  padding: 1.55rem 1.45rem 1.55rem 1.35rem;
  border-radius: 16px;
  border: 1px solid rgba(63, 127, 255, 0.18);
  background: #ffffff;
  box-shadow: 0 16px 40px rgba(25, 70, 150, 0.08);
}

.wedding-why__card:hover {
  background: #ffffff;
  border-color: rgba(63, 127, 255, 0.4);
  box-shadow: 0 22px 48px rgba(25, 70, 150, 0.14);
}

.wedding-why__num {
  font-family: 'Montserrat', sans-serif;
  font-size: 0.72rem;
  font-weight: 800;
  letter-spacing: 0.14em;
  color: #ffffff;
  background: linear-gradient(145deg, #3f7fff 0%, #1a5bb8 100%);
  width: 2.35rem;
  height: 2.35rem;
  border-radius: 999px;
  display: grid;
  place-items: center;
  box-shadow: 0 8px 18px rgba(26, 91, 184, 0.28);
}

.wedding-why__text {
  font-size: clamp(0.94rem, 1.5vw, 1.05rem);
  font-weight: 500;
  line-height: 1.7;
  color: rgba(20, 40, 72, 0.86);
}

.wedding-why__card:hover .wedding-why__text {
  color: var(--ws-ink);
}

.wedding-visit {
  background:
    radial-gradient(ellipse 70% 45% at 50% 0%, rgba(63, 127, 255, 0.1) 0%, transparent 55%),
    linear-gradient(180deg, #ffffff 0%, #f3f7ff 100%);
}

.wedding-visit__inner {
  max-width: 1100px;
}

.wedding-visit__grid {
  gap: 1.15rem;
}

.wedding-visit__card {
  padding: 1.65rem 1.45rem;
  border: 1px solid rgba(63, 127, 255, 0.2);
  border-radius: 16px;
  background:
    linear-gradient(165deg, #ffffff 0%, #f4f8ff 100%);
  box-shadow: 0 16px 40px rgba(25, 70, 150, 0.08);
  transition:
    border-color 0.3s ease,
    box-shadow 0.3s ease,
    transform 0.3s ease;
}

.wedding-visit__card:hover {
  border-color: rgba(63, 127, 255, 0.4);
  box-shadow: 0 22px 48px rgba(25, 70, 150, 0.14);
  transform: translateY(-3px);
}

.wedding-visit__label {
  color: var(--ws-blue);
  letter-spacing: 0.18em;
  font-size: 0.68rem;
}

.wedding-visit__address {
  color: rgba(25, 45, 80, 0.82);
  font-size: 0.94rem;
  line-height: 1.7;
}

.wedding-visit__list a {
  color: var(--ws-blue-deep);
  font-weight: 600;
}

.wedding-visit__list a:hover {
  color: var(--ws-blue-bright);
}

.wedding-visit__map-wrap {
  margin-top: clamp(2rem, 4vw, 2.75rem);
  border-radius: 16px;
  overflow: hidden;
  border: 1px solid rgba(63, 127, 255, 0.22);
  min-height: 320px;
  background: #e8f1ff;
  box-shadow: 0 20px 48px rgba(25, 70, 150, 0.12);
}

.wedding-testimonials .wedding-section__title {
  margin-bottom: 0.85rem;
}

.wedding-testimonials__grid {
  gap: clamp(1.15rem, 2.4vw, 1.5rem);
}

.wedding-testimonial {
  border-radius: 18px;
  min-height: 100%;
}

.wedding-testimonial__header {
  padding: 1.45rem 1.45rem 0.35rem;
}

.wedding-testimonial__quote {
  font-size: 0.94rem;
  line-height: 1.82;
}

.wedding-about__inner {
  max-width: min(1120px, 100%);
}

.wedding-about__page-title {
  margin-bottom: clamp(2.25rem, 4.5vw, 3rem);
}

.wedding-about__row {
  gap: clamp(1.35rem, 3vw, 2rem);
  margin-bottom: clamp(1.35rem, 3vw, 2rem);
}

.wedding-about__block:not(.wedding-about__block--muted) {
  padding: 1.55rem 1.45rem;
  border-radius: 16px;
  border: 1px solid rgba(63, 127, 255, 0.16);
  background: rgba(255, 255, 255, 0.88);
  box-shadow: 0 14px 36px rgba(25, 70, 150, 0.06);
}

.wedding-about__block--muted {
  border-radius: 16px;
}

@media (prefers-reduced-motion: reduce) {
  .wedding-offering-card:hover,
  .wedding-visit__card:hover {
    transform: none;
  }
}

.wedding-packages-section .wedding-section__eyebrow,
.wedding-testimonials .wedding-section__eyebrow,
.wedding-knowledge-bar .wedding-section__eyebrow {
  color: var(--ws-blue-bright);
}

.wedding-packages-section .wedding-section__title,
.wedding-testimonials .wedding-section__title,
.wedding-about .wedding-section__title {
  font-style: normal;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--ws-ink);
}

.wedding-packages-section .wedding-section__intro,
.wedding-testimonials .wedding-section__intro {
  color: rgba(30, 55, 95, 0.7);
}

.wedding-packages-section__intro-el {
  color: rgba(50, 80, 120, 0.58);
  margin-left: auto;
  margin-right: auto;
  text-align: center;
}

.wedding-packages-section__card {
  border: 1px solid rgba(63, 127, 255, 0.2);
  background: #ffffff;
  border-radius: 16px;
  box-shadow:
    0 18px 44px rgba(25, 70, 150, 0.1),
    inset 0 1px 0 rgba(255, 255, 255, 0.9);
}

.wedding-packages-section__card--interactive:hover,
.wedding-packages-section__card--interactive:focus-within {
  border-color: rgba(63, 127, 255, 0.5);
  box-shadow:
    0 24px 56px rgba(25, 70, 150, 0.16),
    0 0 0 1px rgba(63, 127, 255, 0.12);
}

.wedding-packages-section__media-scrim {
  background: linear-gradient(90deg, transparent 0%, rgba(10, 40, 90, 0.12) 100%);
}

.wedding-packages-section__content {
  padding: 1.4rem 1.45rem 1.5rem;
  gap: 0.4rem;
}

.wedding-packages-section__name-stack::after {
  background: linear-gradient(
    90deg,
    rgba(63, 127, 255, 0.55) 0%,
    rgba(26, 91, 184, 0.25) 50%,
    transparent 100%
  );
}

.wedding-packages-section__name-stack::before {
  background: linear-gradient(90deg, #3f7fff 0%, #1a5bb8 100%);
  box-shadow: 0 0 14px rgba(63, 127, 255, 0.35);
}

.wedding-packages-section__name {
  font-style: normal;
  letter-spacing: 0.06em;
  color: var(--ws-ink);
  text-shadow: none;
}

@supports (background-clip: text) and (-webkit-background-clip: text) {
  .wedding-packages-section__name {
    background: linear-gradient(120deg, #07111f 0%, #1a5bb8 70%, #3f7fff 100%);
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
    filter: none;
  }
}

.wedding-packages-section__name-el {
  color: rgba(26, 91, 184, 0.72);
}

.wedding-packages-section__price {
  color: var(--ws-blue);
  text-shadow: none;
  font-size: clamp(1.35rem, 2.2vw, 1.7rem);
}

.wedding-packages-section__tag {
  color: rgba(25, 45, 80, 0.72);
}

.wedding-packages-section__tag-el {
  color: rgba(40, 70, 110, 0.55);
}

.wedding-packages-section__details {
  color: var(--ws-blue-deep);
  border-color: rgba(63, 127, 255, 0.4);
  background: linear-gradient(145deg, rgba(63, 127, 255, 0.12) 0%, rgba(232, 241, 255, 0.9) 100%);
  box-shadow: 0 8px 18px rgba(30, 80, 170, 0.1);
}

.wedding-packages-section__details::after {
  color: var(--ws-blue);
}

.wedding-packages-section__details:hover {
  color: #ffffff;
  border-color: transparent;
  background: linear-gradient(145deg, #3f7fff 0%, #1a5bb8 100%);
  box-shadow: 0 12px 28px rgba(26, 91, 184, 0.28);
}

.wedding-packages-section__enquire {
  color: #ffffff;
  background: linear-gradient(145deg, #3f7fff 0%, #1a5bb8 55%, #0d3d8a 100%);
  border: 1px solid rgba(255, 255, 255, 0.35);
  box-shadow: 0 10px 24px rgba(26, 91, 184, 0.28);
  border-radius: 999px;
  padding: 0.65rem 1.15rem;
  letter-spacing: 0.16em;
}

.wedding-packages-section__enquire:hover {
  filter: brightness(1.08);
}

.wedding-knowledge-bar {
  background:
    radial-gradient(ellipse 80% 60% at 50% 50%, rgba(63, 127, 255, 0.12) 0%, transparent 60%),
    linear-gradient(180deg, #f7faff 0%, #ffffff 100%);
}

.wedding-knowledge-bar__trigger {
  border: 1px solid rgba(63, 127, 255, 0.35);
  background:
    linear-gradient(120deg, rgba(255, 255, 255, 0.2) 0%, transparent 40%),
    linear-gradient(145deg, #3f7fff 0%, #1a5bb8 48%, #0d3d8a 100%);
  color: #ffffff;
  box-shadow:
    0 16px 40px rgba(26, 91, 184, 0.28),
    inset 0 1px 0 rgba(255, 255, 255, 0.28);
  animation:
    weddingKnowledgeBarFloat 2.6s ease-in-out infinite,
    weddingKnowledgeBarPulseBlue 2.8s ease-in-out infinite;
}

@keyframes weddingKnowledgeBarPulseBlue {
  0%,
  100% {
    box-shadow:
      0 16px 40px rgba(26, 91, 184, 0.28),
      0 0 0 rgba(63, 127, 255, 0),
      inset 0 1px 0 rgba(255, 255, 255, 0.28);
  }
  50% {
    box-shadow:
      0 20px 48px rgba(26, 91, 184, 0.36),
      0 0 36px rgba(63, 127, 255, 0.28),
      inset 0 1px 0 rgba(255, 255, 255, 0.35);
  }
}

.wedding-knowledge-bar__trigger:hover {
  border-color: rgba(150, 200, 255, 0.7);
  filter: brightness(1.05);
  box-shadow:
    0 22px 52px rgba(20, 70, 170, 0.4),
    0 0 44px rgba(63, 127, 255, 0.3);
}

.wedding-knowledge-bar__text {
  letter-spacing: 0.22em;
  text-shadow: 0 1px 0 rgba(0, 0, 0, 0.15);
}

.wedding-knowledge-modal__panel {
  border: 1px solid rgba(63, 127, 255, 0.28);
  background:
    radial-gradient(ellipse 80% 40% at 0% 0%, rgba(63, 127, 255, 0.12) 0%, transparent 50%),
    linear-gradient(180deg, #ffffff 0%, #f4f8ff 100%);
  box-shadow: 0 28px 70px rgba(20, 60, 130, 0.22);
}

.wedding-knowledge-modal__head {
  border-bottom: 1px solid var(--ws-line);
  background: rgba(255, 255, 255, 0.92);
}

.wedding-knowledge-modal__head h2 {
  font-style: normal;
  color: var(--ws-ink);
}

.wedding-testimonials {
  background:
    radial-gradient(ellipse 70% 45% at 10% 0%, rgba(63, 127, 255, 0.1) 0%, transparent 55%),
    linear-gradient(180deg, #ffffff 0%, #f3f7ff 100%);
  border-top: 1px solid var(--ws-line);
}

.wedding-testimonial {
  background: #ffffff;
  border: 1px solid rgba(63, 127, 255, 0.18);
  border-radius: 16px;
  box-shadow:
    0 18px 44px rgba(25, 70, 150, 0.1),
    inset 0 1px 0 rgba(255, 255, 255, 0.95);
}

.wedding-testimonial:hover {
  box-shadow:
    0 26px 56px rgba(25, 70, 150, 0.16),
    0 0 0 1px rgba(63, 127, 255, 0.22);
}

.wedding-testimonial__avatar {
  background: linear-gradient(145deg, #6fb0ff 0%, #1a5bb8 100%);
  border: 1px solid rgba(63, 127, 255, 0.4);
  box-shadow: 0 8px 20px rgba(26, 91, 184, 0.22);
}

.wedding-testimonial__avatar-icon {
  color: #ffffff;
  filter: none;
}

.wedding-testimonial__deco-quote {
  color: rgba(63, 127, 255, 0.22);
  font-size: 4rem;
}

.wedding-testimonial__quote {
  color: rgba(20, 40, 72, 0.82);
  font-weight: 500;
  padding: 0.45rem 1.5rem 1.45rem;
}

.wedding-testimonial__footer {
  border-top: 1px solid var(--ws-line);
  background: linear-gradient(180deg, transparent 0%, rgba(232, 241, 255, 0.65) 100%);
}

.wedding-testimonial__author {
  color: var(--ws-blue-deep);
}

.wedding-testimonial__badge {
  color: var(--ws-blue);
  border-color: rgba(63, 127, 255, 0.3);
  background: rgba(63, 127, 255, 0.08);
}

.wedding-about {
  background:
    radial-gradient(ellipse 65% 45% at 100% 0%, rgba(63, 127, 255, 0.12) 0%, transparent 55%),
    linear-gradient(180deg, #ffffff 0%, #f6f9ff 55%, #ffffff 100%);
  border-top: 1px solid var(--ws-line);
  padding-top: clamp(3.25rem, 6.5vw, 5rem);
}

.wedding-about__page-title {
  border-bottom: 1px solid rgba(63, 127, 255, 0.22);
  color: var(--ws-ink);
  font-style: normal;
  font-size: clamp(2rem, 4vw, 2.75rem);
  letter-spacing: -0.025em;
}

.wedding-about__subhead {
  color: var(--ws-blue);
  letter-spacing: 0.18em;
  font-size: 0.72rem;
}

.wedding-about__tagline {
  color: var(--ws-ink);
}

.wedding-about__copy {
  color: rgba(25, 45, 80, 0.76);
  font-size: 1rem;
  line-height: 1.85;
}

.wedding-about__block--muted {
  border: 1px solid rgba(63, 127, 255, 0.22);
  background:
    linear-gradient(155deg, rgba(232, 241, 255, 0.95) 0%, rgba(255, 255, 255, 0.98) 100%);
  box-shadow:
    0 20px 48px rgba(25, 70, 150, 0.1),
    inset 0 1px 0 rgba(255, 255, 255, 0.95);
}

.wedding-about__block--muted::before {
  background: linear-gradient(180deg, #3f7fff 0%, #1a5bb8 55%, #0d3d8a 100%);
  box-shadow: 0 0 20px rgba(63, 127, 255, 0.35);
}

.wedding-about__block--muted .wedding-about__subhead {
  color: var(--ws-blue-deep);
}

.wedding-about__block--muted .wedding-about__tagline {
  color: var(--ws-ink);
  border-bottom-color: rgba(63, 127, 255, 0.2);
}

.wedding-about__block--muted .wedding-about__copy {
  color: rgba(25, 45, 80, 0.78);
}

.wedding-about__cta-wrap {
  border-top: 1px solid var(--ws-line);
}

.wedding-about__cta {
  color: #ffffff;
  background: linear-gradient(145deg, #3f7fff 0%, #1a5bb8 50%, #0d3d8a 100%);
  border: 1px solid rgba(255, 255, 255, 0.35);
  border-radius: 999px;
  padding: 1rem 2.1rem;
  box-shadow: 0 14px 36px rgba(26, 91, 184, 0.3);
}

.wedding-about__cta:hover {
  box-shadow: 0 18px 44px rgba(26, 91, 184, 0.4);
}

.wedding-about__panel {
  padding: 0.15rem 0;
}

.wedding-knowledge-modal__close {
  border-color: rgba(63, 127, 255, 0.3);
  background: #ffffff;
  color: var(--ws-blue-deep);
}

.wedding-knowledge-modal__close:hover {
  border-color: rgba(63, 127, 255, 0.55);
  background: var(--ws-soft);
}

.wedding-knowledge-modal__item {
  border-color: rgba(63, 127, 255, 0.2);
  background: linear-gradient(145deg, rgba(232, 241, 255, 0.65) 0%, #ffffff 55%);
  box-shadow: 0 10px 24px rgba(25, 70, 150, 0.08);
}

.wedding-knowledge-modal__item--open {
  border-color: rgba(63, 127, 255, 0.45);
  box-shadow:
    0 14px 30px rgba(25, 70, 150, 0.12),
    0 0 24px rgba(63, 127, 255, 0.12);
}

.wedding-knowledge-modal__item-icon {
  border-color: rgba(63, 127, 255, 0.35);
  color: var(--ws-blue);
  background: #ffffff;
}

.wedding-knowledge-modal__item--open .wedding-knowledge-modal__item-icon {
  border-color: rgba(63, 127, 255, 0.55);
  color: var(--ws-blue-deep);
  background: var(--ws-soft);
}

.wedding-knowledge-modal__item-toggle h3 {
  color: var(--ws-ink) !important;
  font-style: normal !important;
}

.wedding-knowledge-modal__item--open h3 {
  color: var(--ws-blue-deep) !important;
}

.wedding-knowledge-modal__item-body,
.wedding-knowledge-modal__item-body-inner,
.wedding-knowledge-modal__item-body p {
  color: rgba(25, 45, 80, 0.78) !important;
}

.wedding-knowledge-modal__backdrop {
  background: rgba(8, 24, 55, 0.45);
}

@media (max-width: 900px) {
  .wedding-about__page-title {
    color: var(--ws-ink);
  }
}

.wedding-package-detail-page {
  background: #05070a;
}

.wedding-package-detail-hero {
  position: relative;
  min-height: min(66vh, 720px);
  display: flex;
  align-items: flex-end;
  overflow: hidden;
  border-bottom: 1px solid rgba(255, 255, 255, 0.07);
}

.wedding-package-detail-hero__bg {
  position: absolute;
  inset: 0;
}

.wedding-package-detail-hero__bg img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
  filter: saturate(1.1) contrast(1.02);
}

.wedding-package-detail-hero__scrim {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(90deg, rgba(3, 10, 20, 0.88) 0%, rgba(3, 10, 20, 0.58) 42%, rgba(3, 10, 20, 0.76) 100%),
    linear-gradient(180deg, rgba(2, 7, 16, 0.25) 0%, rgba(2, 7, 16, 0.95) 85%);
}

.wedding-package-detail-hero__content {
  position: relative;
  z-index: 2;
  width: min(760px, 100%);
  padding: clamp(6rem, 14vh, 9rem) 0 clamp(2.2rem, 5vh, 3.1rem);
}

.wedding-package-detail-hero__eyebrow {
  margin: 0 0 0.8rem;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.24em;
  text-transform: uppercase;
  color: rgba(200, 169, 106, 0.94);
}

.wedding-package-detail-hero__title {
  margin: 0;
  font-family: 'Montserrat', sans-serif;
  font-size: clamp(1.7rem, 4.5vw, 2.7rem);
  font-weight: 800;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.98);
}

.wedding-package-detail-hero__subtitle {
  margin: 0.65rem 0 0;
  font-family: 'Playfair Display', Georgia, serif;
  font-size: clamp(0.94rem, 1.9vw, 1.15rem);
  font-style: italic;
  color: rgba(215, 229, 245, 0.92);
}

.wedding-package-detail-hero__title-el {
  margin: 0.35rem 0 0;
  font-family: 'Playfair Display', Georgia, serif;
  font-size: clamp(1rem, 2vw, 1.2rem);
  font-style: italic;
  color: rgba(188, 214, 238, 0.9);
}

.wedding-package-detail-hero__price {
  margin: 1.15rem 0 0;
  font-family: 'Playfair Display', Georgia, serif;
  font-size: clamp(1.35rem, 2.6vw, 1.75rem);
  font-weight: 600;
  letter-spacing: 0.05em;
  color: var(--service-light-blue);
  text-shadow: 0 0 26px rgba(165, 200, 232, 0.22);
}

.wedding-package-detail-hero__summary {
  margin: 1rem 0 0;
  max-width: 58ch;
  font-family: 'Montserrat', sans-serif;
  line-height: 1.78;
  color: rgba(242, 248, 255, 0.89);
}

.wedding-package-detail-hero__summary-el {
  margin: 0.6rem 0 0;
  max-width: 58ch;
  font-family: 'Montserrat', sans-serif;
  line-height: 1.72;
  color: rgba(193, 209, 227, 0.74);
}

.wedding-package-detail-hero__actions {
  margin-top: 1.35rem;
  display: flex;
  flex-wrap: wrap;
  gap: 0.65rem;
}

.wedding-package-detail-hero__action {
  text-decoration: none;
  border-radius: 4px;
  padding: 0.72rem 1.15rem;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.64rem;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  transition:
    transform 0.2s ease,
    filter 0.2s ease,
    border-color 0.2s ease;
}

.wedding-package-detail-hero__action--primary {
  color: rgba(7, 18, 34, 0.94);
  border: 1px solid rgba(255, 255, 255, 0.4);
  background: linear-gradient(165deg, #e8f2fa 0%, #c5daf0 40%, var(--service-light-blue) 100%);
}

.wedding-package-detail-hero__action--ghost {
  color: rgba(228, 236, 246, 0.92);
  border: 1px solid rgba(165, 200, 232, 0.38);
  background: rgba(10, 16, 28, 0.65);
}

.wedding-package-detail-hero__action:hover {
  transform: translateY(-1px);
  filter: brightness(1.04);
}

.wedding-package-detail-content {
  padding: clamp(2rem, 5vw, 3.25rem) 0 clamp(3.5rem, 7vw, 5rem);
}

.wedding-package-detail-content__grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: clamp(1.1rem, 2.2vw, 1.75rem);
}

.wedding-package-detail-panel {
  border: 1px solid rgba(165, 200, 232, 0.2);
  border-radius: 10px;
  padding: clamp(1.2rem, 2.5vw, 1.75rem);
  background:
    linear-gradient(155deg, rgba(28, 22, 16, 0.2) 0%, transparent 45%),
    linear-gradient(180deg, rgba(10, 14, 24, 0.94) 0%, rgba(5, 8, 14, 0.97) 100%);
}

.wedding-package-detail-panel__title {
  margin: 0 0 0.8rem;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.74rem;
  font-weight: 800;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: rgba(200, 169, 106, 0.92);
}

.wedding-package-detail-panel__copy {
  margin: 0;
  line-height: 1.76;
  color: rgba(230, 239, 250, 0.88);
}

.wedding-package-detail-panel__copy-el {
  margin: 0.7rem 0 0;
  line-height: 1.72;
  color: rgba(192, 209, 228, 0.74);
}

.wedding-package-detail-panel__meta {
  margin-top: 1rem;
  padding-top: 0.9rem;
