.pool-garden-hero__services-btn {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 1.05rem 2.55rem;
  cursor: pointer;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.24em;
  text-transform: uppercase;
  color: rgba(8, 22, 48, 0.97);
  border: 2px solid transparent;
  border-radius: 9999px;
  background:
    linear-gradient(
      158deg,
      #fbfdff 0%,
      #d2ecff 38%,
      #b8ddfb 58%,
      #eef8ff 100%
    )
      padding-box,
    linear-gradient(
      110deg,
      #e8c978 0%,
      #5ba8e8 28%,
      #c5a059 52%,
      #7ec0f0 78%,
      #dfc381 100%
    )
      border-box;
  background-size: 100% 100%, 280% 280%;
  background-clip: padding-box, border-box;
  background-position: 0 0, 0% 50%;
  animation:
    pool-hero-cta-glow-pulse 3.2s ease-in-out infinite,
