.pool-garden-hero__services-btn::before {
  content: '';
  position: absolute;
  inset: -40%;
  background: linear-gradient(
    105deg,
    transparent 36%,
    rgba(255, 255, 255, 0.55) 49%,
    rgba(255, 250, 235, 0.35) 52%,
    transparent 64%
  );
  transform: translateX(-65%) rotate(12deg);
  animation: pool-hero-cta-shine 4.8s ease-in-out infinite;
