}

.limo-detail--luxury .limo-detail-gallery--luxury-full {
  width: 100%;
  max-width: none;
  margin: 0 0 clamp(1.35rem, 3vw, 2.25rem);
  padding: 0 clamp(0.45rem, 1.1vw, 0.85rem);
  gap: clamp(0.45rem, 1vw, 0.75rem);
  display: grid;
  grid-template-columns: 1fr;
}

.limo-detail--luxury .limo-detail-gallery__item {
  border-radius: clamp(10px, 1.2vw, 16px);
  border-color: rgba(170, 210, 245, 0.32);
  box-shadow:
    0 16px 40px rgba(0, 0, 0, 0.38),
    inset 0 1px 0 rgba(255, 255, 255, 0.06);
  transition:
    border-color 0.35s ease,
    box-shadow 0.35s ease;
}

.limo-detail--luxury .limo-detail-gallery__item:hover {
  border-color: rgba(200, 230, 255, 0.55);
  box-shadow:
    0 22px 48px rgba(0, 0, 0, 0.42),
    0 0 0 1px rgba(120, 190, 240, 0.18);
}

.limo-detail--luxury .limo-detail-gallery__item img {
  aspect-ratio: 16 / 10;
  min-height: clamp(220px, 42vw, 420px);
}

.limo-detail--luxury .limo-detail-gallery__item--hero img {
  aspect-ratio: 21 / 9;
  min-height: clamp(280px, 52vw, 560px);
}

.limo-detail--luxury .limo-detail__content {
  width: min(1480px, 96%);
}

@media (min-width: 700px) {
  .limo-detail--luxury .limo-detail-gallery--luxury-full {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .limo-detail--luxury .limo-detail-gallery__item--hero {
    grid-column: 1 / -1;
  }

  .limo-detail--luxury .limo-detail-gallery__item:not(.limo-detail-gallery__item--hero) img {
    min-height: clamp(240px, 28vw, 380px);
  }
}

@media (min-width: 1100px) {
