  background: linear-gradient(
    165deg,
    #8ecfff 0%,
    #52a8df 42%,
    #3888c4 100%
  );
  border-color: rgba(210, 240, 255, 0.65);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.38),
    0 3px 0 rgba(15, 55, 95, 0.35),
    0 10px 26px rgba(60, 150, 215, 0.48);
  transform: translateY(-1px);
}

.yacht-modal__cta:active {
  color: rgba(235, 248, 255, 0.96);
  background: linear-gradient(
    165deg,
    #357dad 0%,
    #286899 48%,
    #1d527d 100%
  );
  border-color: rgba(130, 185, 225, 0.38);
  box-shadow:
    inset 0 2px 6px rgba(0, 25, 55, 0.42),
    0 1px 0 rgba(255, 255, 255, 0.12);
  transform: translateY(1px);
}

.yacht-modal__cta:focus-visible {
  outline: 2px solid rgba(140, 200, 255, 0.9);
  outline-offset: 3px;
}

/* —— Astreal Developers dedicated page —— */
.astreal-page {
  background: linear-gradient(180deg, #060a10 0%, #0a121c 38%, #070c12 100%);
}

.astreal-about-page {
  padding: clamp(5rem, 12vw, 6.5rem) 0 clamp(3rem, 7vw, 4.5rem);
}

.astreal-about-page--hero {
  --astreal-about-topbar-h: 72px;
  position: relative;
  padding: 0;
  margin-top: calc(-1 * var(--astreal-about-topbar-h));
  min-height: 100svh;
  min-height: 100dvh;
  overflow: hidden;
}

/* Our Services: deeper canvas + subtle cool/warm washes over base astreal-page */
.astreal-about-page.astreal-services-page {
  position: relative;
  isolation: isolate;
  padding-bottom: clamp(4rem, 9vw, 5.5rem);
  background-color: #061018;
  background-image:
    radial-gradient(
      ellipse 125% 90% at 50% -8%,
      rgba(112, 168, 225, 0.22) 0%,
      transparent 52%
    ),
    radial-gradient(ellipse 70% 50% at 92% 18%, rgba(74, 144, 226, 0.09), transparent 46%),
    radial-gradient(
      ellipse 65% 55% at 6% 48%,
      rgba(72, 120, 168, 0.16),
      transparent 52%
    ),
    radial-gradient(ellipse 100% 65% at 50% 100%, rgba(4, 10, 20, 0.55), transparent 58%),
    linear-gradient(
      180deg,
      #03060c 0%,
      #0a1420 32%,
      #0d1a2c 58%,
      #071018 100%
    );
}

.astreal-about-page.astreal-services-page .astreal-about-page__shell {
  position: relative;
  z-index: 1;
  padding-inline: clamp(1rem, 4vw, 3rem);
}

.astreal-about-page .astreal-detail-breadcrumb {
  margin-bottom: clamp(1.25rem, 3vw, 2rem);
}

/* Astreal subpages — premium horizontal navigation */
.astreal-page-nav {
  position: relative;
  display: flex;
  flex-flow: row nowrap;
  align-items: stretch;
  gap: 0;
  margin: 0 0 clamp(0.55rem, 1.2vw, 0.75rem);
  width: 100%;
  max-width: none;
  padding: 0;
  border: 1px solid rgba(74, 144, 226, 0.34);
  border-top: 2px solid rgba(218, 192, 138, 0.82);
  background: linear-gradient(
    180deg,
    rgba(16, 26, 40, 0.94) 0%,
    rgba(8, 14, 24, 0.9) 100%
  );
  box-shadow:
    0 0 0 1px rgba(112, 168, 225, 0.1) inset,
    0 14px 36px rgba(0, 0, 0, 0.28);
}

.astreal-page-nav::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 3px;
  height: 100%;
  background: linear-gradient(
    180deg,
    rgba(218, 192, 138, 0.95) 0%,
    rgba(74, 144, 226, 0.45) 55%,
    rgba(112, 168, 225, 0.35) 100%
  );
  pointer-events: none;
}

.astreal-page-nav__divider {
  flex-shrink: 0;
  align-self: stretch;
  width: 1px;
  margin: 0;
  background: linear-gradient(
    180deg,
    rgba(218, 192, 138, 0.55) 0%,
    rgba(74, 144, 226, 0.28) 50%,
    rgba(112, 168, 225, 0.22) 100%
  );
}

.astreal-page-nav__btn {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  flex: 1 1 0;
  min-width: 0;
  width: 100%;
  padding: 0.62rem 0.75rem;
  border-radius: 0;
  border: none;
  border-right: 1px solid rgba(74, 144, 226, 0.2);
  background: transparent;
  font-family: 'Montserrat', sans-serif;
  font-size: clamp(0.52rem, 0.95vw, 0.62rem);
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  text-decoration: none;
  text-align: center;
  line-height: 1.35;
  white-space: nowrap;
  color: rgba(198, 212, 230, 0.86);
  transition:
    border-color 0.32s cubic-bezier(0.22, 1, 0.36, 1),
    background 0.32s cubic-bezier(0.22, 1, 0.36, 1),
    color 0.32s cubic-bezier(0.22, 1, 0.36, 1),
    box-shadow 0.32s cubic-bezier(0.22, 1, 0.36, 1);
}

.astreal-page-nav__btn:last-child {
  border-right: none;
}

.astreal-page-nav__btn--back {
  padding-left: calc(1rem + 3px);
  border-right-color: rgba(74, 144, 226, 0.42);
  background: rgba(74, 144, 226, 0.07);
  color: rgba(232, 214, 178, 0.98);
}

@media (hover: hover) {
  .astreal-page-nav__btn--link:hover,
  .astreal-page-nav__btn--back:hover {
    background: rgba(112, 168, 225, 0.1);
    color: rgba(255, 252, 246, 0.98);
    box-shadow: inset 0 -2px 0 rgba(74, 144, 226, 0.72);
  }

  .astreal-page-nav__btn--back:hover {
    background: rgba(74, 144, 226, 0.14);
    box-shadow: inset 0 -2px 0 rgba(218, 192, 138, 0.9);
  }
}

.astreal-page-nav__btn--current {
  border-right-color: rgba(74, 144, 226, 0.32);
  background: linear-gradient(
    180deg,
    rgba(74, 144, 226, 0.24) 0%,
    rgba(74, 144, 226, 0.1) 100%
  );
  color: rgba(255, 252, 246, 0.99);
  box-shadow:
    inset 0 -2px 0 rgba(218, 192, 138, 0.92),
    inset 0 0 0 1px rgba(74, 144, 226, 0.18);
  cursor: default;
}

.astreal-page-nav__btn--link:focus-visible,
.astreal-page-nav__btn--back:focus-visible {
  outline: 2px solid rgba(150, 195, 235, 0.75);
  outline-offset: -2px;
  z-index: 1;
}

/* Shell: horizontal nav bar full width; main section below */
.astreal-about-page__shell:has(> .astreal-page-nav + section) {
  display: grid;
  grid-template-columns: 1fr;
  grid-template-rows: auto auto;
  row-gap: clamp(0.5rem, 1.2vw, 0.85rem);
  align-items: start;
  padding-top: 0.15rem;
}

.astreal-about-page__shell:has(> .astreal-page-nav + section) > .astreal-page-nav {
  grid-column: 1;
  grid-row: 1;
  position: sticky;
  top: clamp(4.5rem, 10vh, 5.5rem);
  z-index: 3;
  align-self: start;
  padding-block: 0;
  background: transparent;
  backdrop-filter: none;
}

.astreal-about-page__shell:has(> .astreal-page-nav + section) > section {
  grid-column: 1;
  grid-row: 2;
  width: 100%;
  min-width: 0;
}

.astreal-about-page__shell:has(> .astreal-page-nav + section) .astreal-about-page__content {
  max-width: 100%;
  width: 100%;
}

.astreal-about-page.astreal-invest-page {
  position: relative;
  isolation: isolate;
  padding-bottom: clamp(4rem, 9vw, 5.5rem);
  background-color: #061018;
  background-image:
    radial-gradient(ellipse 125% 90% at 50% -8%, rgba(112, 168, 225, 0.18) 0%, transparent 52%),
    radial-gradient(ellipse 70% 50% at 92% 18%, rgba(74, 144, 226, 0.08), transparent 46%),
    radial-gradient(ellipse 65% 55% at 6% 48%, rgba(72, 120, 168, 0.14), transparent 52%),
    linear-gradient(180deg, #03060c 0%, #0a1420 32%, #0d1a2c 58%, #071018 100%);
}

.astreal-about-page.astreal-services-page .astreal-about-page__shell,
.astreal-about-page.astreal-invest-page .astreal-about-page__shell {
  padding-top: 0;
  position: relative;
  z-index: 1;
}

.astreal-about-page.astreal-services-page .astreal-about.astreal-about--page-layout,
.astreal-about-page.astreal-invest-page .astreal-about.astreal-about--page-layout {
  padding-top: 0;
  padding-bottom: clamp(1.75rem, 4vw, 2.75rem);
}

.astreal-about-page.astreal-services-page .astreal-about-page__masthead,
.astreal-about-page.astreal-invest-page .astreal-about-page__masthead {
  padding-bottom: 0.25rem;
}

@media (max-width: 768px) {
  .astreal-about-page__shell:has(> .astreal-page-nav + section) > .astreal-page-nav {
    position: static;
  }

  .astreal-page-nav {
    flex-wrap: wrap;
  }

  .astreal-page-nav__btn {
    flex: 1 1 calc(50% - 1px);
    padding-inline: 0.65rem;
    border-bottom: 1px solid rgba(74, 144, 226, 0.16);
  }

  .astreal-page-nav__divider {
    display: none;
  }
}

/* About subpage: flat section (no panels / ambient behind copy), editorial type */
.astreal-about-page__shell {
