/* ── Scroll-synced LED section spotlight (see SectionLedScroll.tsx) ── */

.section-led {
  --section-led-core: rgba(120, 190, 255, 0.58);
  --section-led-mid: rgba(85, 155, 235, 0.32);
  --section-led-soft: rgba(55, 110, 185, 0.14);
  --section-led-hot: rgba(210, 235, 255, 0.28);
  position: relative;
  isolation: isolate;
  overflow: hidden;
}

/* Content only — do not restyle glow/ambient siblings (they must stay absolute) */
.section-led > .container,
.section-led > .astreal-detail-article__inner {
  position: relative;
  z-index: 1;
}

.section-led > [class*='glow'],
.section-led > [class*='ambient'],
.section-led > [class*='scrim'],
.section-led > [class*='vignette'] {
  position: absolute;
  z-index: 0;
}

.section-led::before {
  content: '';
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  opacity: 0.28;
  background: radial-gradient(
    ellipse 92% 58% at 50% 14%,
    var(--section-led-soft) 0%,
    transparent 68%
  );
  transition: opacity 0.75s cubic-bezier(0.22, 1, 0.36, 1);
}

.section-led::after {
  content: '';
  position: absolute;
  inset: -12% -8%;
  z-index: 0;
  pointer-events: none;
  opacity: 0;
  background:
    radial-gradient(
      ellipse 105% 72% at 50% 6%,
      var(--section-led-core) 0%,
      var(--section-led-mid) 38%,
      transparent 72%
    ),
    radial-gradient(
      ellipse 55% 38% at 50% 0%,
      var(--section-led-hot) 0%,
      transparent 58%
    );
  filter: blur(2px);
  transform: translateY(14px) scale(0.96);
  transition:
    opacity 0.65s cubic-bezier(0.22, 1, 0.36, 1),
    transform 0.85s cubic-bezier(0.22, 1, 0.36, 1);
}

.section-led.is-led-active::before {
  opacity: 0.5;
}

.section-led.is-led-active::after {
  opacity: 1;
  transform: translateY(0) scale(1);
  animation: section-led-beam-pulse 3.6s ease-in-out infinite;
}

.section-led--warm {
  --section-led-core: rgba(237, 200, 140, 0.5);
  --section-led-mid: rgba(74, 144, 226, 0.28);
  --section-led-soft: rgba(160, 120, 60, 0.12);
  --section-led-hot: rgba(255, 240, 210, 0.22);
}

.section-led--cyan {
  --section-led-core: rgba(95, 210, 255, 0.52);
  --section-led-mid: rgba(55, 165, 220, 0.3);
  --section-led-soft: rgba(40, 120, 170, 0.12);
  --section-led-hot: rgba(200, 245, 255, 0.24);
}

@keyframes section-led-beam-pulse {
  0%,
  100% {
    opacity: 0.88;
    filter: blur(2px);
  }

  50% {
    opacity: 1;
    filter: blur(0px);
  }
}

@media (prefers-reduced-motion: reduce) {
  .section-led.is-led-active::after {
    animation: none;
    opacity: 0.92;
    filter: none;
  }

  .section-led::before,
  .section-led::after {
    transition-duration: 0.2s;
  }
}

