@keyframes astreal-detail-lightbox-in {
  from {
    opacity: 0;
  }

  to {
    opacity: 1;
  }
}

.astreal-detail-lightbox {
  position: fixed;
  inset: 0;
  z-index: 500;
  margin: 0;
  padding: 0;
  background: rgba(2, 6, 14, 0.97);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  animation: astreal-detail-lightbox-in 0.26s ease-out;
}

.astreal-detail-lightbox__backdrop {
  position: absolute;
  inset: 0;
  z-index: 0;
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  border: none;
  cursor: zoom-out;
  background: transparent;
}

.astreal-detail-lightbox__close {
  position: absolute;
  top: max(0.65rem, env(safe-area-inset-top, 0px));
  right: max(0.65rem, env(safe-area-inset-right, 0px));
  z-index: 4;
  margin: 0;
  width: 2.75rem;
  height: 2.75rem;
  border-radius: 999px;
  border: 1px solid rgba(160, 200, 245, 0.35);
  background: rgba(12, 22, 38, 0.85);
  color: rgba(248, 252, 255, 0.96);
  font-size: 1.65rem;
  line-height: 1;
  cursor: pointer;
  transition:
    background 0.25s ease,
    border-color 0.25s ease,
    transform 0.25s ease;
}

.astreal-detail-lightbox__close:hover {
  background: rgba(22, 42, 68, 0.95);
  border-color: rgba(200, 225, 255, 0.55);
  transform: scale(1.05);
}

.astreal-detail-lightbox__nav {
  position: absolute;
  top: 50%;
  z-index: 4;
  transform: translateY(-50%);
  width: 3rem;
  height: 3rem;
  border-radius: 999px;
  border: 1px solid rgba(160, 200, 245, 0.38);
  background: rgba(10, 20, 36, 0.78);
  color: rgba(248, 252, 255, 0.96);
  font-size: 1.85rem;
  line-height: 1;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition:
    background 0.25s ease,
    border-color 0.25s ease,
    transform 0.25s ease;
}

.astreal-detail-lightbox__nav:hover {
  background: rgba(24, 48, 82, 0.92);
  border-color: rgba(210, 230, 255, 0.55);
  transform: translateY(-50%);
}

.astreal-detail-lightbox__nav--prev {
  left: max(0.35rem, env(safe-area-inset-left, 0px));
}

.astreal-detail-lightbox__nav--next {
  right: max(0.35rem, env(safe-area-inset-right, 0px));
}

.astreal-detail-lightbox__stage {
  position: absolute;
  z-index: 2;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0.65rem;
  min-width: 0;
  min-height: 0;
  pointer-events: none;
  inset: max(3.35rem, calc(env(safe-area-inset-top, 0px) + 2.75rem))
    max(0.35rem, env(safe-area-inset-right, 0px))
    max(2.25rem, calc(env(safe-area-inset-bottom, 0px) + 1.75rem))
    max(0.35rem, env(safe-area-inset-left, 0px));
}

.astreal-detail-lightbox__img {
  display: block;
  flex: 1 1 auto;
  min-width: 0;
  min-height: 0;
  max-width: min(100%, 1680px);
  max-height: 100%;
  width: auto;
  height: auto;
  object-fit: contain;
  pointer-events: auto;
  border-radius: 4px;
  box-shadow:
    0 28px 90px rgba(0, 0, 0, 0.65),
    0 0 0 1px rgba(255, 255, 255, 0.08);
}

.astreal-detail-lightbox__caption {
