    radial-gradient(55% 100% at 0% 60%, rgba(26, 52, 92, 0.14) 0%, transparent 48%),
    linear-gradient(
      180deg,
      rgba(10, 17, 30, 0.99) 0%,
      rgba(6, 10, 20, 0.985) 46%,
      rgba(3, 5, 12, 0.995) 100%
    );
  backdrop-filter: blur(22px) saturate(1.35);
  -webkit-backdrop-filter: blur(22px) saturate(1.35);
  border-bottom: 1px solid rgba(165, 210, 255, 0.14);
  box-shadow:
    0 20px 56px rgba(0, 0, 0, 0.38),
    inset 0 1px 0 rgba(255, 255, 255, 0.05);
}

.gw-subnav::before {
  content: '';
  display: block;
  height: 2px;
  background: linear-gradient(
    90deg,
    transparent 0%,
    rgba(44, 95, 158, 0.45) 12%,
    rgba(120, 185, 255, 0.95) 50%,
    rgba(44, 95, 158, 0.45) 88%,
    transparent 100%
  );
  box-shadow: 0 0 18px rgba(74, 144, 226, 0.35);
}

.gw-subnav__shell {
  position: relative;
}

.gw-subnav__shell::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(
    90deg,
    transparent 0%,
    rgba(74, 144, 226, 0.05) 42%,
    rgba(165, 210, 255, 0.07) 50%,
    rgba(74, 144, 226, 0.05) 58%,
    transparent 100%
  );
  pointer-events: none;
}

.gw-subnav__shell::after {
  content: '';
  position: absolute;
  inset: auto 0 0;
  height: 1px;
  background: linear-gradient(
    90deg,
    transparent,
    rgba(255, 255, 255, 0.08) 50%,
    transparent
  );
  pointer-events: none;
}

