  transition:
    transform 0.32s cubic-bezier(0.22, 1, 0.36, 1),
    opacity 0.22s ease;
}

.gw-subnav__toggle--open .gw-subnav__toggle-icon {
  transform: rotate(180deg);
  opacity: 1;
}

.gw-subnav__menu-wrap {
  position: absolute;
  top: calc(100% + 0.45rem);
  left: 0;
  right: 0;
  z-index: 50;
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transform: translateY(-6px);
  transition:
    opacity 0.28s ease,
    transform 0.32s cubic-bezier(0.22, 1, 0.36, 1),
    visibility 0.28s ease;
}

.gw-subnav__menu-wrap--open {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
  transform: translateY(0);
}

.gw-subnav__menu {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.45rem;
  margin: 0;
  padding: 0.55rem;
  list-style: none;
  background:
    linear-gradient(165deg, rgba(12, 18, 32, 0.96) 0%, rgba(3, 5, 10, 0.98) 100%);
  border: 1px solid rgba(74, 144, 226, 0.24);
  border-radius: 14px;
  box-shadow:
    0 22px 48px rgba(0, 0, 0, 0.38),
    inset 0 1px 0 rgba(255, 255, 255, 0.06);
  backdrop-filter: blur(22px) saturate(1.35);
  -webkit-backdrop-filter: blur(22px) saturate(1.35);
}

.gw-subnav__menu-item {
  margin: 0;
}

.gw-subnav__menu-link {
  display: flex;
  flex-direction: column;
  gap: 0.12rem;
  padding: 0.72rem 0.8rem;
  text-decoration: none;
  border: 1px solid rgba(74, 144, 226, 0.14);
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.02);
  transition:
    color 0.22s ease,
    background 0.22s ease,
    border-color 0.22s ease,
    transform 0.22s ease;
}

.gw-subnav__menu-link-label {
  font-family: 'Outfit', 'Montserrat', sans-serif;
  font-size: 0.74rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: rgba(220, 232, 248, 0.88);
}

.gw-subnav__menu-link-full {
  font-family: 'Montserrat', sans-serif;
  font-size: 0.52rem;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: rgba(165, 210, 255, 0.55);
}

.gw-subnav__menu-link:hover,
.gw-subnav__menu-link:focus-visible {
  background: rgba(74, 144, 226, 0.1);
  border-color: rgba(74, 144, 226, 0.32);
  transform: translateY(-1px);
}

.gw-subnav__menu-link--active {
  background: linear-gradient(135deg, rgba(74, 144, 226, 0.22) 0%, rgba(44, 95, 158, 0.16) 100%);
  border-color: rgba(74, 144, 226, 0.45);
  box-shadow: inset 0 0 0 1px rgba(165, 210, 255, 0.08);
}

.gw-subnav__menu-link--active .gw-subnav__menu-link-label {
  color: #fff;
}

.gw-subnav__menu-link--active .gw-subnav__menu-link-full {
  color: rgba(165, 210, 255, 0.82);
}

.gw-aviation-outlet {
  min-height: 0;
}

.gw-page [id] {
  scroll-margin-top: calc(var(--gw-topbar-h) + 44px + 0.75rem);
}

@media (prefers-reduced-motion: no-preference) {
  .gw-aviation-outlet {
    animation: gw-nav-content-in 0.22s cubic-bezier(0.22, 1, 0.36, 1) both;
  }
}

@keyframes gw-nav-content-in {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.gw-aviation-page {
  width: 100%;
}

.gw-main--section {
  min-height: min(50vh, 480px);
}

.gw-section-shell {
  display: grid;
  gap: 1.5rem;
}

.gw-section-shell__note {
  margin: 0;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.9rem;
  line-height: 1.65;
  color: var(--gw-text-muted);
  text-align: center;
}

/* Placeholder */
.gw-placeholder {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  min-height: 120px;
  background:
    linear-gradient(145deg, rgba(255, 255, 255, 0.04) 0%, transparent 55%),
    repeating-linear-gradient(
      -45deg,
      rgba(74, 144, 226, 0.06) 0,
      rgba(74, 144, 226, 0.06) 1px,
      transparent 1px,
      transparent 10px
    ),
    linear-gradient(180deg, #121a2e 0%, #0a1020 100%);
  border: 1px dashed rgba(74, 144, 226, 0.35);
  border-radius: 4px;
  overflow: hidden;
}

.gw-placeholder--hero-bg {
  position: absolute;
  inset: 0;
  min-height: 100%;
  border: none;
  border-radius: 0;
}

.gw-placeholder--logo {
  max-width: min(567px, 90%);
  margin-inline: auto;
}

.gw-placeholder--icon {
  width: 56px;
  min-height: 64px;
  margin-inline: auto;
}

.gw-placeholder__label {
  font-family: 'Montserrat', sans-serif;
  font-size: 0.65rem;
  font-weight: 600;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: rgba(74, 144, 226, 0.65);
  text-align: center;
  padding: 1rem;
}

/* Hero carousel */
.gw-hero {
  position: relative;
  min-height: calc(100svh - var(--gw-topbar-h) - 44px);
  min-height: calc(100dvh - var(--gw-topbar-h) - 44px);
  background: var(--gw-navy);
  overflow: hidden;
}

.gw-hero__slides {
  position: absolute;
  inset: 0;
  z-index: 1;
}

.gw-hero__video-wrap {
  position: absolute;
  inset: 0;
  z-index: 0;
  overflow: hidden;
  background: var(--gw-navy);
}

.gw-hero__video {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center center;
  opacity: 0;
  transform: scale(1.02);
  transition:
    opacity 0.55s cubic-bezier(0.22, 1, 0.36, 1),
    transform 1.2s cubic-bezier(0.22, 1, 0.36, 1);
}

.gw-hero__video-wrap--ready .gw-hero__video {
  opacity: 1;
  transform: scale(1);
}

.gw-hero__video-scrim {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(
      180deg,
      rgba(3, 5, 10, 0.42) 0%,
      rgba(3, 5, 10, 0.12) 42%,
      rgba(3, 5, 10, 0.48) 100%
    );
  pointer-events: none;
  opacity: 0.35;
  transition: opacity 0.75s cubic-bezier(0.22, 1, 0.36, 1);
}

.gw-hero--caption-visible .gw-hero__video-scrim {
  opacity: 1;
  background:
    linear-gradient(
      180deg,
      rgba(3, 5, 10, 0.58) 0%,
      rgba(3, 5, 10, 0.32) 38%,
      rgba(3, 5, 10, 0.65) 100%
    ),
    linear-gradient(
      115deg,
      rgba(3, 5, 10, 0.78) 0%,
      rgba(8, 16, 32, 0.52) 42%,
      rgba(3, 5, 10, 0.72) 100%
    );
}

.gw-hero--video-clear .gw-hero__video-scrim {
  opacity: 0.12;
}

.gw-hero__stage {
  position: absolute;
  inset: 0;
  z-index: 2;
  display: grid;
  place-items: center;
  pointer-events: none;
}

.gw-hero__caption {
  position: relative;
  z-index: 2;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: calc(100svh - var(--gw-topbar-h) - 44px);
  min-height: calc(100dvh - var(--gw-topbar-h) - 44px);
  text-align: center;
  padding: clamp(2rem, 8vh, 4rem) 1.25rem 5rem;
  pointer-events: auto;
}

.gw-hero__beats {
  position: absolute;
  bottom: 4.35rem;
  left: 50%;
  z-index: 4;
  display: flex;
  gap: 0.45rem;
  transform: translateX(-50%);
}

.gw-hero__beat {
  width: 1.75rem;
  height: 3px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.28);
  transition:
    width 0.35s cubic-bezier(0.22, 1, 0.36, 1),
    background 0.35s ease;
}

.gw-hero__beat--active {
  width: 2.25rem;
  background: rgba(165, 210, 255, 0.55);
}

.gw-hero__beat--live {
  background: linear-gradient(90deg, #4a90e2 0%, #a5d2ff 100%);
  box-shadow: 0 0 12px rgba(74, 144, 226, 0.45);
}

.gw-hero__slide {
  position: absolute;
  inset: 0;
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.85s cubic-bezier(0.22, 1, 0.36, 1), visibility 0.85s;
}

.gw-hero__slide--active {
  opacity: 1;
  visibility: visible;
  z-index: 2;
}

.gw-hero__logo-placeholder,
.gw-hero__banner-placeholder {
  margin-bottom: clamp(1.5rem, 4vh, 2.5rem);
}

.gw-hero__eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 0.55rem;
  margin: 0 0 1rem;
  padding: 0.35rem 0.85rem 0.35rem 0.55rem;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.64rem;
  font-weight: 600;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: #a5d2ff;
  background: rgba(74, 144, 226, 0.12);
  border: 1px solid rgba(74, 144, 226, 0.28);
  border-radius: 999px;
}

.gw-hero__eyebrow-dot {
  width: 0.45rem;
  height: 0.45rem;
  border-radius: 50%;
  background: linear-gradient(135deg, #4a90e2 0%, #a5d2ff 100%);
  box-shadow: 0 0 10px rgba(74, 144, 226, 0.55);
}

.gw-hero__title {
  margin: 0 0 0.65rem;
  font-family: 'Playfair Display', serif;
  font-size: clamp(1.65rem, 4.5vw, 2.75rem);
  font-weight: 500;
  line-height: 1.15;
  color: #fff;
  max-width: 18ch;
}

.gw-hero__subtitle {
  margin: 0 0 1.75rem;
  font-family: 'Cormorant Garamond', serif;
  font-size: clamp(1.35rem, 3vw, 2rem);
  font-weight: 400;
  font-style: italic;
  color: var(--gw-gold-light);
}

.gw-hero__cta {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 10rem;
  padding: 0.85rem 2rem;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  text-decoration: none;
  color: var(--gw-navy);
  background: linear-gradient(135deg, #a5c8e8 0%, var(--gw-gold) 100%);
  border: 1px solid rgba(220, 235, 255, 0.4);
  border-radius: 2px;
  transition: transform 0.25s ease, box-shadow 0.25s ease;
}

.gw-hero__cta:hover {
  transform: translateY(-2px);
  box-shadow: 0 12px 32px rgba(74, 144, 226, 0.35);
}

.gw-hero__cta--secondary {
  color: #fff;
  background: transparent;
  border-color: rgba(74, 144, 226, 0.55);
}

.gw-hero__cta--secondary:hover {
  background: rgba(74, 144, 226, 0.12);
  box-shadow: none;
}

.gw-hero__controls {
  position: absolute;
  inset: 0;
  z-index: 3;
  pointer-events: none;
}

.gw-hero__control {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  display: flex;
  align-items: center;
  justify-content: center;
  width: 2.75rem;
  height: 2.75rem;
  padding: 0;
  pointer-events: auto;
  color: rgba(255, 255, 255, 0.85);
  background: rgba(3, 5, 10, 0.45);
  border: 1px solid rgba(74, 144, 226, 0.3);
  border-radius: 50%;
  cursor: pointer;
  transition: background 0.2s ease, color 0.2s ease;
}

.gw-hero__control:hover {
  color: var(--gw-gold-light);
  background: rgba(74, 144, 226, 0.18);
}

.gw-hero__control--prev {
  left: clamp(0.75rem, 3vw, 1.5rem);
}

.gw-hero__control--next {
  right: clamp(0.75rem, 3vw, 1.5rem);
}

.gw-hero__scroll {
  position: absolute;
  bottom: 1.25rem;
  left: 50%;
  z-index: 4;
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  justify-content: center;
  width: 2.5rem;
  height: 2.5rem;
  color: var(--gw-gold-light);
  text-decoration: none;
  animation: gw-bounce 2s ease-in-out infinite;
}

@keyframes gw-bounce {
  0%,
  100% {
    transform: translateX(-50%) translateY(0);
  }
  50% {
    transform: translateX(-50%) translateY(6px);
  }
}

.gw-hero__dots {
  position: absolute;
  bottom: 3.75rem;
  left: 50%;
  z-index: 3;
  transform: translateX(-50%);
  display: flex;
  gap: 0.5rem;
}

.gw-hero__dot {
  width: 0.5rem;
  height: 0.5rem;
  padding: 0;
  border: none;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.35);
  cursor: pointer;
  transition: background 0.2s ease, transform 0.2s ease;
}

.gw-hero__dot--active {
  background: var(--gw-accent);
  transform: scale(1.2);
  box-shadow: 0 0 12px rgba(74, 144, 226, 0.45);
}

.gw-hero::before {
  content: '';
  position: absolute;
  inset: 0 auto auto;
  z-index: 2;
  height: 3px;
  background: linear-gradient(
    90deg,
    transparent 0%,
    #2c5f9e 18%,
    #4a90e2 50%,
    #a5d2ff 82%,
    transparent 100%
  );
  pointer-events: none;
}

.gw-hero__slide::after {
  content: '';
  position: absolute;
  inset: 0;
  z-index: 1;
  background:
    linear-gradient(
      115deg,
      rgba(3, 5, 10, 0.92) 0%,
      rgba(8, 16, 32, 0.78) 42%,
      rgba(3, 5, 10, 0.88) 100%
    ),
    radial-gradient(ellipse 55% 45% at 12% 18%, rgba(74, 144, 226, 0.16) 0%, transparent 62%);
  pointer-events: none;
}

.gw-hero__title {
  text-shadow: 0 8px 32px rgba(0, 0, 0, 0.35);
}

.gw-hero__subtitle {
  color: #a5d2ff;
}

.gw-hero__cta {
  position: relative;
  isolation: isolate;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.55rem;
  min-width: 11.5rem;
  padding: 0.92rem 1.85rem;
  overflow: hidden;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  text-decoration: none;
  color: #d4e8ff;
  background: rgba(255, 255, 255, 0.06);
  border: 2px solid rgba(74, 144, 226, 0.55);
  border-radius: 999px;
  box-shadow:
    0 10px 32px rgba(0, 0, 0, 0.28),
    inset 0 0 0 1px rgba(165, 210, 255, 0.06);
  transition:
    color 0.38s cubic-bezier(0.22, 1, 0.36, 1),
    border-color 0.38s ease,
    box-shadow 0.38s ease,
    transform 0.28s cubic-bezier(0.22, 1, 0.36, 1);
}

.gw-hero__cta-fill {
  position: absolute;
  inset: 0;
  z-index: -1;
  background: linear-gradient(135deg, #4a90e2 0%, #2c5f9e 52%, #1a3a66 100%);
  transform: translateX(-101%);
  transition: transform 0.52s cubic-bezier(0.22, 1, 0.36, 1);
}

.gw-hero__cta-fill::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(
    115deg,
    transparent 0%,
    rgba(255, 255, 255, 0.22) 48%,
    transparent 92%
  );
  transform: translateX(-120%);
  transition: transform 0.65s cubic-bezier(0.22, 1, 0.36, 1);
}

.gw-hero__cta-label,
.gw-hero__cta-icon {
  position: relative;
  z-index: 1;
}

.gw-hero__cta-icon {
  flex-shrink: 0;
  transition: transform 0.38s cubic-bezier(0.22, 1, 0.36, 1);
}

.gw-hero__cta:hover,
.gw-hero__cta:focus-visible {
  color: #fff;
  border-color: rgba(165, 210, 255, 0.72);
  transform: translateY(-2px);
  box-shadow:
    0 16px 40px rgba(74, 144, 226, 0.38),
    0 0 28px rgba(74, 144, 226, 0.18);
  outline: none;
}

.gw-hero__cta:hover .gw-hero__cta-fill,
.gw-hero__cta:focus-visible .gw-hero__cta-fill {
  transform: translateX(0);
}

.gw-hero__cta:hover .gw-hero__cta-fill::after,
.gw-hero__cta:focus-visible .gw-hero__cta-fill::after {
  transform: translateX(120%);
}

.gw-hero__cta:hover .gw-hero__cta-icon,
.gw-hero__cta:focus-visible .gw-hero__cta-icon {
  transform: translateX(4px);
}

.gw-hero__cta--secondary {
  color: rgba(255, 255, 255, 0.92);
  background: rgba(3, 5, 10, 0.35);
  border: 2px solid rgba(165, 210, 255, 0.45);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.22);
}

.gw-hero__cta--secondary:hover,
.gw-hero__cta--secondary:focus-visible {
  color: #fff;
  background: rgba(74, 144, 226, 0.16);
  border-color: rgba(165, 210, 255, 0.65);
  box-shadow: 0 12px 32px rgba(74, 144, 226, 0.24);
}

/* Unified inner-page hero (Global Wings sub-pages) */
.gw-page-hero {
  position: relative;
  min-height: min(62vh, 560px);
  display: flex;
  align-items: flex-end;
  padding: clamp(4.5rem, 11vh, 6.5rem) 0 clamp(2.75rem, 6vh, 4.25rem);
  overflow: hidden;
  background: var(--gw-navy);
}

.gw-page-hero__bg {
  position: absolute;
  inset: 0;
  z-index: 0;
  border: none;
  border-radius: 0;
}

.gw-page-hero__scrim {
  position: absolute;
  inset: 0;
  z-index: 1;
  background:
    linear-gradient(
      115deg,
      rgba(3, 5, 10, 0.94) 0%,
      rgba(8, 16, 32, 0.82) 48%,
      rgba(3, 5, 10, 0.92) 100%
    );
  pointer-events: none;
}

.gw-page-hero__grid {
  position: absolute;
  inset: 0;
  z-index: 1;
  opacity: 0.22;
  background-image:
    linear-gradient(rgba(165, 210, 255, 0.08) 1px, transparent 1px),
    linear-gradient(90deg, rgba(165, 210, 255, 0.08) 1px, transparent 1px);
  background-size: 48px 48px;
  mask-image: linear-gradient(180deg, rgba(0, 0, 0, 0.55) 0%, transparent 88%);
  pointer-events: none;
}

.gw-page-hero__glow {
  position: absolute;
  z-index: 1;
  width: min(42vw, 520px);
  height: min(42vw, 520px);
  border-radius: 50%;
  filter: blur(80px);
  pointer-events: none;
}

.gw-page-hero__glow--left {
  top: -12%;
  left: -8%;
  background: rgba(74, 144, 226, 0.22);
}

.gw-page-hero__glow--right {
  right: -6%;
  bottom: -18%;
  background: rgba(44, 95, 158, 0.18);
}

.gw-page-hero__accent {
  position: absolute;
  inset: 0 auto auto;
  z-index: 2;
  height: 3px;
  background: linear-gradient(
    90deg,
    transparent 0%,
    #2c5f9e 16%,
    #4a90e2 50%,
    #a5d2ff 84%,
    transparent 100%
  );
  pointer-events: none;
}

.gw-page-hero__inner {
  position: relative;
  z-index: 2;
  max-width: min(860px, 100%);
}

.gw-page-hero__eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 0.55rem;
  margin: 0 0 1rem;
  padding: 0.35rem 0.85rem 0.35rem 0.55rem;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.64rem;
  font-weight: 600;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: #a5d2ff;
  background: rgba(74, 144, 226, 0.12);
  border: 1px solid rgba(74, 144, 226, 0.28);
  border-radius: 999px;
}

.gw-page-hero__eyebrow-dot {
  width: 0.45rem;
  height: 0.45rem;
  border-radius: 50%;
  background: linear-gradient(135deg, #4a90e2 0%, #a5d2ff 100%);
  box-shadow: 0 0 10px rgba(74, 144, 226, 0.55);
}

.gw-page-hero__title {
  margin: 0 0 0.85rem;
  font-family: 'Playfair Display', serif;
  font-size: clamp(2.15rem, 5.5vw, 3.65rem);
  font-weight: 500;
  line-height: 1.08;
  letter-spacing: -0.01em;
  color: #fff;
  text-shadow: 0 10px 36px rgba(0, 0, 0, 0.35);
}

.gw-page-hero__subtitle {
  margin: 0 0 0.75rem;
  font-family: 'Montserrat', sans-serif;
  font-size: clamp(1.02rem, 2.1vw, 1.22rem);
  font-weight: 500;
  line-height: 1.65;
  color: rgba(244, 248, 255, 0.94);
  max-width: 58ch;
}

.gw-page-hero__lead,
.gw-page-hero__para {
  margin: 0 0 0.65rem;
  font-family: 'Montserrat', sans-serif;
  font-size: clamp(0.88rem, 1.5vw, 0.96rem);
  line-height: 1.75;
  color: rgba(220, 232, 248, 0.78);
  max-width: 62ch;
}

.gw-page-hero__para:last-of-type {
  margin-bottom: 0;
}

.gw-page-hero__highlights {
  display: flex;
  flex-wrap: wrap;
  gap: 0.65rem;
  margin: 1.35rem 0 0;
  padding: 0;
  list-style: none;
}

.gw-page-hero__highlights li {
  display: flex;
  flex-direction: column;
  min-width: 6.25rem;
  padding: 0.7rem 1rem;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(74, 144, 226, 0.28);
  border-radius: 12px;
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
}

.gw-page-hero__highlight-value {
  font-family: 'Playfair Display', serif;
  font-size: 1.2rem;
  font-weight: 500;
  line-height: 1.1;
  color: #d4e8ff;
}

.gw-page-hero__highlight-label {
  margin-top: 0.15rem;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.6rem;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: rgba(165, 210, 255, 0.72);
}

.gw-page-hero__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  margin-top: 1.5rem;
}

.gw-page-hero__btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.72rem 1.35rem;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  text-decoration: none;
  border-radius: 999px;
  transition: transform 0.2s ease, box-shadow 0.2s ease, background 0.2s ease;
}

.gw-page-hero__btn--primary {
  color: #fff;
  background: linear-gradient(135deg, #4a90e2 0%, #2c5f9e 100%);
  border: 1px solid rgba(165, 210, 255, 0.28);
  box-shadow: 0 10px 28px rgba(74, 144, 226, 0.28);
}

.gw-page-hero__btn--primary:hover,
.gw-page-hero__btn--primary:focus-visible {
  transform: translateY(-2px);
  box-shadow: 0 14px 34px rgba(74, 144, 226, 0.38);
}

.gw-page-hero__btn--secondary {
  color: #f4f8ff;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(165, 210, 255, 0.32);
}

.gw-page-hero__btn--secondary:hover,
.gw-page-hero__btn--secondary:focus-visible {
  background: rgba(74, 144, 226, 0.14);
  transform: translateY(-2px);
}

.gw-page-hero__fade {
  position: absolute;
  inset: auto 0 0;
  z-index: 2;
  height: 4.5rem;
  background: linear-gradient(180deg, transparent 0%, var(--gw-blue-grey) 100%);
  pointer-events: none;
}

@media (max-width: 640px) {
  .gw-page-hero {
    min-height: min(58vh, 480px);
  }

  .gw-page-hero__actions {
    flex-direction: column;
    align-items: stretch;
  }

  .gw-page-hero__btn {
    width: 100%;
  }
}

@media (prefers-reduced-motion: reduce) {
  .gw-page-hero__btn--primary:hover,
  .gw-page-hero__btn--secondary:hover {
    transform: none;
  }
}

/* Main sections */
.gw-main {
  background: var(--gw-blue-grey);
}

.gw-section {
  padding: clamp(3.5rem, 8vw, 5.5rem) 0;
}

.gw-section__bleed {
  position: relative;
  z-index: 1;
  box-sizing: border-box;
  width: 100vw;
  max-width: 100vw;
  margin-left: calc(50% - 50vw);
  margin-right: calc(50% - 50vw);
  padding-inline: clamp(1rem, 3vw, 2.5rem);
}

.gw-section__header {
  text-align: center;
  margin-bottom: clamp(2rem, 5vw, 3rem);
}

.gw-section__title {
  margin: 0;
  font-family: 'Playfair Display', serif;
  font-size: clamp(1.75rem, 4vw, 2.5rem);
  font-weight: 500;
  color: var(--gw-text);
}

.gw-section--about {
  position: relative;
  overflow: hidden;
  padding: clamp(4rem, 9vw, 6rem) 0;
  background:
    linear-gradient(180deg, #ffffff 0%, #f6faff 38%, #eef4fc 100%);
}

.gw-section--about::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 60% 50% at 0% 0%, rgba(74, 144, 226, 0.11) 0%, transparent 62%),
    radial-gradient(ellipse 50% 45% at 100% 100%, rgba(44, 95, 158, 0.09) 0%, transparent 58%),
    linear-gradient(90deg, rgba(3, 5, 10, 0.015) 0%, transparent 12%, transparent 88%, rgba(3, 5, 10, 0.015) 100%);
  pointer-events: none;
}

.gw-about {
  position: relative;
  z-index: 1;
}

.gw-about__layout {
  display: grid;
  grid-template-columns: minmax(0, 1.02fr) minmax(0, 0.98fr);
  gap: clamp(1.25rem, 2.5vw, 1.85rem);
  align-items: stretch;
}

.gw-about__panel {
  position: relative;
  overflow: hidden;
  background: #fff;
  border: 2px solid rgba(44, 95, 158, 0.24);
  border-radius: 20px;
  box-shadow:
    0 28px 72px rgba(3, 5, 10, 0.08),
    0 0 0 1px rgba(255, 255, 255, 0.92) inset;
}

.gw-about__panel--film {
  border-color: rgba(74, 144, 226, 0.32);
  background:
    linear-gradient(155deg, rgba(3, 5, 10, 0.98) 0%, rgba(10, 18, 36, 0.96) 52%, rgba(18, 32, 58, 0.94) 100%);
  box-shadow:
    0 32px 80px rgba(3, 5, 10, 0.22),
    0 0 0 1px rgba(74, 144, 226, 0.12) inset;
}

.gw-about__panel-accent {
  height: 4px;
  background: linear-gradient(90deg, #1a3a66 0%, #2c5f9e 22%, #4a90e2 50%, #a5d2ff 78%, #d4e8ff 100%);
}

.gw-about__panel-inner {
  display: flex;
  flex-direction: column;
  height: 100%;
  padding: clamp(1.55rem, 3vw, 2.35rem);
}

.gw-about__eyebrow {
  display: inline-flex;
  align-self: flex-start;
  align-items: center;
  gap: 0.45rem;
  margin-bottom: 1rem;
  padding: 0.38rem 0.85rem 0.38rem 0.55rem;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--gw-accent-deep);
  background: rgba(74, 144, 226, 0.08);
  border: 1.5px solid rgba(74, 144, 226, 0.28);
  border-radius: 999px;
}

.gw-about__eyebrow::before {
  content: '';
  width: 0.42rem;
  height: 0.42rem;
  border-radius: 50%;
  background: linear-gradient(135deg, #4a90e2 0%, #a5d2ff 100%);
  box-shadow: 0 0 10px rgba(74, 144, 226, 0.45);
}

.gw-about__title {
  margin: 0 0 0.85rem;
  font-family: 'Playfair Display', serif;
  font-size: clamp(2rem, 4.5vw, 2.85rem);
  font-weight: 500;
  line-height: 1.08;
  letter-spacing: -0.01em;
  color: var(--gw-text);
}

.gw-about__intro {
  margin: 0;
  font-family: 'Montserrat', sans-serif;
  font-size: clamp(0.92rem, 1.6vw, 1.02rem);
  font-weight: 500;
  line-height: 1.85;
  color: var(--gw-text);
}

.gw-about__body {
  margin: 0.85rem 0 0;
  padding-bottom: 1.35rem;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.9rem;
  line-height: 1.8;
  color: var(--gw-text-muted);
  border-bottom: 2px solid rgba(74, 144, 226, 0.14);
}

.gw-about__highlights {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.65rem;
  margin: 1.25rem 0 0;
  padding: 0;
  list-style: none;
}

.gw-about__highlights li {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 0.28rem;
  padding: clamp(0.85rem, 2vw, 1rem) clamp(0.9rem, 2.2vw, 1.1rem);
  background: linear-gradient(180deg, #f8fbff 0%, #fff 100%);
  border: 2px solid rgba(44, 95, 158, 0.28);
  border-radius: 12px;
  box-shadow:
    0 10px 28px -18px rgba(26, 52, 92, 0.35),
    inset 0 1px 0 rgba(255, 255, 255, 0.92);
}

.gw-about__highlight-value {
  font-family: 'Montserrat', sans-serif;
  font-size: clamp(1.2rem, 2.5vw, 1.65rem);
  font-weight: 800;
  letter-spacing: 0.08em;
  line-height: 1.05;
  text-transform: uppercase;
  color: #1a3a66;
}

.gw-about__highlight-label {
  font-family: 'Montserrat', sans-serif;
  font-size: clamp(0.58rem, 1.2vw, 0.66rem);
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: rgba(26, 36, 56, 0.78);
}

.gw-about__capabilities {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin: auto 0 0;
  padding: 1.25rem 0 0;
  list-style: none;
}

.gw-about__capabilities li {
  padding: 0.48rem 0.82rem;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.02em;
  color: var(--gw-text);
  background: rgba(74, 144, 226, 0.07);
  border: 1.5px solid rgba(74, 144, 226, 0.24);
  border-radius: 999px;
}

.gw-about__film {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 1.75rem;
  height: 100%;
  min-height: 100%;
  padding: clamp(1.5rem, 3vw, 2rem);
}

.gw-about__film-visual {
  position: relative;
  display: grid;
  place-items: center;
  min-height: clamp(10rem, 28vw, 14rem);
  border-radius: 16px;
  overflow: hidden;
  background:
    radial-gradient(circle at 50% 42%, rgba(74, 144, 226, 0.22) 0%, transparent 58%),
    linear-gradient(145deg, rgba(74, 144, 226, 0.08) 0%, rgba(3, 5, 10, 0.2) 100%);
  border: 2px solid rgba(74, 144, 226, 0.28);
}

.gw-about__film-glow {
  position: absolute;
  inset: -20%;
  background:
    radial-gradient(circle at 30% 35%, rgba(74, 144, 226, 0.28) 0%, transparent 48%),
    radial-gradient(circle at 72% 68%, rgba(165, 210, 255, 0.14) 0%, transparent 52%);
  pointer-events: none;
  animation: gw-about-film-glow 5s ease-in-out infinite alternate;
}

@keyframes gw-about-film-glow {
  from { transform: scale(1) translate(0, 0); opacity: 0.75; }
  to { transform: scale(1.05) translate(1%, -1%); opacity: 1; }
}

.gw-about__film-ring {
  position: absolute;
  width: clamp(5.5rem, 18vw, 7.5rem);
  height: clamp(5.5rem, 18vw, 7.5rem);
  border-radius: 999px;
  border: 2px solid rgba(74, 144, 226, 0.35);
  box-shadow: 0 0 40px rgba(74, 144, 226, 0.18);
}

.gw-about__film-icon-wrap {
  position: relative;
  z-index: 1;
  display: grid;
  place-items: center;
  width: 3.75rem;
  height: 3.75rem;
  color: #fff;
  background: linear-gradient(135deg, #4a90e2 0%, #2c5f9e 100%);
  border: 2px solid rgba(165, 210, 255, 0.4);
  border-radius: 999px;
  box-shadow: 0 12px 32px rgba(74, 144, 226, 0.38);
}

.gw-about__film-icon {
  width: 1.35rem;
  height: 1.35rem;
  margin-left: 0.12rem;
}

.gw-about__film-copy {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 0.85rem;
}

.gw-about__film-badge {
  display: inline-flex;
  padding: 0.35rem 0.75rem;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.56rem;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: rgba(165, 210, 255, 0.9);
  background: rgba(74, 144, 226, 0.14);
  border: 1.5px solid rgba(74, 144, 226, 0.35);
  border-radius: 999px;
}

.gw-about__film-lead {
  margin: 0;
  font-family: 'Montserrat', sans-serif;
  font-size: clamp(0.88rem, 1.5vw, 0.96rem);
  line-height: 1.75;
  color: rgba(220, 232, 248, 0.82);
  max-width: 34ch;
}

.gw-about__film-link {
  position: relative;
  isolation: isolate;
  display: inline-flex;
  align-items: center;
  gap: 0.55rem;
  padding: 0.85rem 1.45rem;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  text-decoration: none;
  color: #d4e8ff;
  background: rgba(255, 255, 255, 0.04);
  border: 2px solid rgba(74, 144, 226, 0.48);
  border-radius: 999px;
  overflow: hidden;
  transition:
    color 0.32s ease,
    border-color 0.32s ease,
    transform 0.24s cubic-bezier(0.22, 1, 0.36, 1),
    box-shadow 0.32s ease;
}

.gw-about__film-link-fill {
  position: absolute;
  inset: 0;
  z-index: -1;
  background: linear-gradient(135deg, #4a90e2 0%, #2c5f9e 52%, #1a3a66 100%);
  transform: translateX(-101%);
  transition: transform 0.45s cubic-bezier(0.22, 1, 0.36, 1);
}

.gw-about__film-link-label,
.gw-about__film-link-icon,
.gw-about__film-link-arrow {
  position: relative;
  z-index: 1;
}

.gw-about__film-link-arrow {
  transition: transform 0.28s cubic-bezier(0.22, 1, 0.36, 1);
}

.gw-about__film-link:hover,
.gw-about__film-link:focus-visible {
  color: #fff;
  border-color: rgba(165, 210, 255, 0.62);
  transform: translateY(-2px);
  box-shadow: 0 14px 36px rgba(74, 144, 226, 0.32);
  outline: none;
}

.gw-about__film-link:hover .gw-about__film-link-fill,
.gw-about__film-link:focus-visible .gw-about__film-link-fill {
  transform: translateX(0);
}

.gw-about__film-link:hover .gw-about__film-link-arrow,
.gw-about__film-link:focus-visible .gw-about__film-link-arrow {
  transform: translate(2px, -2px);
}

.gw-about__film-hint {
  font-family: 'Montserrat', sans-serif;
  font-size: 0.62rem;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: rgba(165, 210, 255, 0.52);
}

.gw-video--about {
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.gw-video--about .gw-video__shell {
  inset: -0.65rem;
  border: 2px solid rgba(44, 95, 158, 0.24);
  border-radius: 16px;
}

.gw-video--about .gw-video__frame {
  border: 2px solid rgba(44, 95, 158, 0.38);
  border-radius: 12px;
  box-shadow:
    0 22px 56px rgba(3, 5, 10, 0.16),
    inset 0 0 0 1px rgba(255, 255, 255, 0.55);
}

/* Video */
.gw-video {
  position: relative;
}

.gw-video__shell {
  position: absolute;
  inset: -0.85rem;
  border-radius: 20px;
  background: linear-gradient(145deg, rgba(74, 144, 226, 0.18) 0%, rgba(44, 95, 158, 0.1) 100%);
  border: 1px solid rgba(74, 144, 226, 0.22);
  box-shadow:
    0 28px 72px rgba(3, 5, 10, 0.14),
    0 0 48px rgba(74, 144, 226, 0.12);
  pointer-events: none;
}

.gw-video__accent {
  position: absolute;
  inset: 0 auto auto 0;
  width: 100%;
  height: 3px;
  border-radius: 20px 20px 0 0;
  background: linear-gradient(
    90deg,
    transparent 0%,
    #2c5f9e 16%,
    #4a90e2 50%,
    #a5d2ff 84%,
    transparent 100%
  );
}

.gw-video__frame {
  position: relative;
  z-index: 1;
  width: 100%;
  aspect-ratio: 16 / 9;
  border-radius: 14px;
  overflow: hidden;
  background: #03050a;
  border: 1px solid rgba(74, 144, 226, 0.45);
  box-shadow:
    0 18px 48px rgba(3, 5, 10, 0.2),
    0 0 0 1px rgba(255, 255, 255, 0.65) inset;
  transform: translateZ(0);
}

.gw-video__frame iframe {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  border: none;
  background: #000;
  transform: translateZ(0);
  backface-visibility: hidden;
}

.gw-section--services {
  position: relative;
  overflow: hidden;
  padding-bottom: clamp(3rem, 7vw, 5rem);
  background:
    linear-gradient(180deg, #f8fbff 0%, #e8f0fa 55%, var(--gw-blue-grey) 100%);
}

.gw-services-section__bg {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 55% 45% at 6% 15%, rgba(74, 144, 226, 0.1) 0%, transparent 68%),
    radial-gradient(ellipse 50% 40% at 94% 82%, rgba(10, 18, 36, 0.06) 0%, transparent 68%),
    linear-gradient(90deg, rgba(3, 5, 10, 0.02) 0%, transparent 18%, transparent 82%, rgba(3, 5, 10, 0.02) 100%);
  pointer-events: none;
}

.gw-section--services .gw-section__bleed {
  padding-inline: clamp(0.65rem, 1.75vw, 1.35rem);
}

.gw-services-section__header {
  position: relative;
  z-index: 1;
  max-width: 42rem;
  margin-inline: auto;
  text-align: center;
}

.gw-services-section__eyebrow {
  display: inline-block;
  margin-bottom: 0.75rem;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.68rem;
  font-weight: 600;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--gw-gold);
}

.gw-services-section__intro {
  margin: 0.85rem auto 0;
  max-width: 36rem;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.92rem;
  line-height: 1.75;
  color: var(--gw-text-muted);
}

/* Services grid */
.gw-services-grid {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: clamp(0.65rem, 1.35vw, 1.1rem);
  margin-top: clamp(1.75rem, 3.5vw, 2.75rem);
}

.gw-services-grid__item {
  min-width: 0;
}

.gw-service-card {
  position: relative;
  display: block;
  height: 100%;
  min-height: clamp(22rem, 34vw, 28rem);
  text-decoration: none;
  color: inherit;
  border-radius: 12px;
  overflow: hidden;
  box-shadow:
    0 10px 40px rgba(3, 5, 10, 0.1),
    0 1px 0 rgba(255, 255, 255, 0.08) inset;
  transition:
    box-shadow 0.5s cubic-bezier(0.22, 1, 0.36, 1),
    transform 0.5s cubic-bezier(0.22, 1, 0.36, 1);
}

.gw-service-card::before {
  content: '';
  position: absolute;
  inset: 0;
  z-index: 4;
  border-radius: inherit;
  border: 1px solid rgba(74, 144, 226, 0.18);
  pointer-events: none;
  transition: border-color 0.45s ease;
}

.gw-service-card:hover {
  transform: translateY(-8px);
  box-shadow:
    0 28px 64px rgba(3, 5, 10, 0.18),
    0 0 0 1px rgba(74, 144, 226, 0.12);
}

.gw-service-card:hover::before {
  border-color: rgba(74, 144, 226, 0.45);
}

.gw-service-card__media {
  position: relative;
  height: 100%;
  min-height: inherit;
}

.gw-service-card__photo-wrap {
  position: absolute;
  inset: 0;
  overflow: hidden;
  transform-origin: center center;
}

.gw-service-card__photo {
  display: block;
  width: 100%;
  height: 100%;
  margin: 0;
  border-radius: 0;
  object-fit: cover;
  object-position: center center;
  transform: scale(1.02);
  filter: contrast(1.04) saturate(1.05);
  image-rendering: auto;
  -webkit-backface-visibility: hidden;
  backface-visibility: hidden;
  will-change: transform;
}

.gw-service-card:hover .gw-service-card__photo {
  filter: contrast(1.06) saturate(1.08);
}

.gw-service-card__photo.gw-placeholder {
  aspect-ratio: unset;
  min-height: 100%;
  height: 100%;
  background:
    linear-gradient(155deg, rgba(3, 5, 10, 0.98) 0%, rgba(14, 24, 48, 0.94) 48%, rgba(26, 36, 56, 0.9) 100%);
  border: none;
}

.gw-service-card__photo .gw-placeholder__label {
  font-size: 0.58rem;
  font-weight: 600;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: rgba(165, 210, 255, 0.38);
}

.gw-service-card__overlay {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(
      180deg,
      rgba(3, 5, 10, 0.12) 0%,
      rgba(3, 5, 10, 0.04) 24%,
      rgba(3, 5, 10, 0.42) 62%,
      rgba(3, 5, 10, 0.9) 100%
    );
  transition: opacity 0.5s ease;
}

.gw-service-card:hover .gw-service-card__overlay {
  opacity: 0.98;
  background:
    linear-gradient(
      180deg,
      rgba(3, 5, 10, 0.1) 0%,
      rgba(3, 5, 10, 0.02) 22%,
      rgba(3, 5, 10, 0.48) 64%,
      rgba(3, 5, 10, 0.94) 100%
    );
}

.gw-service-card__shine {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    115deg,
    transparent 30%,
    rgba(255, 255, 255, 0.14) 50%,
    transparent 70%
  );
  transform: translateX(-130%);
  transition: transform 0.85s cubic-bezier(0.22, 1, 0.36, 1);
}

.gw-service-card:hover .gw-service-card__shine {
  transform: translateX(130%);
}

.gw-service-card__content {
  position: relative;
  z-index: 3;
  display: flex;
  flex-direction: column;
