  min-height: clamp(220px, 38vw, 380px);
  object-fit: cover;
  object-position: center center;
  transform: scale(1.015);
  filter: contrast(1.04) saturate(1.05);
  -webkit-backface-visibility: hidden;
  backface-visibility: hidden;
}

.gw-blog-feature--active .gw-blog-feature__link:hover .gw-blog-feature__photo {
  filter: contrast(1.06) saturate(1.08);
}

.gw-blog-feature__carousel-slide .gw-blog-feature__photo {
  width: 100%;
}

.gw-blog-feature__photo.gw-placeholder {
  min-height: clamp(220px, 38vw, 380px);
  background:
    linear-gradient(145deg, rgba(10, 18, 36, 0.98) 0%, rgba(26, 36, 56, 0.92) 100%);
  border: none;
}

.gw-blog-feature__photo .gw-placeholder__label {
  font-size: 0.58rem;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: rgba(165, 210, 255, 0.4);
}

.gw-blog-feature__overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    180deg,
    rgba(3, 5, 10, 0.02) 0%,
    rgba(3, 5, 10, 0.08) 40%,
    rgba(3, 5, 10, 0.82) 100%
  );
  pointer-events: none;
}

.gw-blog-feature__shine {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    115deg,
    transparent 35%,
    rgba(255, 255, 255, 0.1) 50%,
    transparent 65%
  );
  transform: translateX(-120%);
  transition: transform 0.85s cubic-bezier(0.22, 1, 0.36, 1);
  pointer-events: none;
}

.gw-blog-feature--active .gw-blog-feature__link:hover .gw-blog-feature__shine {
  transform: translateX(120%);
}

.gw-blog-feature__index {
  position: absolute;
  top: 1rem;
  right: 1rem;
  z-index: 2;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.18em;
  color: rgba(255, 255, 255, 0.75);
}

.gw-blog-feature__content {
  position: relative;
  padding: clamp(1.25rem, 3vw, 2rem);
  margin-top: -4.5rem;
  z-index: 2;
}

.gw-blog-feature__tag {
  display: inline-block;
  margin-bottom: 0.65rem;
  padding: 0.32rem 0.7rem;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--gw-navy);
  background: linear-gradient(135deg, #a5c8e8 0%, var(--gw-gold) 100%);
  border-radius: 999px;
}

.gw-blog-feature__title {
  margin: 0 0 0.75rem;
  max-width: 28ch;
  font-family: 'Playfair Display', serif;
  font-size: clamp(1.35rem, 2.8vw, 2rem);
  font-weight: 500;
  line-height: 1.25;
  color: #fff;
  transition: color 0.3s ease;
}

.gw-blog-feature--active .gw-blog-feature__link:hover .gw-blog-feature__title {
  color: var(--gw-gold-light);
}

.gw-blog-feature__excerpt {
  margin: 0 0 1rem;
  max-width: 58ch;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.88rem;
  line-height: 1.75;
  color: rgba(255, 255, 255, 0.72);
}

.gw-blog-feature__cta {
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--gw-gold-light);
}

.gw-blog-feature__cta-icon {
  transition: transform 0.35s cubic-bezier(0.22, 1, 0.36, 1);
}

.gw-blog-feature--active .gw-blog-feature__link:hover .gw-blog-feature__cta-icon {
  transform: translate(3px, -3px);
}

.gw-blog-feature__carousel {
  position: relative;
}

.gw-blog-feature__carousel-track {
  position: relative;
  overflow: hidden;
}

.gw-blog-feature__carousel-slide {
  width: 100%;
}

.gw-blog-feature__carousel-controls {
  position: absolute;
  right: 1rem;
  bottom: 1rem;
  z-index: 3;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.35rem 0.5rem;
  background: rgba(3, 5, 10, 0.55);
  border: 1px solid rgba(74, 144, 226, 0.25);
  border-radius: 999px;
  backdrop-filter: blur(8px);
}

.gw-blog-feature__carousel-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 1.75rem;
  height: 1.75rem;
  padding: 0;
  color: #fff;
  background: transparent;
  border: none;
  border-radius: 50%;
  cursor: pointer;
  transition: color 0.2s ease, background 0.2s ease;
}

.gw-blog-feature__carousel-btn:hover {
  color: var(--gw-navy);
  background: var(--gw-gold);
}

.gw-blog-feature__carousel-dots {
  display: flex;
  gap: 0.35rem;
}

.gw-blog-feature__carousel-dot {
  width: 0.4rem;
  height: 0.4rem;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.35);
  transition: background 0.25s ease, transform 0.25s ease;
}

.gw-blog-feature__carousel-dot.is-active {
  background: var(--gw-gold);
  transform: scale(1.15);
}

.gw-blog-showcase__footer {
  position: relative;
  z-index: 1;
  margin-top: clamp(1.25rem, 3vw, 2rem);
}

.gw-blog-showcase__progress {
  height: 2px;
  margin-bottom: 1.25rem;
  background: rgba(255, 255, 255, 0.12);
  border-radius: 999px;
  overflow: hidden;
}

.gw-blog-showcase__progress-bar {
  display: block;
  width: 100%;
  height: 100%;
  background: linear-gradient(90deg, var(--gw-gold) 0%, #a5c8e8 100%);
  transform-origin: left center;
}

.gw-blog-showcase__thumbs {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: clamp(0.75rem, 2vw, 1rem);
}

.gw-blog-showcase__thumb {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
  padding: 1rem 1.1rem;
  text-align: left;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(74, 144, 226, 0.14);
  border-radius: 12px;
  cursor: pointer;
  transition:
    background 0.35s ease,
    border-color 0.35s ease,
    transform 0.35s cubic-bezier(0.22, 1, 0.36, 1);
}

.gw-blog-showcase__thumb:hover,
.gw-blog-showcase__thumb.is-active {
  background: rgba(74, 144, 226, 0.1);
  border-color: rgba(74, 144, 226, 0.35);
}

.gw-blog-showcase__thumb.is-active {
  transform: translateY(-3px);
}

.gw-blog-showcase__thumb-tag {
  font-family: 'Montserrat', sans-serif;
  font-size: 0.58rem;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--gw-gold-light);
}

.gw-blog-showcase__thumb-title {
  font-family: 'Playfair Display', serif;
  font-size: 0.95rem;
  line-height: 1.35;
  color: rgba(255, 255, 255, 0.88);
}

.gw-section--closing {
  position: relative;
  text-align: center;
  background:
    linear-gradient(135deg, rgba(3, 5, 10, 0.9) 0%, rgba(10, 18, 36, 0.85) 100%),
    var(--gw-navy);
  color: #fff;
}

/* Clients grid — legacy static layout (replaced by marquee) */
.gw-clients-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: clamp(0.75rem, 2vw, 1.25rem);
}

.gw-client-cell {
  display: block;
  text-decoration: none;
  transition: transform 0.25s ease;
}

.gw-client-cell:hover {
  transform: scale(1.03);
}

.gw-client-cell .gw-placeholder {
  min-height: 80px;
  background: #fff;
  border-color: rgba(74, 144, 226, 0.25);
}

/* Clients — premium logo marquee */
.gw-clients-marquee {
  position: relative;
  padding: 0;
  overflow: hidden;
}

.gw-clients-marquee__edge {
  position: absolute;
  top: 0;
  bottom: 0;
  width: clamp(3rem, 8vw, 6rem);
  z-index: 2;
  pointer-events: none;
}

.gw-clients-marquee__edge--left {
  left: 0;
  background: linear-gradient(90deg, rgba(6, 11, 20, 0.95) 0%, transparent 100%);
}

.gw-clients-marquee__edge--right {
  right: 0;
  background: linear-gradient(270deg, rgba(6, 11, 20, 0.95) 0%, transparent 100%);
}

.gw-clients-marquee::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 50% 40% at 50% 50%, rgba(74, 144, 226, 0.1), transparent 72%);
  pointer-events: none;
}

.gw-clients-marquee__stage {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  gap: clamp(1.35rem, 3vw, 2rem);
  padding-block: clamp(0.5rem, 1.5vw, 1rem);
}

.gw-clients-marquee__divider {
  height: 1px;
  margin-inline: clamp(1rem, 5vw, 4rem);
  background: linear-gradient(
    90deg,
    transparent 0%,
    rgba(74, 144, 226, 0.35) 20%,
    rgba(165, 210, 255, 0.55) 50%,
    rgba(74, 144, 226, 0.35) 80%,
    transparent 100%
  );
  opacity: 0.75;
}

.gw-clients-marquee__row {
  width: 100%;
}

.gw-clients-marquee__viewport {
  overflow: hidden;
  mask-image: linear-gradient(
    90deg,
    transparent 0%,
    #000 10%,
    #000 90%,
    transparent 100%
  );
}

.gw-clients-marquee__viewport--static {
  overflow-x: auto;
  overflow-y: hidden;
  scrollbar-width: thin;
  scrollbar-color: rgba(74, 144, 226, 0.35) transparent;
  -webkit-overflow-scrolling: touch;
}

.gw-clients-marquee__track {
  display: flex;
  flex-wrap: nowrap;
  align-items: flex-start;
  gap: clamp(1rem, 2.2vw, 1.65rem);
  width: max-content;
  padding-inline: clamp(1rem, 3vw, 2rem);
}

.gw-clients-marquee__track--animate {
  animation: gw-clients-marquee-scroll var(--marquee-duration, 48s) linear infinite;
  will-change: transform;
}

.gw-clients-marquee__row--reverse .gw-clients-marquee__track--animate {
  animation-name: gw-clients-marquee-scroll-reverse;
}

.gw-clients-marquee__viewport:hover .gw-clients-marquee__track--animate {
  animation-play-state: paused;
}

@keyframes gw-clients-marquee-scroll {
  from { transform: translateX(0); }
  to { transform: translateX(-50%); }
}

@keyframes gw-clients-marquee-scroll-reverse {
  from { transform: translateX(-50%); }
  to { transform: translateX(0); }
}

.gw-clients-marquee__item {
  flex: 0 0 auto;
  width: clamp(12rem, 23vw, 16.5rem);
  margin: 0;
  text-align: center;
}

.gw-clients-marquee__card {
  position: relative;
  display: grid;
  place-items: center;
  min-height: clamp(6rem, 11vw, 7.25rem);
  padding: clamp(0.95rem, 2.2vw, 1.25rem) clamp(1.1rem, 2.4vw, 1.5rem);
  overflow: hidden;
  background:
    linear-gradient(160deg, rgba(22, 48, 88, 0.94) 0%, rgba(9, 22, 44, 0.97) 100%);
  border: 1px solid rgba(130, 176, 255, 0.34);
  border-radius: 16px;
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.08) inset,
    0 18px 42px -22px rgba(0, 0, 0, 0.7),
    0 0 0 1px rgba(63, 127, 255, 0.16);
  transition:
    transform 0.4s cubic-bezier(0.22, 1, 0.36, 1),
    border-color 0.4s ease,
    box-shadow 0.4s ease;
}

.gw-clients-marquee__card-glow {
  position: absolute;
  inset: -40%;
  background: radial-gradient(circle, rgba(74, 144, 226, 0.18) 0%, transparent 68%);
  opacity: 0;
  transition: opacity 0.4s ease;
  pointer-events: none;
}

.gw-clients-marquee__card img {
  position: relative;
  z-index: 1;
  display: block;
  width: 100%;
  max-width: 11.5rem;
  height: clamp(2.85rem, 5.2vw, 3.65rem);
  object-fit: contain;
  object-position: center;
  /* Uniform white monochrome treatment so every logo matches on the navy card */
  filter: brightness(0) invert(1);
  opacity: 0.88;
  transition:
    filter 0.4s ease,
    opacity 0.4s ease,
    transform 0.4s cubic-bezier(0.22, 1, 0.36, 1);
}

.gw-clients-marquee__card--text {
  padding-inline: clamp(0.85rem, 2vw, 1.15rem);
}

.gw-clients-marquee__card-name {
  position: relative;
  z-index: 1;
  display: block;
  max-width: 100%;
  font-family: 'Montserrat', sans-serif;
  font-size: clamp(0.72rem, 1.15vw, 0.92rem);
  font-weight: 800;
  line-height: 1.25;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  text-align: center;
  text-wrap: balance;
  color: #1a3a66;
}

/* Premium gradient wordmark for text-only client cards */
.gw-clients-marquee__card--text .gw-clients-marquee__card-name {
  background: linear-gradient(180deg, #f2f8ff 0%, #b9d3ff 55%, #7fa8ee 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  text-shadow: 0 0 18px rgba(127, 168, 238, 0.25);
}

.gw-clients-marquee__caption {
  margin: 0.8rem 0 0;
  padding-top: 0.55rem;
}

.gw-clients-marquee__caption-text {
  display: block;
  max-width: 100%;
  font-family: 'Montserrat', sans-serif;
  font-size: clamp(0.74rem, 1.15vw, 0.92rem);
  font-weight: 800;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: rgba(244, 248, 255, 0.94);
  text-shadow: 0 2px 16px rgba(74, 144, 226, 0.28);
  position: relative;
  padding-bottom: 0.35rem;
  white-space: normal;
  text-wrap: balance;
  line-height: 1.35;
}

.gw-clients-marquee__caption-text::after {
  content: '';
  position: absolute;
  left: 50%;
  bottom: 0;
  width: 1.75rem;
  height: 2px;
  transform: translateX(-50%) scaleX(0.35);
  border-radius: 999px;
  background: linear-gradient(90deg, transparent, #4a90e2, transparent);
  transition: transform 0.4s cubic-bezier(0.22, 1, 0.36, 1), width 0.4s ease;
}

@media (hover: hover) {
  .gw-clients-marquee__item:hover .gw-clients-marquee__card {
    border-color: rgba(143, 186, 255, 0.7);
    box-shadow:
      0 1px 0 rgba(255, 255, 255, 0.14) inset,
      0 24px 48px -18px rgba(0, 0, 0, 0.72),
      0 0 32px rgba(63, 127, 255, 0.3);
  }

  .gw-clients-marquee__item:hover .gw-clients-marquee__card-glow {
    opacity: 1;
  }

  .gw-clients-marquee__item:hover .gw-clients-marquee__card img {
    opacity: 1;
    transform: scale(1.04);
  }

  .gw-clients-marquee__item:hover .gw-clients-marquee__caption-text {
    color: #ffffff;
    text-shadow: 0 2px 20px rgba(74, 144, 226, 0.45);
  }

  .gw-clients-marquee__item:hover .gw-clients-marquee__caption-text::after {
    width: 2.75rem;
    transform: translateX(-50%) scaleX(1);
  }
}

@media (max-width: 768px) {
  .gw-clients-section__ribbon {
    flex-wrap: wrap;
    justify-content: center;
    text-align: center;
  }

  .gw-clients-marquee__item {
    width: clamp(11rem, 74vw, 14rem);
  }

  .gw-clients-marquee__card {
    min-height: clamp(5.5rem, 20vw, 6.5rem);
  }

  .gw-clients-marquee__caption-text {
    font-size: 0.72rem;
    letter-spacing: 0.12em;
  }
}

@media (prefers-reduced-motion: reduce) {
  .gw-clients-section__aurora--one,
  .gw-clients-section__aurora--two,
  .gw-clients-marquee__track--animate {
    animation: none !important;
  }

  .gw-leader__logo-ring,
  .gw-leader__logo-glow {
    animation: none !important;
  }
}

/* Leader */
.gw-leader {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: clamp(2rem, 5vw, 4rem);
  align-items: center;
}

.gw-leader__title {
  margin: 0 0 1.25rem;
  font-family: 'Playfair Display', serif;
  font-size: clamp(1.5rem, 3.5vw, 2.25rem);
  font-weight: 500;
  line-height: 1.2;
  color: #fff;
}

.gw-leader__para {
  margin: 0 0 1rem;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.95rem;
  line-height: 1.75;
  color: rgba(255, 255, 255, 0.82);
}

.gw-leader__para--last {
  margin-bottom: 1.75rem;
}

.gw-btn-more {
  display: inline-flex;
  align-items: center;
  padding: 0.65rem 1.5rem;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  text-decoration: none;
  color: var(--gw-navy);
  background: linear-gradient(135deg, #a5c8e8 0%, var(--gw-gold) 100%);
  border-radius: 2px;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.gw-btn-more:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 24px rgba(74, 144, 226, 0.35);
}

.gw-leader__media {
  position: relative;
  justify-self: center;
  width: min(100%, 520px);
}

.gw-leader__logo-frame {
  position: relative;
  aspect-ratio: 1 / 1;
  border-radius: 18px;
  isolation: isolate;
}

.gw-leader__logo-ring {
  position: absolute;
  inset: -3px;
  z-index: 2;
  border-radius: inherit;
  padding: 3px;
  background: conic-gradient(
    from 0deg,
    #4a90e2 0deg,
    #a5d2ff 70deg,
    #2c5f9e 140deg,
    transparent 180deg,
    transparent 220deg,
    #4a90e2 280deg,
    #a5d2ff 340deg,
    #4a90e2 360deg
  );
  -webkit-mask:
    linear-gradient(#fff 0 0) content-box,
    linear-gradient(#fff 0 0);
  mask:
    linear-gradient(#fff 0 0) content-box,
    linear-gradient(#fff 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
  animation: gw-leader-logo-ring-spin 7s linear infinite;
  pointer-events: none;
}

.gw-leader__logo-glow {
  position: absolute;
  inset: -10%;
  z-index: 0;
  border-radius: inherit;
  background: radial-gradient(circle, rgba(74, 144, 226, 0.42) 0%, transparent 68%);
  filter: blur(12px);
  animation: gw-leader-logo-glow 3.6s ease-in-out infinite alternate;
  pointer-events: none;
}

@keyframes gw-leader-logo-ring-spin {
  to {
    transform: rotate(360deg);
  }
}

@keyframes gw-leader-logo-glow {
  from {
    opacity: 0.45;
    transform: scale(0.96);
  }

  to {
    opacity: 1;
    transform: scale(1.04);
  }
}

.gw-leader__logo {
  position: relative;
  z-index: 1;
  display: block;
  width: 100%;
  height: 100%;
  aspect-ratio: 1 / 1;
  object-fit: cover;
  object-position: center center;
  border-radius: 14px;
  border: 3px solid rgba(74, 144, 226, 0.85);
  box-shadow:
    0 0 0 1px rgba(165, 210, 255, 0.25) inset,
    0 28px 72px rgba(3, 5, 10, 0.48),
    0 0 40px rgba(74, 144, 226, 0.28);
  transition:
    transform 0.55s cubic-bezier(0.22, 1, 0.36, 1),
    box-shadow 0.55s cubic-bezier(0.22, 1, 0.36, 1);
}

.gw-leader__logo-frame:hover .gw-leader__logo {
  transform: scale(1.015);
  box-shadow:
    0 0 0 1px rgba(165, 210, 255, 0.35) inset,
    0 32px 80px rgba(3, 5, 10, 0.52),
    0 0 56px rgba(74, 144, 226, 0.42);
}

/* Team */

/* Stats */
.gw-stats-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: clamp(1.5rem, 3vw, 2.5rem);
  text-align: center;
}

.gw-stat__icon {
  display: inline-grid;
  place-items: center;
  width: clamp(3.4rem, 6vw, 4.2rem);
  height: clamp(3.4rem, 6vw, 4.2rem);
  margin: 0 auto;
  border-radius: 50%;
  color: #cfe2ff;
  background: radial-gradient(circle at 30% 25%, rgba(90, 143, 230, 0.35), rgba(20, 44, 88, 0.55));
  border: 1px solid rgba(130, 176, 255, 0.4);
  box-shadow:
    0 10px 26px -12px rgba(28, 71, 160, 0.7),
    inset 0 1px 0 rgba(255, 255, 255, 0.18);
  transition:
    transform 0.4s cubic-bezier(0.22, 1, 0.36, 1),
    box-shadow 0.4s ease,
    border-color 0.4s ease,
    color 0.4s ease;
}

.gw-stat:hover .gw-stat__icon {
  transform: translateY(-4px) scale(1.06);
  color: #eaf3ff;
  border-color: rgba(143, 186, 255, 0.7);
  box-shadow:
    0 16px 34px -12px rgba(28, 71, 160, 0.85),
    0 0 22px -4px rgba(63, 127, 255, 0.55),
    inset 0 1px 0 rgba(255, 255, 255, 0.28);
}

@media (prefers-reduced-motion: reduce) {
  .gw-stat:hover .gw-stat__icon {
    transform: none;
  }
}

.gw-stat__value {
