/* Responsive */
@media (max-width: 1024px) {
  .gw-services-grid,
  .gw-clients-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .gw-service-card {
    min-height: clamp(20rem, 42vw, 24rem);
  }

  .gw-team-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .gw-team-card {
    grid-column: auto;
    min-height: clamp(20rem, 42vw, 26rem);
  }

  .gw-team-card:nth-child(4):nth-last-child(2),
  .gw-team-card:nth-child(5):last-child {
    grid-column: auto;
  }

  .gw-leader {
    grid-template-columns: 1fr;
  }

  .gw-blog-showcase__thumbs {
    grid-template-columns: 1fr;
  }

  .gw-blog-showcase__nav {
    width: 2.5rem;
    height: 2.5rem;
  }

  .gw-stats-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 960px) {
  .gw-subnav__bar--desktop {
    display: none;
  }

  .gw-subnav__bar--mobile {
    display: flex;
  }
}

@media (max-width: 640px) {
  .gw-subnav__menu {
    grid-template-columns: 1fr;
  }

  .gw-services-grid,
  .gw-clients-grid,
  .gw-stats-grid {
    grid-template-columns: 1fr;
  }

  .gw-service-card {
    min-height: clamp(18rem, 62vw, 22rem);
  }

  .gw-section--services .gw-section__bleed {
    padding-inline: clamp(0.85rem, 4vw, 1.25rem);
  }

  .gw-team-grid {
    grid-template-columns: 1fr;
  }

  .gw-team-card {
    grid-column: auto;
    min-height: clamp(18rem, 62vw, 24rem);
  }

  .gw-section--team .gw-section__bleed {
    padding-inline: clamp(0.85rem, 4vw, 1.25rem);
  }

  .gw-blog-feature {
    flex-basis: min(920px, 92vw);
  }

  .gw-blog-feature__content {
    margin-top: -3rem;
  }

  .gw-video__shell {
    inset: -0.5rem;
    border-radius: 16px;
  }

  .gw-video__frame {
    border-radius: 12px;
  }

  .gw-about__layout {
    grid-template-columns: 1fr;
  }

  .gw-about__highlights {
    grid-template-columns: 1fr;
  }
}

@media (prefers-reduced-motion: reduce) {
  .gw-hero__slide {
    transition: none;
  }

  .gw-hero__scroll {
    animation: none;
  }

  .gw-service-card:hover,
  .gw-team-card:hover,
  .gw-client-cell:hover,
  .gw-hero__cta:hover,
  .gw-btn-more:hover,
  .gw-subnav__cta:hover,
  .gw-subnav__link:hover,
  .gw-subnav__menu-link:hover {
    transform: none;
  }

  .gw-subnav__link:hover {
