@media (max-width: 1024px) {
  .gw-jobs-intro,
  .gw-jobs-markets,
  .gw-jobs-network {
    grid-template-columns: 1fr;
  }

  .gw-jobs-intro__media {
    order: -1;
  }

  .gw-jobs-markets__grid {
    grid-template-columns: 1fr;
  }

  .gw-jobs-markets__region:nth-child(1) {
    grid-column: span 1;
  }

  .gw-jobs-positions__shell {
    grid-template-columns: 1fr;
  }

  .gw-jobs-positions__nav {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .gw-jobs-positions__tab--active {
    transform: none;
  }

  .gw-jobs-why-grid {
    grid-template-columns: 1fr;
  }

  .gw-jobs-why-card,
  .gw-jobs-why-card--featured {
    grid-column: span 1;
  }

  .gw-jobs-timeline {
    grid-template-columns: repeat(2, 1fr);
  }

  .gw-jobs-timeline__step::after {
    display: none;
  }
}

@media (max-width: 640px) {
  .gw-jobs-positions__nav {
    grid-template-columns: 1fr;
  }

  .gw-jobs-positions__panel-foot {
    flex-direction: column;
    align-items: stretch;
  }

  .gw-jobs-positions__cta {
    justify-content: center;
  }

  .gw-jobs-why-grid,
  .gw-jobs-timeline {
    grid-template-columns: 1fr;
  }

  .gw-jobs-closing__actions {
    flex-direction: column;
    align-items: stretch;
  }
}

@media (prefers-reduced-motion: reduce) {
  .gw-jobs-why-card:hover,
  .gw-jobs-positions__tab--active,
  .gw-jobs-positions__role:hover,
  .gw-jobs-positions__cta:hover,
  .gw-jobs-network__cta:hover,
  .gw-jobs-closing__btn--primary:hover {
    transform: none;
  }
}

