.gw-trainings-section--why {
  background: #fff;
}

.gw-trainings-why-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: clamp(1rem, 2vw, 1.35rem);
}

.gw-trainings-why-card {
  padding: clamp(1.35rem, 2.5vw, 1.75rem);
