  border-radius: 6px;
  transition: transform 0.3s ease, box-shadow 0.3s ease;
}

.gw-trainings-why-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 12px 40px rgba(3, 5, 10, 0.08);
}

.gw-trainings-why-card__icon-wrap {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 2.75rem;
  height: 2.75rem;
  margin-bottom: 1rem;
  color: var(--gw-gold);
  background: rgba(74, 144, 226, 0.1);
  border-radius: 50%;
}

.gw-trainings-why-card__icon {
  width: 1.25rem;
  height: 1.25rem;
}

.gw-trainings-why-card__title {
  margin: 0 0 0.55rem;
  font-family: 'Playfair Display', serif;
  font-size: 1.08rem;
  font-weight: 500;
  color: var(--gw-text);
}

.gw-trainings-why-card__text {
  margin: 0;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.86rem;
  line-height: 1.7;
  color: var(--gw-text-muted);
}

.gw-trainings-section--closing {
  background:
    linear-gradient(135deg, rgba(3, 5, 10, 0.94) 0%, rgba(10, 18, 36, 0.9) 100%),
    var(--gw-navy);
}

.gw-trainings-closing {
  text-align: center;
}

.gw-trainings-closing__inner {
  max-width: 44rem;
  margin-inline: auto;
}

.gw-trainings-closing__title {
  margin: 0 0 1rem;
  font-family: 'Playfair Display', serif;
  font-size: clamp(1.85rem, 4vw, 2.75rem);
  font-weight: 500;
  line-height: 1.12;
  color: #fff;
}

.gw-trainings-closing__para {
  margin: 0;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.95rem;
  line-height: 1.75;
  color: rgba(255, 255, 255, 0.82);
}

.gw-trainings-closing__actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 0.85rem;
  margin-top: 1.75rem;
}

.gw-trainings-closing__btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 11rem;
  padding: 0.9rem 1.75rem;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  text-decoration: none;
  border-radius: 2px;
  transition: transform 0.25s ease, box-shadow 0.25s ease, background 0.25s ease;
}

.gw-trainings-closing__btn--primary {
  color: var(--gw-navy);
  background: linear-gradient(135deg, #a5c8e8 0%, var(--gw-gold) 100%);
  border: 1px solid rgba(220, 235, 255, 0.35);
}

.gw-trainings-closing__btn--primary:hover {
  transform: translateY(-2px);
  box-shadow: 0 12px 32px rgba(74, 144, 226, 0.35);
}

.gw-trainings-closing__btn--secondary {
  color: #fff;
  background: transparent;
  border: 1px solid rgba(74, 144, 226, 0.55);
}

.gw-trainings-closing__btn--secondary:hover {
  background: rgba(74, 144, 226, 0.12);
}

@media (max-width: 1024px) {
  .gw-trainings-intro,
  .gw-trainings-line,
  .gw-trainings-captain {
    grid-template-columns: 1fr;
  }

  .gw-trainings-intro__media,
  .gw-trainings-line__media,
  .gw-trainings-captain__media {
    order: -1;
  }

  .gw-trainings-services-grid,
  .gw-trainings-services-grid .gw-trainings-service-card:nth-child(4),
  .gw-trainings-services-grid .gw-trainings-service-card:nth-child(5) {
    grid-column: auto;
  }

  .gw-trainings-services-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .gw-trainings-includes-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .gw-trainings-meta-grid,
  .gw-trainings-captain-grid {
    grid-template-columns: 1fr;
  }

  .gw-trainings-why-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 640px) {
  .gw-trainings-services-grid,
  .gw-trainings-includes-grid,
  .gw-trainings-benefits-grid,
  .gw-trainings-why-grid {
    grid-template-columns: 1fr;
  }

  .gw-trainings-closing__actions {
    flex-direction: column;
    align-items: stretch;
  }
}

@media (prefers-reduced-motion: reduce) {
  .gw-trainings-service-card:hover,
  .gw-trainings-why-card:hover,
  .gw-trainings-closing__btn--primary:hover {
    transform: none;
  }
}

