  border-radius: 18px;
  box-shadow: 0 22px 56px rgba(3, 5, 10, 0.08);
}

.gw-cadet-programme-feature__accent {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 4px;
  background: linear-gradient(90deg, #2c5f9e 0%, #4a90e2 50%, #a5d2ff 100%);
}

.gw-cadet-programme-feature__head {
  display: flex;
  gap: 1rem;
  align-items: flex-start;
  margin-bottom: 1rem;
}

.gw-cadet-programme-feature__icon-wrap {
  display: grid;
  place-items: center;
  flex-shrink: 0;
  width: 3rem;
  height: 3rem;
  color: #fff;
  background: linear-gradient(135deg, #4a90e2 0%, #2c5f9e 100%);
  border-radius: 12px;
  box-shadow: 0 10px 24px rgba(74, 144, 226, 0.28);
}

.gw-cadet-programme-feature__icon {
  width: 1.35rem;
  height: 1.35rem;
}

.gw-cadet-programme-feature__eyebrow {
  margin: 0 0 0.35rem;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.62rem;
  font-weight: 600;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--gw-accent-deep);
}

.gw-cadet-programme-feature__title {
  margin: 0;
  font-family: 'Playfair Display', serif;
  font-size: clamp(1.35rem, 2.5vw, 1.85rem);
  font-weight: 500;
  line-height: 1.15;
  color: var(--gw-text);
}

.gw-cadet-programme-feature__text {
  margin: 0 0 1.25rem;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.95rem;
  line-height: 1.8;
  color: var(--gw-text-muted);
}

.gw-cadet-programme-feature__salary {
  padding-top: 1rem;
  border-top: 2px solid rgba(74, 144, 226, 0.14);
}

.gw-cadet-programme-feature__salary-label {
  display: block;
  margin-bottom: 0.25rem;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.58rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--gw-accent-deep);
}

.gw-cadet-programme-feature__salary strong {
  font-family: 'Playfair Display', serif;
  font-size: 1.35rem;
  font-weight: 500;
  color: var(--gw-text);
}

/* Cadet — why bento */
.gw-cadet-why__header {
  max-width: 44rem;
}

.gw-cadet-why__intro {
  margin: 0.85rem 0 0;
  font-family: 'Montserrat', sans-serif;
