}

/* Cadet — FAQ premium */
.gw-cadet-faq-layout {
  max-width: 52rem;
}

.gw-cadet-faq__header {
  max-width: 44rem;
  margin-inline: auto;
  text-align: center;
}

.gw-cadet-faq__intro {
  margin: 0.85rem auto 0;
  max-width: 38rem;
  font-family: 'Montserrat', sans-serif;
