.gw-cadet-faq__item--featured {
  border-color: rgba(74, 144, 226, 0.32);
}

.gw-cadet-faq__item--open {
  border-color: rgba(74, 144, 226, 0.45);
  box-shadow: 0 18px 44px rgba(3, 5, 10, 0.1);
}

.gw-cadet-faq__accent {
