  }
}

/* Trainings — premium closing CTA */
.gw-trainings-section--closing {
  position: relative;
  overflow: hidden;
}

.gw-trainings-closing__bg {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 55% 50% at 8% 20%, rgba(74, 144, 226, 0.16) 0%, transparent 62%),
    radial-gradient(ellipse 45% 45% at 96% 78%, rgba(44, 95, 158, 0.12) 0%, transparent 58%);
  pointer-events: none;
}

.gw-trainings-closing {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: 1.15fr 0.85fr;
  gap: clamp(2rem, 5vw, 3.5rem);
  align-items: center;
  text-align: left;
}

.gw-trainings-closing__copy {
  max-width: 38rem;
}

.gw-trainings-closing__eyebrow {
  margin: 0 0 0.75rem;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: rgba(165, 210, 255, 0.72);
}

.gw-trainings-closing__title {
  margin: 0 0 1rem;
  font-family: 'Playfair Display', serif;
  font-size: clamp(1.85rem, 4vw, 2.75rem);
  font-weight: 500;
  line-height: 1.12;
  color: #fff;
}

.gw-trainings-closing__title-em {
  display: inline;
  background: linear-gradient(135deg, #a5d2ff 0%, #4a90e2 55%, #d4e8ff 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

.gw-trainings-closing__title::after {
  content: '';
  display: block;
  width: 4.5rem;
  height: 3px;
  margin-top: 0.85rem;
  border-radius: 999px;
  background: linear-gradient(90deg, #4a90e2 0%, #a5d2ff 100%);
}

.gw-trainings-closing__para {
  margin: 0;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.95rem;
  line-height: 1.8;
  color: rgba(255, 255, 255, 0.82);
}

.gw-trainings-closing__stats {
  display: flex;
  flex-wrap: wrap;
  gap: 0.65rem;
  margin: 1.35rem 0 0;
  padding: 0;
  list-style: none;
}

.gw-trainings-closing__stats li {
  display: flex;
  flex-direction: column;
  min-width: 6.25rem;
  padding: 0.7rem 1rem;
  background: rgba(255, 255, 255, 0.04);
  border: 2px solid rgba(74, 144, 226, 0.28);
  border-radius: 12px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.18);
}

.gw-trainings-closing__stat-value {
  font-family: 'Playfair Display', serif;
  font-size: 1.2rem;
  font-weight: 500;
  line-height: 1.1;
  color: #a5d2ff;
}

.gw-trainings-closing__stat-label {
  margin-top: 0.2rem;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.58rem;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: rgba(165, 210, 255, 0.62);
}

.gw-trainings-closing__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  margin-top: 1.5rem;
}

.gw-trainings-closing__cta {
  position: relative;
  isolation: isolate;
  display: inline-flex;
  align-items: center;
  gap: 0.55rem;
  padding: 0.88rem 1.75rem;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  text-decoration: none;
  border-radius: 999px;
  overflow: hidden;
  transition:
    color 0.38s cubic-bezier(0.22, 1, 0.36, 1),
    border-color 0.38s ease,
    box-shadow 0.38s ease,
    transform 0.28s cubic-bezier(0.22, 1, 0.36, 1),
    background 0.38s ease;
}

.gw-trainings-closing__cta--primary {
  color: #d4e8ff;
  background: rgba(255, 255, 255, 0.04);
  border: 2px solid rgba(74, 144, 226, 0.55);
  box-shadow:
    0 8px 28px rgba(0, 0, 0, 0.22),
    inset 0 0 0 1px rgba(165, 210, 255, 0.06);
}

.gw-trainings-closing__cta--secondary {
  color: rgba(255, 255, 255, 0.88);
  background: transparent;
  border: 2px solid rgba(74, 144, 226, 0.32);
}

.gw-trainings-closing__cta-fill {
  position: absolute;
  inset: 0;
  z-index: -1;
  background: linear-gradient(135deg, #4a90e2 0%, #2c5f9e 52%, #1a3a66 100%);
  transform: translateX(-101%);
  transition: transform 0.52s cubic-bezier(0.22, 1, 0.36, 1);
}

.gw-trainings-closing__cta-fill::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(
    115deg,
    transparent 0%,
    rgba(255, 255, 255, 0.22) 48%,
    transparent 92%
  );
  transform: translateX(-120%);
  transition: transform 0.65s cubic-bezier(0.22, 1, 0.36, 1);
}

.gw-trainings-closing__cta-label,
.gw-trainings-closing__cta-icon {
  position: relative;
  z-index: 1;
}

.gw-trainings-closing__cta-icon {
  flex-shrink: 0;
  transition: transform 0.38s cubic-bezier(0.22, 1, 0.36, 1);
}

.gw-trainings-closing__cta--primary:hover,
.gw-trainings-closing__cta--primary:focus-visible {
  color: #fff;
  border-color: rgba(165, 210, 255, 0.72);
  transform: translateY(-2px);
  box-shadow:
    0 16px 40px rgba(74, 144, 226, 0.38),
    0 0 28px rgba(74, 144, 226, 0.18);
  outline: none;
}

.gw-trainings-closing__cta--primary:hover .gw-trainings-closing__cta-fill,
.gw-trainings-closing__cta--primary:focus-visible .gw-trainings-closing__cta-fill {
  transform: translateX(0);
}

.gw-trainings-closing__cta--primary:hover .gw-trainings-closing__cta-fill::after,
.gw-trainings-closing__cta--primary:focus-visible .gw-trainings-closing__cta-fill::after {
  transform: translateX(120%);
}

.gw-trainings-closing__cta--primary:hover .gw-trainings-closing__cta-icon,
.gw-trainings-closing__cta--primary:focus-visible .gw-trainings-closing__cta-icon {
  transform: translateX(4px);
}

.gw-trainings-closing__cta--secondary:hover,
.gw-trainings-closing__cta--secondary:focus-visible {
  color: #fff;
  background: rgba(74, 144, 226, 0.12);
  border-color: rgba(74, 144, 226, 0.55);
  transform: translateY(-2px);
  outline: none;
}

.gw-trainings-closing__cta--secondary:hover .gw-trainings-closing__cta-icon,
.gw-trainings-closing__cta--secondary:focus-visible .gw-trainings-closing__cta-icon {
  transform: translateX(4px);
}

.gw-trainings-closing__panel {
  position: relative;
  overflow: hidden;
  padding: clamp(1.5rem, 3vw, 2rem);
  background: rgba(255, 255, 255, 0.04);
  border: 2px solid rgba(74, 144, 226, 0.32);
  border-radius: 18px;
  box-shadow:
    0 22px 56px rgba(0, 0, 0, 0.28),
    0 0 0 1px rgba(165, 210, 255, 0.05) inset;
}

.gw-trainings-closing__panel-accent {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 4px;
  background: linear-gradient(90deg, #2c5f9e 0%, #4a90e2 50%, #a5d2ff 100%);
}

.gw-trainings-closing__panel-eyebrow {
  margin: 0 0 0.5rem;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: rgba(165, 210, 255, 0.72);
}

.gw-trainings-closing__panel-title {
  margin: 0 0 1.15rem;
  font-family: 'Playfair Display', serif;
  font-size: clamp(1.35rem, 2.5vw, 1.75rem);
  font-weight: 500;
  line-height: 1.2;
  color: #f4f8ff;
}

.gw-trainings-closing__panel-list {
  margin: 0;
  padding: 0;
  list-style: none;
  display: grid;
  gap: 0.65rem;
}

.gw-trainings-closing__panel-list li {
  position: relative;
  padding-left: 1.1rem;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.88rem;
  line-height: 1.55;
  color: rgba(220, 232, 248, 0.82);
}

.gw-trainings-closing__panel-list li::before {
  content: '';
  position: absolute;
  left: 0;
  top: 0.55em;
  width: 0.35rem;
  height: 0.35rem;
  border-radius: 50%;
  background: linear-gradient(135deg, #4a90e2 0%, #a5d2ff 100%);
  box-shadow: 0 0 8px rgba(74, 144, 226, 0.45);
}

@media (max-width: 900px) {
  .gw-trainings-closing {
    grid-template-columns: 1fr;
  }

  .gw-trainings-closing__panel {
    order: -1;
  }
}

@media (prefers-reduced-motion: reduce) {
  .gw-trainings-closing__cta,
  .gw-trainings-closing__cta-fill,
  .gw-trainings-closing__cta-fill::after,
  .gw-trainings-closing__cta-icon {
    transition: none;
  }

  .gw-trainings-closing__cta--primary:hover,
  .gw-trainings-closing__cta--primary:focus-visible {
    transform: none;
  }

  .gw-trainings-closing__cta--primary:hover .gw-trainings-closing__cta-fill,
  .gw-trainings-closing__cta--primary:focus-visible .gw-trainings-closing__cta-fill {
    transform: translateX(0);
  }
}

/* Trainings — dynamic beat timeline */
.gw-trainings-section--timeline {
  position: relative;
  overflow: hidden;
}

.gw-trainings-timeline-explorer__bg {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 50% 45% at 15% 15%, rgba(74, 144, 226, 0.14) 0%, transparent 60%),
    radial-gradient(ellipse 40% 40% at 88% 85%, rgba(44, 95, 158, 0.1) 0%, transparent 58%);
  pointer-events: none;
}

.gw-trainings-timeline-explorer {
  position: relative;
  z-index: 1;
