    0 14px 36px rgba(74, 144, 226, 0.42),
    0 0 24px rgba(74, 144, 226, 0.28);
  transform: scale(1.08);
}

.gw-trainings-beat--active .gw-trainings-beat__icon {
  transform: scale(1.06);
}

.gw-trainings-beat--active .gw-trainings-beat__index {
