}

.gw-trainings-beat-panel__head {
  display: grid;
  grid-template-columns: auto 1fr auto;
  gap: 1rem;
  align-items: start;
  margin-bottom: 1.25rem;
  padding-bottom: 1.15rem;
  border-bottom: 2px solid rgba(74, 144, 226, 0.16);
}

.gw-trainings-beat-panel__icon-wrap {
  display: grid;
  place-items: center;
  width: 3rem;
  height: 3rem;
  color: #fff;
  background: linear-gradient(135deg, #4a90e2 0%, #2c5f9e 100%);
  border-radius: 12px;
  box-shadow: 0 10px 24px rgba(74, 144, 226, 0.28);
}

.gw-trainings-beat-panel__icon {
  width: 1.35rem;
  height: 1.35rem;
}

.gw-trainings-beat-panel__phase {
  margin: 0 0 0.35rem;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: rgba(165, 210, 255, 0.72);
}

.gw-trainings-beat-panel__title {
  margin: 0;
  font-family: 'Playfair Display', serif;
  font-size: clamp(1.25rem, 2.5vw, 1.65rem);
  font-weight: 500;
  line-height: 1.2;
  color: #f4f8ff;
}

.gw-trainings-beat-panel__counter {
  display: grid;
  place-items: center;
  width: 3.5rem;
  height: 3.5rem;
  border: 2px solid rgba(74, 144, 226, 0.32);
  border-radius: 50%;
  background: rgba(74, 144, 226, 0.08);
}

.gw-trainings-beat-panel__counter-value {
  font-family: 'Playfair Display', serif;
  font-size: 1.15rem;
  font-weight: 500;
  color: #a5d2ff;
}

.gw-trainings-beat-panel__text {
  margin: 0;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.92rem;
  line-height: 1.8;
  color: rgba(220, 232, 248, 0.82);
}

.gw-trainings-beat-panel__list {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.65rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.gw-trainings-beat-panel__item {
  display: flex;
  align-items: flex-start;
  gap: 0.65rem;
  padding: 0.85rem 1rem;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.84rem;
  line-height: 1.55;
  color: rgba(244, 248, 255, 0.9);
  background: rgba(74, 144, 226, 0.08);
  border: 1.5px solid rgba(74, 144, 226, 0.22);
  border-radius: 12px;
  transition:
    border-color 0.25s ease,
    background 0.25s ease,
    transform 0.25s ease;
}

.gw-trainings-beat-panel__item:hover {
  background: rgba(74, 144, 226, 0.14);
  border-color: rgba(74, 144, 226, 0.38);
  transform: translateY(-2px);
}

.gw-trainings-beat-panel__item-index {
  flex-shrink: 0;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.58rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: rgba(165, 210, 255, 0.62);
}

.gw-trainings-beat-controls {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1rem;
  margin-top: 1rem;
}

.gw-trainings-beat-controls__btn {
  display: grid;
  place-items: center;
  width: 2.5rem;
  height: 2.5rem;
  color: #a5d2ff;
  background: rgba(255, 255, 255, 0.04);
  border: 2px solid rgba(74, 144, 226, 0.32);
  border-radius: 50%;
  cursor: pointer;
  transition:
    background 0.25s ease,
    border-color 0.25s ease,
    transform 0.25s ease,
    opacity 0.25s ease;
}

.gw-trainings-beat-controls__btn:hover:not(:disabled),
.gw-trainings-beat-controls__btn:focus-visible {
  background: rgba(74, 144, 226, 0.16);
  border-color: rgba(74, 144, 226, 0.55);
  transform: translateY(-2px);
  outline: none;
}

.gw-trainings-beat-controls__btn:disabled {
  opacity: 0.35;
  cursor: not-allowed;
}

.gw-trainings-beat-controls__label {
  margin: 0;
  min-width: 8rem;
  text-align: center;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.68rem;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: rgba(165, 210, 255, 0.72);
}

@media (max-width: 1024px) {
  .gw-trainings-beats__nav {
    display: flex;
    gap: 0.75rem;
    overflow-x: auto;
    padding-bottom: 0.5rem;
    scrollbar-width: none;
    -webkit-overflow-scrolling: touch;
  }

  .gw-trainings-beats__nav::-webkit-scrollbar {
    display: none;
  }

  .gw-trainings-beat {
    flex: 0 0 5.5rem;
  }

  .gw-trainings-beats__track-shell {
    display: none;
  }

  .gw-trainings-beat-panel__list {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 640px) {
  .gw-trainings-beat-panel__head {
    grid-template-columns: auto 1fr;
  }

  .gw-trainings-beat-panel__counter {
    display: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .gw-trainings-beat,
  .gw-trainings-beat__node,
  .gw-trainings-beat-panel__item,
  .gw-trainings-beat-controls__btn {
    transition: none;
  }

  .gw-trainings-beat:hover,
  .gw-trainings-beat:focus-visible,
  .gw-trainings-beat-panel__item:hover {
    transform: none;
  }
}

/* Home — premium blog thumbs & closing CTA */
.gw-blog-showcase__progress {
  height: 3px;
  background: rgba(74, 144, 226, 0.14);
}

.gw-blog-showcase__progress-bar {
