}

.gw-blog-showcase__thumb-index {
  display: grid;
  place-items: center;
  width: 2.25rem;
  height: 2.25rem;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: rgba(165, 210, 255, 0.72);
  background: rgba(74, 144, 226, 0.1);
  border: 1.5px solid rgba(74, 144, 226, 0.28);
