  flex-direction: column;
  gap: 0.25rem;
  min-width: 0;
  text-align: left;
}

.gw-blog-showcase__thumb-tag {
  color: rgba(165, 210, 255, 0.68);
}

.gw-blog-showcase__thumb.is-active .gw-blog-showcase__thumb-tag {
  color: #a5d2ff;
}

.gw-blog-showcase__thumb-title {
  font-size: clamp(0.92rem, 1.5vw, 1.02rem);
  color: rgba(244, 248, 255, 0.88);
}

.gw-blog-showcase__thumb.is-active .gw-blog-showcase__thumb-title {
  color: #fff;
}

.gw-blog-showcase__thumb-arrow {
  flex-shrink: 0;
  color: rgba(165, 210, 255, 0.45);
  transition:
    color 0.28s ease,
    transform 0.28s cubic-bezier(0.22, 1, 0.36, 1);
}

.gw-blog-showcase__thumb.is-active .gw-blog-showcase__thumb-arrow,
.gw-blog-showcase__thumb:hover .gw-blog-showcase__thumb-arrow {
  color: #a5d2ff;
  transform: translate(2px, -2px);
}

.gw-blog-showcase__nav:hover {
  color: #fff;
