  transition: transform 0.52s cubic-bezier(0.22, 1, 0.36, 1);
}

.gw-closing__cta-fill::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(
    115deg,
    transparent 0%,
    rgba(255, 255, 255, 0.22) 48%,
    transparent 92%
  );
  transform: translateX(-120%);
  transition: transform 0.65s cubic-bezier(0.22, 1, 0.36, 1);
}

.gw-closing__cta-label,
.gw-closing__cta-icon {
  position: relative;
  z-index: 1;
}

.gw-closing__cta-icon {
  flex-shrink: 0;
  transition: transform 0.38s cubic-bezier(0.22, 1, 0.36, 1);
}

.gw-closing__cta--primary:hover,
.gw-closing__cta--primary:focus-visible {
  color: #fff;
  border-color: rgba(165, 210, 255, 0.72);
  transform: translateY(-2px);
  box-shadow:
    0 16px 40px rgba(74, 144, 226, 0.38),
    0 0 28px rgba(74, 144, 226, 0.18);
  outline: none;
}

.gw-closing__cta--primary:hover .gw-closing__cta-fill,
.gw-closing__cta--primary:focus-visible .gw-closing__cta-fill {
  transform: translateX(0);
}

.gw-closing__cta--primary:hover .gw-closing__cta-fill::after,
.gw-closing__cta--primary:focus-visible .gw-closing__cta-fill::after {
  transform: translateX(120%);
}

.gw-closing__cta--primary:hover .gw-closing__cta-icon,
.gw-closing__cta--primary:focus-visible .gw-closing__cta-icon {
  transform: translateX(4px);
}

.gw-closing__cta--secondary:hover,
.gw-closing__cta--secondary:focus-visible {
  color: #fff;
