}

.gw-pilots-closing__para {
  color: rgba(255, 255, 255, 0.82);
}

.gw-pilots-closing__stats {
  display: flex;
  flex-wrap: wrap;
  gap: 0.65rem;
  margin: 1.35rem 0 0;
  padding: 0;
  list-style: none;
}

.gw-pilots-closing__stats li {
  display: flex;
  flex-direction: column;
  min-width: 6.25rem;
  padding: 0.7rem 1rem;
  background: rgba(255, 255, 255, 0.04);
  border: 2px solid rgba(74, 144, 226, 0.28);
