}

.gw-pilots-closing__stat-value {
  font-family: 'Playfair Display', serif;
  font-size: 1.2rem;
  font-weight: 500;
  color: #a5d2ff;
}

.gw-pilots-closing__stat-label {
  margin-top: 0.2rem;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.58rem;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: rgba(165, 210, 255, 0.62);
}

.gw-pilots-closing__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  margin-top: 1.5rem;
}

.gw-pilots-closing__cta {
  position: relative;
  isolation: isolate;
  display: inline-flex;
  align-items: center;
  gap: 0.55rem;
  padding: 0.88rem 1.75rem;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  text-decoration: none;
  border-radius: 999px;
  overflow: hidden;
  transition:
    color 0.38s cubic-bezier(0.22, 1, 0.36, 1),
    border-color 0.38s ease,
    box-shadow 0.38s ease,
    transform 0.28s cubic-bezier(0.22, 1, 0.36, 1),
    background 0.38s ease;
}

.gw-pilots-closing__cta--primary {
  color: #d4e8ff;
  background: rgba(255, 255, 255, 0.04);
  border: 2px solid rgba(74, 144, 226, 0.55);
}

.gw-pilots-closing__cta--secondary {
  color: rgba(255, 255, 255, 0.88);
  background: transparent;
  border: 2px solid rgba(74, 144, 226, 0.32);
}

.gw-pilots-closing__cta-fill {
  position: absolute;
  inset: 0;
  z-index: -1;
  background: linear-gradient(135deg, #4a90e2 0%, #2c5f9e 52%, #1a3a66 100%);
  transform: translateX(-101%);
  transition: transform 0.52s cubic-bezier(0.22, 1, 0.36, 1);
}

.gw-pilots-closing__cta-fill::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(115deg, transparent 0%, rgba(255, 255, 255, 0.22) 48%, transparent 92%);
  transform: translateX(-120%);
  transition: transform 0.65s cubic-bezier(0.22, 1, 0.36, 1);
}

.gw-pilots-closing__cta-label,
.gw-pilots-closing__cta-icon {
  position: relative;
  z-index: 1;
}

.gw-pilots-closing__cta-icon {
  transition: transform 0.38s cubic-bezier(0.22, 1, 0.36, 1);
}

.gw-pilots-closing__cta--primary:hover,
.gw-pilots-closing__cta--primary:focus-visible {
  color: #fff;
  border-color: rgba(165, 210, 255, 0.72);
  transform: translateY(-2px);
  box-shadow: 0 16px 40px rgba(74, 144, 226, 0.38);
  outline: none;
}

.gw-pilots-closing__cta--primary:hover .gw-pilots-closing__cta-fill,
.gw-pilots-closing__cta--primary:focus-visible .gw-pilots-closing__cta-fill {
  transform: translateX(0);
}

.gw-pilots-closing__cta--primary:hover .gw-pilots-closing__cta-fill::after,
.gw-pilots-closing__cta--primary:focus-visible .gw-pilots-closing__cta-fill::after {
  transform: translateX(120%);
}

.gw-pilots-closing__cta--primary:hover .gw-pilots-closing__cta-icon,
.gw-pilots-closing__cta--primary:focus-visible .gw-pilots-closing__cta-icon {
  transform: translateX(4px);
}

.gw-pilots-closing__cta--secondary:hover,
.gw-pilots-closing__cta--secondary:focus-visible {
  color: #fff;
  background: rgba(74, 144, 226, 0.12);
  border-color: rgba(74, 144, 226, 0.55);
  transform: translateY(-2px);
  outline: none;
}

.gw-pilots-closing__panel {
  position: relative;
  overflow: hidden;
  padding: clamp(1rem, 2vw, 1.25rem);
  background: rgba(255, 255, 255, 0.04);
  border: 2px solid rgba(74, 144, 226, 0.32);
  border-radius: 18px;
  box-shadow: 0 22px 56px rgba(0, 0, 0, 0.28);
}

.gw-pilots-closing__panel-accent {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 4px;
  background: linear-gradient(90deg, #2c5f9e 0%, #4a90e2 50%, #a5d2ff 100%);
}

.gw-pilots-closing__media {
  border-radius: 12px;
  overflow: hidden;
  box-shadow: 0 16px 40px rgba(0, 0, 0, 0.22);
}

.gw-pilots-closing__panel-caption {
  margin: 0.85rem 0 0;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  text-align: center;
  color: rgba(165, 210, 255, 0.72);
}

@media (max-width: 1024px) {
  .gw-pilots-why-grid {
    grid-template-columns: 1fr;
  }

  .gw-pilots-why-card,
  .gw-pilots-why-card--featured {
    grid-column: span 1;
  }
}

@media (max-width: 900px) {
  .gw-pilots-intro {
    grid-template-columns: 1fr;
  }

  .gw-pilots-intro__media {
    order: -1;
  }
}

/* Global Wings — entry preloader */
.gw-page__content--hidden {
  visibility: hidden;
  pointer-events: none;
}

.gw-preloader {
  position: fixed;
  inset: 0;
  z-index: 10050;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  background: #02040a;
  transition:
    opacity 0.52s cubic-bezier(0.22, 1, 0.36, 1),
    transform 0.52s cubic-bezier(0.22, 1, 0.36, 1);
}

.gw-preloader--exit {
  opacity: 0;
  transform: scale(1.02);
  pointer-events: none;
}

.gw-preloader__bg {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(120% 80% at 50% 110%, rgba(44, 95, 158, 0.28) 0%, transparent 55%),
    linear-gradient(165deg, rgba(2, 4, 10, 0.99) 0%, rgba(8, 16, 34, 0.97) 42%, rgba(2, 4, 10, 0.99) 100%);
}

.gw-preloader__aurora {
  position: absolute;
  width: 140%;
  height: 55%;
  left: -20%;
  filter: blur(48px);
  opacity: 0.55;
  pointer-events: none;
  mix-blend-mode: screen;
}

.gw-preloader__aurora--one {
  top: -8%;
  background: linear-gradient(
    105deg,
    transparent 0%,
    rgba(74, 144, 226, 0.22) 35%,
    rgba(165, 210, 255, 0.18) 55%,
    transparent 100%
  );
  animation: gw-preloader-aurora-a 3s ease-in-out infinite alternate;
}

.gw-preloader__aurora--two {
  bottom: 8%;
  background: linear-gradient(
    -75deg,
    transparent 0%,
    rgba(44, 95, 158, 0.2) 40%,
    rgba(74, 144, 226, 0.14) 62%,
    transparent 100%
  );
  animation: gw-preloader-aurora-b 3.6s ease-in-out infinite alternate;
}

@keyframes gw-preloader-aurora-a {
  from { transform: translateX(-3%) skewX(-6deg); opacity: 0.42; }
  to { transform: translateX(4%) skewX(-2deg); opacity: 0.72; }
}

@keyframes gw-preloader-aurora-b {
  from { transform: translateX(2%) skewX(4deg); opacity: 0.38; }
  to { transform: translateX(-5%) skewX(8deg); opacity: 0.66; }
}

.gw-preloader__stars {
  position: absolute;
  inset: 0;
  opacity: 0.75;
  background-image:
    radial-gradient(1px 1px at 12% 18%, rgba(255, 255, 255, 0.85) 50%, transparent 52%),
    radial-gradient(1px 1px at 28% 42%, rgba(255, 255, 255, 0.55) 50%, transparent 52%),
    radial-gradient(1.5px 1.5px at 44% 12%, rgba(165, 210, 255, 0.75) 50%, transparent 52%),
    radial-gradient(1px 1px at 58% 34%, rgba(255, 255, 255, 0.65) 50%, transparent 52%),
    radial-gradient(1px 1px at 72% 22%, rgba(255, 255, 255, 0.5) 50%, transparent 52%),
    radial-gradient(1.5px 1.5px at 86% 48%, rgba(165, 210, 255, 0.7) 50%, transparent 52%),
    radial-gradient(1px 1px at 18% 68%, rgba(255, 255, 255, 0.45) 50%, transparent 52%),
    radial-gradient(1px 1px at 36% 78%, rgba(255, 255, 255, 0.6) 50%, transparent 52%),
    radial-gradient(1px 1px at 64% 72%, rgba(255, 255, 255, 0.5) 50%, transparent 52%),
    radial-gradient(1px 1px at 82% 66%, rgba(255, 255, 255, 0.55) 50%, transparent 52%);
  animation: gw-preloader-stars 6s linear infinite;
}

@keyframes gw-preloader-stars {
  from { transform: translateY(0); }
  to { transform: translateY(-12px); }
}

.gw-preloader__grid {
  position: absolute;
  inset: auto 0 0;
  height: 42%;
  opacity: 0.22;
  background:
    linear-gradient(rgba(74, 144, 226, 0.18) 1px, transparent 1px),
    linear-gradient(90deg, rgba(74, 144, 226, 0.14) 1px, transparent 1px);
  background-size: 48px 48px;
  transform: perspective(420px) rotateX(68deg);
  transform-origin: center top;
  mask-image: linear-gradient(to top, rgba(0, 0, 0, 0.85) 0%, transparent 100%);
}

.gw-preloader__horizon {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 34%;
  height: 2px;
  background: linear-gradient(
    90deg,
    transparent 0%,
    rgba(74, 144, 226, 0.15) 15%,
    rgba(165, 210, 255, 0.85) 50%,
    rgba(74, 144, 226, 0.15) 85%,
    transparent 100%
  );
  box-shadow: 0 0 28px rgba(74, 144, 226, 0.45);
  animation: gw-preloader-horizon 2.2s ease-in-out infinite;
}

@keyframes gw-preloader-horizon {
  0%, 100% { opacity: 0.55; transform: scaleX(0.92); }
  50% { opacity: 1; transform: scaleX(1); }
}

.gw-preloader__radar {
  position: absolute;
  top: 50%;
  left: 50%;
  width: min(72vw, 34rem);
  height: min(72vw, 34rem);
  transform: translate(-50%, -50%);
  border-radius: 50%;
  border: 1px solid rgba(74, 144, 226, 0.12);
  opacity: 0.35;
  pointer-events: none;
}

.gw-preloader__radar::before {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: conic-gradient(
    from 0deg,
    transparent 0deg,
    rgba(74, 144, 226, 0.28) 28deg,
    transparent 56deg
  );
  animation: gw-preloader-radar 2.8s linear infinite;
}

@keyframes gw-preloader-radar {
  to { transform: rotate(360deg); }
}

.gw-preloader__glow {
  position: absolute;
  border-radius: 50%;
  filter: blur(90px);
  pointer-events: none;
}

.gw-preloader__glow--one {
  width: min(52vw, 520px);
  height: min(52vw, 520px);
  top: -12%;
  left: 8%;
  background: radial-gradient(circle, rgba(74, 144, 226, 0.28) 0%, transparent 68%);
  animation: gw-preloader-glow-a 3s ease-in-out infinite alternate;
}

.gw-preloader__glow--two {
  width: min(44vw, 440px);
  height: min(44vw, 440px);
  bottom: -10%;
  right: 6%;
  background: radial-gradient(circle, rgba(44, 95, 158, 0.24) 0%, transparent 70%);
  animation: gw-preloader-glow-b 3.2s ease-in-out infinite alternate;
}

@keyframes gw-preloader-glow-a {
  from { transform: translate(0, 0) scale(1); opacity: 0.75; }
  to { transform: translate(3%, 2%) scale(1.06); opacity: 1; }
}

@keyframes gw-preloader-glow-b {
  from { transform: translate(0, 0) scale(1); opacity: 0.7; }
  to { transform: translate(-2%, -3%) scale(1.05); opacity: 0.95; }
}

.gw-preloader__flight-scene {
  position: relative;
  z-index: 1;
  width: min(24rem, 86vw);
  height: 5rem;
  margin-bottom: 1.35rem;
}

.gw-preloader__path {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}

.gw-preloader__path-track {
  fill: none;
  stroke: rgba(74, 144, 226, 0.16);
  stroke-width: 2;
  stroke-linecap: round;
}

.gw-preloader__path-active {
  fill: none;
  stroke: rgba(165, 210, 255, 0.85);
  stroke-width: 2.5;
  stroke-linecap: round;
  stroke-dasharray: 100;
  filter: drop-shadow(0 0 8px rgba(74, 144, 226, 0.55));
  transition: stroke-dashoffset 0.08s linear;
}

.gw-preloader__plane-wrap {
  position: absolute;
  top: 38%;
  display: grid;
  place-items: center;
  width: 3.35rem;
  height: 3.35rem;
  color: #d4e8ff;
  background: linear-gradient(145deg, rgba(74, 144, 226, 0.28) 0%, rgba(44, 95, 158, 0.14) 100%);
  border: 1px solid rgba(165, 210, 255, 0.45);
  border-radius: 999px;
  box-shadow:
    0 0 36px rgba(74, 144, 226, 0.42),
    inset 0 1px 0 rgba(255, 255, 255, 0.14);
  transform: translate(-50%, -50%);
  transition: left 0.08s linear;
}

.gw-preloader__plane-trail {
  position: absolute;
  right: calc(100% + 4px);
  top: 50%;
  width: 2.75rem;
  height: 2px;
  transform: translateY(-50%);
  background: linear-gradient(90deg, transparent, rgba(165, 210, 255, 0.85));
  opacity: 0.85;
}

.gw-preloader__plane {
  width: 1.45rem;
  height: 1.45rem;
  transform: rotate(-28deg);
  filter: drop-shadow(0 0 10px rgba(165, 210, 255, 0.45));
}

.gw-preloader__content {
  position: relative;
  z-index: 2;
  text-align: center;
  padding-inline: 1.25rem;
  animation: gw-preloader-content-in 0.85s cubic-bezier(0.22, 1, 0.36, 1) both;
}

@keyframes gw-preloader-content-in {
  from {
    opacity: 0;
    transform: translateY(18px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.gw-preloader__logo-wrap {
  display: flex;
  justify-content: center;
  margin-bottom: 1rem;
}

.gw-preloader__logo {
  display: block;
  width: auto;
  max-width: min(52vw, 11.5rem);
  height: auto;
  filter: drop-shadow(0 8px 28px rgba(74, 144, 226, 0.35));
  animation: gw-preloader-logo-pulse 2.4s ease-in-out infinite;
}

@keyframes gw-preloader-logo-pulse {
  0%, 100% { transform: scale(1); filter: drop-shadow(0 8px 28px rgba(74, 144, 226, 0.35)); }
  50% { transform: scale(1.03); filter: drop-shadow(0 10px 36px rgba(74, 144, 226, 0.5)); }
}

.gw-preloader__eyebrow {
  margin: 0 0 0.55rem;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: rgba(165, 210, 255, 0.72);
}

.gw-preloader__brand {
  margin: 0;
  font-family: 'Playfair Display', Georgia, serif;
  font-size: clamp(2rem, 6vw, 2.85rem);
  font-weight: 500;
  line-height: 1.05;
  letter-spacing: 0.02em;
}

.gw-preloader__brand-lead {
  color: #f4f8ff;
}

.gw-preloader__brand-em {
  margin-left: 0.35rem;
  background: linear-gradient(135deg, #a5d2ff 0%, #4a90e2 55%, #d4e8ff 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

.gw-preloader__status {
  margin: 0.95rem 0 0;
  min-height: 1.2rem;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.78rem;
  font-weight: 500;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: rgba(165, 210, 255, 0.78);
  opacity: 0;
  transform: translateY(6px);
  transition:
    opacity 0.28s ease,
    transform 0.28s ease;
}

.gw-preloader__status--visible {
  opacity: 1;
  transform: translateY(0);
}

.gw-preloader__footer {
  position: relative;
  z-index: 2;
  width: min(22rem, 88vw);
  margin-top: 2rem;
}

.gw-preloader__metrics {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 0.75rem;
}

.gw-preloader__metric {
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
}

.gw-preloader__metric-label {
  font-family: 'Montserrat', sans-serif;
  font-size: 0.58rem;
  font-weight: 600;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: rgba(165, 210, 255, 0.55);
}

.gw-preloader__metric-value {
  font-family: 'Montserrat', sans-serif;
  font-size: 0.82rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  color: rgba(220, 232, 248, 0.92);
  font-variant-numeric: tabular-nums;
}

.gw-preloader__bar-wrap {
  position: relative;
}

.gw-preloader__bar {
  position: relative;
  height: 5px;
  overflow: hidden;
  background: rgba(255, 255, 255, 0.08);
  border-radius: 999px;
  box-shadow: inset 0 0 0 1px rgba(74, 144, 226, 0.12);
}

.gw-preloader__bar-fill {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #2c5f9e 0%, #4a90e2 45%, #a5d2ff 100%);
  box-shadow: 0 0 18px rgba(74, 144, 226, 0.55);
  transition: width 0.08s linear;
}

.gw-preloader__bar-shimmer {
  position: absolute;
  inset: 0 auto 0 0;
  width: 35%;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.45), transparent);
  animation: gw-preloader-shimmer 1.6s ease-in-out infinite;
  pointer-events: none;
}

@keyframes gw-preloader-shimmer {
  from { transform: translateX(-120%); }
  to { transform: translateX(320%); }
}

@media (prefers-reduced-motion: reduce) {
  .gw-preloader__aurora--one,
  .gw-preloader__aurora--two,
  .gw-preloader__stars,
  .gw-preloader__horizon,
  .gw-preloader__radar::before,
  .gw-preloader__glow--one,
  .gw-preloader__glow--two,
  .gw-preloader__logo,
  .gw-preloader__bar-shimmer,
  .gw-preloader__content {
    animation: none;
  }
}

/* Global Wings — premium section headers */
.gw-section-header {
  position: relative;
  z-index: 1;
  max-width: 44rem;
  margin: 0 auto clamp(2rem, 5vw, 3rem);
  padding: clamp(1.35rem, 3vw, 2rem) clamp(1.25rem, 3vw, 2.25rem);
