  opacity: 0.85;
}

.gw-section-header__eyebrow {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  margin-bottom: 0.85rem;
  padding: 0.38rem 0.85rem 0.38rem 0.55rem;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--gw-accent-deep);
  background: rgba(74, 144, 226, 0.08);
  border: 1.5px solid rgba(74, 144, 226, 0.24);
