  inset: 0;
  z-index: -1;
  background:
    radial-gradient(ellipse 90% 70% at 20% 90%, rgba(5, 7, 12, 0.92) 0%, transparent 60%),
    linear-gradient(180deg, rgba(5, 7, 12, 0.55) 0%, rgba(5, 7, 12, 0.35) 40%, rgba(5, 7, 12, 0.9) 100%);
