  pointer-events: none;
}

.casino-hero__glow--1 {
  width: min(560px, 80vw);
  height: min(360px, 45vh);
  top: 8%;
  left: -8%;
  background: radial-gradient(circle, rgba(63, 127, 255, 0.28) 0%, transparent 68%);
}

.casino-hero__glow--2 {
  width: min(520px, 75vw);
  height: min(340px, 42vh);
  bottom: 4%;
  right: -6%;
  background: radial-gradient(circle, rgba(26, 74, 170, 0.4) 0%, transparent 70%);
}

.casino-hero__fade {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 120px;
  z-index: -1;
  background: linear-gradient(180deg, transparent, #05070c);
}

.casino-hero__inner {
  position: relative;
  max-width: 900px;
}

.casino-hero__eyebrow {
  font-family: 'Montserrat', sans-serif;
