}

.casino-hero__title-line--accent {
  width: fit-content;
  max-width: 100%;
  color: transparent;
  background: linear-gradient(
    115deg,
    #ffffff 0%,
    #dce9ff 28%,
    #8eb6ff 48%,
    #3f7fff 62%,
    #dce9ff 78%,
    #ffffff 100%
  );
  background-size: 220% 100%;
  -webkit-background-clip: text;
  background-clip: text;
  filter: drop-shadow(0 8px 28px rgba(40, 90, 200, 0.35));
  animation:
    casinoTitleRise 1.05s cubic-bezier(0.22, 1, 0.36, 1) 0.12s both,
    casinoTitleSheen 7s ease-in-out 1.1s infinite;
}

.casino-hero__subtitle {
  margin: 0 0 0.85rem;
