  font-weight: 500;
  font-size: clamp(1.08rem, 2.7vw, 1.65rem);
  letter-spacing: 0.03em;
  line-height: 1.35;
  color: rgba(236, 242, 255, 0.94);
  text-shadow: 0 4px 24px rgba(0, 0, 0, 0.45);
