}

.casino-hero__tagline {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.85rem;
  margin: 0 0 2.15rem;
}

.casino-hero__tagline-text {
  font-family: 'Montserrat', sans-serif;
  font-size: clamp(0.78rem, 1.9vw, 0.92rem);
  font-weight: 600;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: #8eb6ff;
  text-shadow: 0 0 24px rgba(63, 127, 255, 0.35);
  animation:
    casinoTaglineIn 0.85s cubic-bezier(0.22, 1, 0.36, 1) 0.42s both,
    casinoTaglineGlow 4.5s ease-in-out 1.4s infinite;
}

.casino-hero__tagline-rule {
  display: block;
  height: 1px;
  width: clamp(2.2rem, 8vw, 4.5rem);
  background: linear-gradient(
    90deg,
    transparent 0%,
    rgba(111, 176, 255, 0.15) 18%,
    rgba(143, 182, 255, 0.95) 50%,
    rgba(111, 176, 255, 0.15) 82%,
    transparent 100%
  );
  box-shadow: 0 0 12px rgba(63, 127, 255, 0.45);
  transform-origin: center;
  animation: casinoRuleDraw 0.9s cubic-bezier(0.22, 1, 0.36, 1) 0.55s both;
}

.casino-hero__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.9rem;
}

@keyframes casinoTitleRise {
  from {
    opacity: 0;
    transform: translate3d(0, 28px, 0);
    filter: blur(6px);
  }
  to {
    opacity: 1;
    transform: translate3d(0, 0, 0);
    filter: blur(0);
  }
}

@keyframes casinoTitleSheen {
  0%,
  100% {
    background-position: 0% 50%;
  }
  50% {
    background-position: 100% 50%;
  }
}

@keyframes casinoSubtitleIn {
  from {
    opacity: 0;
    transform: translate3d(0, 18px, 0);
    letter-spacing: 0.08em;
  }
  to {
    opacity: 1;
    transform: translate3d(0, 0, 0);
    letter-spacing: 0.03em;
  }
}

@keyframes casinoTaglineIn {
  from {
    opacity: 0;
    transform: translate3d(0, 12px, 0);
    letter-spacing: 0.36em;
  }
  to {
    opacity: 1;
    transform: translate3d(0, 0, 0);
    letter-spacing: 0.22em;
  }
}

@keyframes casinoTaglineGlow {
  0%,
  100% {
    color: #8eb6ff;
    text-shadow: 0 0 18px rgba(63, 127, 255, 0.28);
  }
  50% {
    color: #c5d9ff;
    text-shadow: 0 0 28px rgba(111, 176, 255, 0.55);
  }
}

@keyframes casinoRuleDraw {
  from {
    opacity: 0;
    transform: scaleX(0.2);
  }
  to {
    opacity: 1;
    transform: scaleX(1);
  }
}

@media (prefers-reduced-motion: reduce) {
  .casino-hero__title-line,
  .casino-hero__title-line--accent,
  .casino-hero__subtitle-text,
  .casino-hero__tagline-text,
  .casino-hero__tagline-rule {
    animation: none;
  }

  .casino-hero__title-line--accent {
    color: #9ec0ff;
    background: none;
    -webkit-background-clip: unset;
    background-clip: unset;
  }
}

/* ── Buttons ── */
.casino-btn {
  position: relative;
  overflow: hidden;
  isolation: isolate;
  display: inline-flex;
  align-items: center;
  gap: 0.55rem;
  padding: 0.98rem 1.9rem;
  border-radius: 3px;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  text-decoration: none;
  cursor: pointer;
  transition: transform 0.3s cubic-bezier(0.2, 0.7, 0.3, 1), box-shadow 0.3s ease,
    background 0.3s ease, color 0.3s ease, border-color 0.3s ease, background-position 0.5s ease;
}

/* moving light sweep */
.casino-btn::after {
  content: '';
  position: absolute;
  top: 0;
  left: -130%;
  width: 55%;
  height: 100%;
  background: linear-gradient(
    100deg,
    transparent 0%,
    rgba(255, 255, 255, 0.38) 50%,
    transparent 100%
  );
  transform: skewX(-20deg);
  transition: left 0.6s ease;
  pointer-events: none;
  z-index: 2;
}

.casino-btn:hover::after {
  left: 135%;
}

.casino-btn svg {
  position: relative;
  z-index: 2;
  transition: transform 0.3s ease;
}

.casino-btn:hover svg {
  transform: translateX(4px);
}

.casino-btn:active {
  transform: translateY(-1px) scale(0.98);
}

.casino-btn:focus-visible {
  outline: 2px solid #7ea8ff;
  outline-offset: 3px;
}

.casino-btn--gold {
  border: none;
  color: #ffffff;
  background: linear-gradient(120deg, #7ea8ff 0%, #3f7fff 45%, #1c47b8 100%);
  background-size: 200% 100%;
  background-position: 0% 0%;
  box-shadow: 0 10px 30px rgba(63, 127, 255, 0.32), inset 0 0 0 1px rgba(126, 168, 255, 0.25);
}

.casino-btn--gold:hover {
  transform: translateY(-3px);
  background-position: 100% 0%;
  box-shadow: 0 18px 48px rgba(63, 127, 255, 0.5), 0 0 24px rgba(63, 127, 255, 0.35);
}

.casino-btn--ghost {
  border: 1px solid rgba(63, 127, 255, 0.55);
  color: rgba(233, 240, 255, 0.95);
  background: rgba(63, 127, 255, 0.04);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
}

/* fill-in on hover */
.casino-btn--ghost::before {
  content: '';
  position: absolute;
  inset: 0;
  z-index: -1;
  background: linear-gradient(120deg, #3f7fff, #1c47b8);
  transform: scaleX(0);
  transform-origin: left center;
  transition: transform 0.4s cubic-bezier(0.2, 0.7, 0.3, 1);
}

.casino-btn--ghost:hover {
  transform: translateY(-3px);
  border-color: #7ea8ff;
  color: #fff;
  box-shadow: 0 16px 40px rgba(63, 127, 255, 0.42);
}

.casino-btn--ghost:hover::before {
  transform: scaleX(1);
}

@media (prefers-reduced-motion: reduce) {
  .casino-btn,
  .casino-btn svg,
  .casino-btn::after,
  .casino-btn--ghost::before {
    transition: none;
  }

  .casino-btn:hover {
    transform: none;
  }

  .casino-btn:hover::after {
    left: -130%;
  }

  .casino-btn:hover svg {
    transform: none;
  }

  .casino-btn--ghost:hover::before {
    transform: scaleX(0);
  }

  .casino-btn--ghost:hover {
    background: rgba(63, 127, 255, 0.16);
  }
}

