/* ── Split sections (grand / beyond) ── */
.casino-grand__inner,
.casino-beyond__inner {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: clamp(1.75rem, 4vw, 3.5rem);
  align-items: center;
}

.casino-grand__media,
.casino-beyond__media {
  position: relative;
  border-radius: 16px;
  overflow: hidden;
  border: 1px solid rgba(120, 170, 255, 0.28);
  box-shadow:
    0 34px 80px -28px rgba(0, 0, 0, 0.7),
    0 0 0 1px rgba(63, 127, 255, 0.12),
    inset 0 1px 0 rgba(255, 255, 255, 0.06);
  aspect-ratio: 4 / 3;
  transition: transform 0.55s cubic-bezier(0.22, 1, 0.36, 1), box-shadow 0.55s ease,
    border-color 0.55s ease;
}

.casino-grand__media:hover,
.casino-beyond__media:hover {
  transform: translateY(-6px);
  border-color: rgba(143, 186, 255, 0.5);
  box-shadow:
    0 44px 96px -28px rgba(0, 0, 0, 0.75),
    0 0 44px -10px rgba(63, 127, 255, 0.5),
    inset 0 1px 0 rgba(255, 255, 255, 0.1);
}

/* Gradient scrim for depth */
.casino-grand__media::after,
.casino-beyond__media::after {
  content: '';
  position: absolute;
  inset: 0;
  z-index: 1;
  background: linear-gradient(180deg, rgba(5, 10, 22, 0) 55%, rgba(5, 10, 22, 0.45) 100%);
  pointer-events: none;
}

/* Light sweep on hover */
.casino-grand__media::before,
.casino-beyond__media::before {
  content: '';
  position: absolute;
  inset: 0;
  z-index: 2;
  background: linear-gradient(
    115deg,
    transparent 42%,
    rgba(190, 214, 255, 0.25) 50%,
    transparent 58%
  );
  transform: translateX(-120%);
  transition: transform 0.85s ease;
  pointer-events: none;
}

.casino-grand__media:hover::before,
.casino-beyond__media:hover::before {
  transform: translateX(120%);
}

.casino-grand__media img,
.casino-beyond__media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  transition: transform 0.7s cubic-bezier(0.22, 1, 0.36, 1), filter 0.7s ease;
}

.casino-grand__media:hover img,
.casino-beyond__media:hover img {
  transform: scale(1.06);
  filter: brightness(1.06) saturate(1.05);
}

/* Cinematic fade-in + un-blur when the image scrolls into view */
.casino-grand__media.reveal img,
.casino-beyond__media.reveal img {
  opacity: 0;
  transform: scale(1.12);
  filter: blur(10px);
  transition: opacity 1s ease, transform 1.1s cubic-bezier(0.22, 1, 0.36, 1),
    filter 1.1s ease;
}

.casino-grand__media.revealed img,
.casino-beyond__media.revealed img {
  opacity: 1;
  transform: scale(1);
  filter: blur(0);
}

.casino-grand__media-badge {
  position: absolute;
  top: 1rem;
  left: 1rem;
  z-index: 3;
  padding: 0.5rem 0.9rem;
  font-family: 'Playfair Display', serif;
  font-weight: 700;
  font-size: 0.95rem;
  color: #ffffff;
  background: linear-gradient(135deg, rgba(126, 168, 255, 0.95), rgba(31, 78, 174, 0.95));
  border: 1px solid rgba(190, 214, 255, 0.4);
  border-radius: 8px;
  box-shadow: 0 10px 24px -8px rgba(0, 0, 0, 0.5), 0 0 18px -6px rgba(63, 127, 255, 0.6);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  animation: casinoBadgePulse 3s ease-in-out infinite;
}

@keyframes casinoBadgePulse {
  0%, 100% {
    box-shadow: 0 10px 24px -8px rgba(0, 0, 0, 0.5), 0 0 14px -6px rgba(63, 127, 255, 0.45);
  }
  50% {
    box-shadow: 0 10px 24px -8px rgba(0, 0, 0, 0.5), 0 0 26px -4px rgba(63, 127, 255, 0.8);
  }
}

.casino-games {
  list-style: none;
  margin: 0 0 1.5rem;
  padding: 0;
  display: flex;
  flex-wrap: wrap;
  gap: 0.6rem;
}

.casino-games__item {
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  padding: 0.55rem 1rem;
  border: 1px solid rgba(63, 127, 255, 0.32);
  border-radius: 999px;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.78rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  color: rgba(246, 240, 228, 0.92);
  background: rgba(63, 127, 255, 0.06);
  transition: transform 0.3s cubic-bezier(0.22, 1, 0.36, 1), background 0.3s ease,
    border-color 0.3s ease, box-shadow 0.3s ease;
}

.casino-games__item:hover {
  transform: translateY(-2px);
  background: rgba(63, 127, 255, 0.16);
  border-color: rgba(143, 186, 255, 0.6);
  box-shadow: 0 8px 20px -10px rgba(63, 127, 255, 0.7);
}

.casino-games__item svg {
  color: var(--casino-gold);
}

.casino-feature-cards {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1rem;
  margin-top: 1.75rem;
}

.casino-feature-card {
  position: relative;
  padding: 1.5rem 1.4rem;
  border: 1px solid rgba(63, 127, 255, 0.2);
  border-radius: 14px;
  overflow: hidden;
  background: linear-gradient(165deg, rgba(63, 127, 255, 0.1), rgba(5, 7, 12, 0.25));
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.05);
  transition: transform 0.4s cubic-bezier(0.22, 1, 0.36, 1), border-color 0.4s ease,
    box-shadow 0.4s ease, background 0.4s ease;
}

/* Animated top accent */
.casino-feature-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 2px;
  background: linear-gradient(90deg, transparent, #5a8fe6, #cfe2ff, #5a8fe6, transparent);
  transform: scaleX(0);
  transform-origin: left center;
  transition: transform 0.45s cubic-bezier(0.22, 1, 0.36, 1);
}

.casino-feature-card:hover {
  transform: translateY(-5px);
  border-color: rgba(143, 186, 255, 0.5);
  background: linear-gradient(165deg, rgba(63, 127, 255, 0.16), rgba(5, 7, 12, 0.28));
  box-shadow: 0 22px 46px -22px rgba(0, 0, 0, 0.7), 0 0 26px -8px rgba(63, 127, 255, 0.45);
}

.casino-feature-card:hover::before {
  transform: scaleX(1);
}

.casino-feature-card svg {
  display: block;
  box-sizing: content-box;
  width: 20px;
  height: 20px;
  padding: 11px;
  color: #cfe2ff;
  border-radius: 50%;
  background: radial-gradient(circle at 30% 25%, rgba(90, 143, 230, 0.4), rgba(20, 44, 88, 0.55));
  border: 1px solid rgba(130, 176, 255, 0.4);
  margin-bottom: 0.9rem;
  transition: transform 0.4s cubic-bezier(0.22, 1, 0.36, 1), box-shadow 0.4s ease;
}

.casino-feature-card:hover svg {
  transform: scale(1.1) rotate(-6deg);
  box-shadow: 0 0 20px -2px rgba(63, 127, 255, 0.6);
}

.casino-feature-card h3 {
  font-family: 'Outfit', sans-serif;
  font-size: 0.98rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  color: #fff;
  margin: 0 0 0.5rem;
}

.casino-feature-card p {
  font-family: 'Montserrat', sans-serif;
  font-size: 0.82rem;
  line-height: 1.65;
  color: rgba(214, 210, 200, 0.7);
  margin: 0;
}

.casino-beyond__inner {
  grid-template-columns: 1fr 1fr;
}

.casino-beyond {
  background:
    radial-gradient(ellipse 70% 60% at 85% 20%, rgba(26, 74, 170, 0.16) 0%, transparent 60%);
}

/* ── Highlights ── */
.casino-highlights {
  border-top: 1px solid rgba(63, 127, 255, 0.12);
  border-bottom: 1px solid rgba(63, 127, 255, 0.12);
  background: linear-gradient(180deg, rgba(63, 127, 255, 0.04), transparent);
}

.casino-highlights__grid {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: clamp(1rem, 1.6vw, 1.4rem);
}

.casino-highlight {
  position: relative;
  display: flex;
  align-items: center;
  gap: clamp(1rem, 1.4vw, 1.35rem);
  padding: clamp(1.4rem, 2vw, 1.9rem) clamp(1.5rem, 2vw, 2rem);
  border: 1px solid rgba(63, 127, 255, 0.18);
  border-radius: 16px;
  background: linear-gradient(135deg, rgba(63, 127, 255, 0.05), rgba(255, 255, 255, 0.012));
  overflow: hidden;
  opacity: 0;
  transform: translateY(22px) scale(0.98);
  transition: opacity 0.6s ease, transform 0.6s cubic-bezier(0.22, 1, 0.36, 1),
    border-color 0.3s ease, background 0.3s ease, box-shadow 0.35s ease;
}

/* Sheen that sweeps across on hover */
.casino-highlight::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(
    115deg,
    transparent 0%,
    rgba(120, 170, 255, 0.14) 45%,
    rgba(180, 210, 255, 0.28) 50%,
    rgba(120, 170, 255, 0.14) 55%,
    transparent 100%
  );
  transform: translateX(-120%);
  transition: transform 0.7s ease;
  pointer-events: none;
}

/* Staggered reveal once the grid scrolls into view */
.casino-highlights__grid.revealed .casino-highlight {
  opacity: 1;
  transform: none;
}

.casino-highlights__grid.revealed .casino-highlight:nth-child(1) { transition-delay: 0.04s; }
.casino-highlights__grid.revealed .casino-highlight:nth-child(2) { transition-delay: 0.1s; }
.casino-highlights__grid.revealed .casino-highlight:nth-child(3) { transition-delay: 0.16s; }
.casino-highlights__grid.revealed .casino-highlight:nth-child(4) { transition-delay: 0.22s; }
.casino-highlights__grid.revealed .casino-highlight:nth-child(5) { transition-delay: 0.28s; }
.casino-highlights__grid.revealed .casino-highlight:nth-child(6) { transition-delay: 0.34s; }
.casino-highlights__grid.revealed .casino-highlight:nth-child(7) { transition-delay: 0.4s; }
.casino-highlights__grid.revealed .casino-highlight:nth-child(8) { transition-delay: 0.46s; }
.casino-highlights__grid.revealed .casino-highlight:nth-child(9) { transition-delay: 0.52s; }

.casino-highlight:hover {
  border-color: rgba(63, 127, 255, 0.55);
  transform: translateY(-6px) scale(1.015);
  background: linear-gradient(135deg, rgba(63, 127, 255, 0.1), rgba(255, 255, 255, 0.02));
  box-shadow: 0 18px 40px -18px rgba(26, 74, 170, 0.65), 0 0 0 1px rgba(63, 127, 255, 0.12);
}

.casino-highlight:hover::before {
  transform: translateX(120%);
}

.casino-highlight__icon {
  flex: none;
  width: clamp(48px, 4vw, 58px);
  height: clamp(48px, 4vw, 58px);
  display: grid;
  place-items: center;
  border-radius: 50%;
  color: var(--casino-gold);
  background: radial-gradient(circle, rgba(63, 127, 255, 0.22), rgba(63, 127, 255, 0.05));
  border: 1px solid rgba(63, 127, 255, 0.35);
  box-shadow: 0 0 0 0 rgba(63, 127, 255, 0.35);
  animation: casinoHighlightPulse 3.2s ease-in-out infinite;
  transition: transform 0.35s cubic-bezier(0.22, 1, 0.36, 1), box-shadow 0.35s ease,
    border-color 0.35s ease;
}

.casino-highlight:hover .casino-highlight__icon {
  transform: scale(1.12) rotate(-6deg);
  border-color: rgba(120, 170, 255, 0.7);
  box-shadow: 0 0 22px -2px rgba(63, 127, 255, 0.6);
}

@keyframes casinoHighlightPulse {
  0%, 100% { box-shadow: 0 0 0 0 rgba(63, 127, 255, 0.28); }
  50% { box-shadow: 0 0 0 7px rgba(63, 127, 255, 0); }
}

.casino-highlight__text {
  font-family: 'Montserrat', sans-serif;
  font-size: clamp(0.95rem, 1.1vw, 1.08rem);
  font-weight: 600;
  line-height: 1.4;
  letter-spacing: 0.01em;
  color: rgba(242, 240, 234, 0.94);
}

/* ── Transport tiers ── */
.casino-tiers {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: clamp(1.25rem, 3vw, 2rem);
}

.casino-tier {
  position: relative;
  display: flex;
  flex-direction: column;
  border: 1px solid rgba(63, 127, 255, 0.2);
  border-radius: 18px;
  overflow: hidden;
  isolation: isolate;
  background:
    linear-gradient(180deg, rgba(63, 127, 255, 0.06) 0%, rgba(255, 255, 255, 0.02) 22%, rgba(5, 8, 16, 0.55) 100%);
  box-shadow:
    0 18px 44px -26px rgba(0, 0, 0, 0.7),
    inset 0 1px 0 rgba(255, 255, 255, 0.05);
  transition:
    border-color 0.45s ease,
    transform 0.55s cubic-bezier(0.22, 1, 0.36, 1),
    box-shadow 0.55s ease;
}

/* Animated top accent line */
.casino-tier::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  z-index: 3;
  background: linear-gradient(90deg, transparent, #5a8fe6, #cfe2ff, #5a8fe6, transparent);
  transform: scaleX(0);
  transform-origin: left center;
  transition: transform 0.55s cubic-bezier(0.22, 1, 0.36, 1);
}

.casino-tier:hover {
  border-color: rgba(120, 170, 255, 0.55);
  transform: translateY(-8px) scale(1.01);
  box-shadow:
    0 34px 70px -24px rgba(0, 0, 0, 0.7),
    0 0 40px -8px rgba(63, 127, 255, 0.45),
    inset 0 1px 0 rgba(255, 255, 255, 0.08);
}

.casino-tier:hover::before {
  transform: scaleX(1);
}

.casino-tier__media {
  position: relative;
  aspect-ratio: 16 / 9;
  overflow: hidden;
}

/* Gradient scrim + sheen for depth */
.casino-tier__media::after {
  content: '';
  position: absolute;
  inset: 0;
  z-index: 1;
  background: linear-gradient(180deg, rgba(5, 10, 22, 0) 45%, rgba(5, 10, 22, 0.55) 100%);
  pointer-events: none;
}

.casino-tier__media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  transition: transform 0.7s cubic-bezier(0.22, 1, 0.36, 1), filter 0.7s ease;
}

.casino-tier:hover .casino-tier__media img {
  transform: scale(1.08);
  filter: brightness(1.08) saturate(1.05);
}

/* Light sweep across the image on hover */
.casino-tier__media::before {
  content: '';
  position: absolute;
  inset: 0;
  z-index: 2;
  background: linear-gradient(
    115deg,
    transparent 40%,
    rgba(190, 214, 255, 0.28) 50%,
    transparent 60%
  );
  transform: translateX(-120%);
  transition: transform 0.8s ease;
  pointer-events: none;
}

.casino-tier:hover .casino-tier__media::before {
  transform: translateX(120%);
}

.casino-tier__eyebrow {
  position: absolute;
  top: 0.9rem;
  left: 0.9rem;
  z-index: 3;
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.42rem 0.85rem;
  border-radius: 999px;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.6rem;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: #ffffff;
  background: linear-gradient(135deg, rgba(90, 143, 230, 0.92), rgba(31, 78, 174, 0.92));
  border: 1px solid rgba(190, 214, 255, 0.4);
  box-shadow: 0 8px 20px -8px rgba(28, 71, 160, 0.7);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  transition: transform 0.45s cubic-bezier(0.22, 1, 0.36, 1), box-shadow 0.45s ease;
}

.casino-tier:hover .casino-tier__eyebrow {
  transform: translateY(-2px);
  box-shadow: 0 12px 26px -8px rgba(28, 71, 160, 0.85), 0 0 18px -4px rgba(63, 127, 255, 0.6);
}

.casino-tier__body {
  padding: clamp(1.35rem, 2.5vw, 1.85rem);
  display: flex;
  flex-direction: column;
  flex: 1;
}

.casino-tier__name {
  font-family: 'Playfair Display', serif;
  font-weight: 700;
  font-size: clamp(1.15rem, 2.4vw, 1.45rem);
  letter-spacing: 0.01em;
  color: #fff;
  margin: 0 0 0.7rem;
  transition: color 0.4s ease;
}

.casino-tier:hover .casino-tier__name {
  color: #dfeaff;
}

.casino-tier__blurb {
  font-family: 'Montserrat', sans-serif;
  font-size: 0.86rem;
  line-height: 1.7;
  color: rgba(214, 210, 200, 0.74);
  margin: 0 0 1.1rem;
}

.casino-tier__features {
  list-style: none;
  margin: 0 0 1.1rem;
  padding: 0;
  display: grid;
  gap: 0.55rem;
}

.casino-tier__features li {
  position: relative;
  padding-left: 1.5rem;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.82rem;
  line-height: 1.5;
  color: rgba(230, 226, 218, 0.85);
  transition: transform 0.4s cubic-bezier(0.22, 1, 0.36, 1), color 0.4s ease;
}

.casino-tier__features li::before {
  content: '';
  position: absolute;
  left: 0;
  top: 0.4em;
  width: 8px;
  height: 8px;
  background: linear-gradient(135deg, #cfe2ff, #4f83e0);
  transform: rotate(45deg);
  box-shadow: 0 0 8px rgba(63, 127, 255, 0.5);
  transition: box-shadow 0.4s ease, transform 0.4s ease;
}

.casino-tier:hover .casino-tier__features li {
  transform: translateX(4px);
  color: rgba(240, 244, 252, 0.95);
}

.casino-tier:hover .casino-tier__features li::before {
  box-shadow: 0 0 14px rgba(63, 127, 255, 0.85);
}

.casino-tier__note {
  margin: auto 0 0;
  padding-top: 1rem;
  border-top: 1px solid rgba(63, 127, 255, 0.14);
  font-family: 'Montserrat', sans-serif;
  font-size: 0.76rem;
  font-style: italic;
  line-height: 1.6;
  color: rgba(214, 210, 200, 0.6);
}

/* Staggered entrance for the tier cards */
.casino-tiers .casino-tier.reveal {
  transition:
    opacity 0.7s cubic-bezier(0.16, 1, 0.3, 1),
    transform 0.7s cubic-bezier(0.16, 1, 0.3, 1),
    border-color 0.45s ease,
    box-shadow 0.55s ease;
}

.casino-tiers .casino-tier:nth-child(1) { transition-delay: 0.05s; }
.casino-tiers .casino-tier:nth-child(2) { transition-delay: 0.14s; }
.casino-tiers .casino-tier:nth-child(3) { transition-delay: 0.23s; }
.casino-tiers .casino-tier:nth-child(4) { transition-delay: 0.32s; }

@media (prefers-reduced-motion: reduce) {
  .casino-tier,
  .casino-tier::before,
  .casino-tier__media img,
  .casino-tier__media::before,
  .casino-tier__eyebrow,
  .casino-tier__features li {
    transition: none;
  }

  .casino-tier:hover {
    transform: none;
  }
}

/* ── Gallery ── */
.casino-gallery__grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: clamp(0.6rem, 1.5vw, 1rem);
}

.casino-gallery__item {
  margin: 0;
  overflow: hidden;
  border-radius: 3px;
  border: 1px solid rgba(63, 127, 255, 0.16);
  aspect-ratio: 4 / 3;
}

.casino-gallery__item--wide {
  grid-column: span 2;
  aspect-ratio: 8 / 3;
}

.casino-gallery__item img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  transition: transform 0.5s ease;
}

.casino-gallery__item:hover img {
  transform: scale(1.05);
}

/* ── Closing CTA ── */
.casino-cta {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  padding: clamp(4rem, 10vw, 7rem) 0;
  text-align: center;
  border-top: 1px solid rgba(63, 127, 255, 0.16);
  background:
    radial-gradient(ellipse 70% 80% at 50% 0%, rgba(63, 127, 255, 0.12) 0%, transparent 60%),
    linear-gradient(180deg, #070a10 0%, #05070c 100%);
}

.casino-cta__glow {
  position: absolute;
  inset: 0;
  z-index: -1;
  background: radial-gradient(circle at 50% 120%, rgba(26, 74, 170, 0.28) 0%, transparent 55%);
  pointer-events: none;
}

.casino-cta__inner {
  max-width: 780px;
}

.casino-cta__title {
  font-family: 'Playfair Display', serif;
  font-weight: 700;
  font-style: italic;
  font-size: clamp(1.9rem, 5vw, 3rem);
  color: #fff;
  margin: 0 0 1.35rem;
  letter-spacing: 0.02em;
}

.casino-cta__text {
  font-family: 'Montserrat', sans-serif;
  font-size: clamp(0.9rem, 2vw, 1rem);
  line-height: 1.8;
  color: rgba(214, 210, 200, 0.74);
  margin: 0 auto 1.5rem;
}

.casino-cta__signature {
  font-family: 'Playfair Display', serif;
  font-style: italic;
  font-size: clamp(1.05rem, 2.6vw, 1.4rem);
  color: var(--casino-gold);
  margin: 0 0 2.25rem;
}

.casino-cta__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.9rem;
  justify-content: center;
}

@media (max-width: 900px) {
  .casino-grand__inner,
  .casino-beyond__inner {
    grid-template-columns: 1fr;
  }

  .casino-beyond__media {
    order: -1;
  }

  .casino-tiers {
    grid-template-columns: 1fr;
  }

  .casino-highlights__grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 640px) {
  .casino-stats {
    grid-template-columns: repeat(2, 1fr);
  }

  .casino-feature-cards {
    grid-template-columns: 1fr;
  }

  .casino-highlights__grid {
    grid-template-columns: 1fr;
  }

  .casino-gallery__grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .casino-gallery__item--wide {
    grid-column: span 2;
    aspect-ratio: 16 / 9;
  }
}

@media (prefers-reduced-motion: reduce) {
  .casino-hero__bg {
    transform: none;
  }

  .casino-tier:hover,
  .casino-highlight:hover,
  .casino-btn:hover,
  .casino-grand__media:hover,
  .casino-beyond__media:hover,
  .casino-feature-card:hover,
  .casino-games__item:hover {
    transform: none;
  }

  .casino-grand__media img,
  .casino-beyond__media img,
  .casino-grand__media.reveal img,
  .casino-beyond__media.reveal img {
    opacity: 1;
    transform: none;
    filter: none;
    transition: none;
  }

  .casino-grand__media-badge {
    animation: none;
  }

  .casino-grand__media::before,
  .casino-beyond__media::before,
  .casino-feature-card::before {
    display: none;
  }

  .casino-highlight {
    opacity: 1;
    transform: none;
    transition: none;
  }

  .casino-highlight__icon {
    animation: none;
  }

  .casino-highlight::before {
    display: none;
  }

  .casino-tier:hover .casino-tier__media img,
  .casino-gallery__item:hover img {
    transform: none;
  }
}

/* ══════════════════════════════════════════════════════════════
   Casino Reservation Modal
   ══════════════════════════════════════════════════════════════ */

.casino-reserve {
  --casino-gold: #3f7fff;
  position: fixed;
  inset: 0;
  z-index: 4000;
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding: clamp(0.75rem, 4vw, 2.5rem);
  overflow-y: auto;
  background: rgba(3, 5, 9, 0.78);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  animation: casino-reserve-fade 0.25s ease;
}

@keyframes casino-reserve-fade {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

.casino-reserve__dialog {
  position: relative;
  width: min(920px, 100%);
  margin: auto;
  border-radius: 8px;
  border: 1px solid rgba(63, 127, 255, 0.28);
  background:
    radial-gradient(ellipse 80% 40% at 50% 0%, rgba(63, 127, 255, 0.12) 0%, transparent 55%),
    linear-gradient(180deg, #0b0e15 0%, #070a10 100%);
  box-shadow: 0 40px 120px rgba(0, 0, 0, 0.7);
  padding: clamp(1.5rem, 3.5vw, 2.75rem);
  outline: none;
  animation: casino-reserve-rise 0.3s cubic-bezier(0.2, 0.7, 0.3, 1);
}

@keyframes casino-reserve-rise {
  from {
    opacity: 0;
    transform: translateY(18px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.casino-reserve__close {
  position: absolute;
  top: 1rem;
  right: 1rem;
  width: 38px;
  height: 38px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  border: 1px solid rgba(63, 127, 255, 0.3);
  background: rgba(255, 255, 255, 0.03);
  color: rgba(246, 240, 228, 0.85);
  cursor: pointer;
  transition: background 0.2s ease, color 0.2s ease, border-color 0.2s ease;
}

.casino-reserve__close:hover {
  background: rgba(63, 127, 255, 0.14);
  border-color: var(--casino-gold);
  color: #fff;
}

.casino-reserve__head {
  text-align: center;
  max-width: 560px;
  margin: 0 auto 1.75rem;
  padding-right: 2rem;
  padding-left: 2rem;
}

.casino-reserve__eyebrow {
  font-family: 'Montserrat', sans-serif;
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.34em;
  text-transform: uppercase;
  color: var(--casino-gold);
  margin: 0 0 0.75rem;
}

.casino-reserve__title {
  font-family: 'Playfair Display', serif;
  font-weight: 700;
  font-size: clamp(1.65rem, 4vw, 2.35rem);
  color: #fff;
  margin: 0 0 0.65rem;
}

.casino-reserve__sub {
  font-family: 'Montserrat', sans-serif;
  font-size: 0.88rem;
  line-height: 1.6;
  color: rgba(214, 210, 200, 0.72);
  margin: 0;
}

.casino-reserve__grid {
  display: grid;
  grid-template-columns: 1.1fr 0.9fr;
  gap: clamp(1.25rem, 3vw, 2.25rem);
  margin-bottom: 1.75rem;
}

.casino-reserve__col {
  min-width: 0;
}

.casino-reserve__label {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: rgba(214, 210, 200, 0.7);
  margin: 0 0 0.85rem;
}

.casino-reserve__label svg {
  color: var(--casino-gold);
}

.casino-reserve__col .casino-reserve__label:not(:first-child) {
  margin-top: 1.5rem;
}

/* ── Calendar ── */
.casino-cal {
  border: 1px solid rgba(63, 127, 255, 0.18);
  border-radius: 6px;
  background: rgba(255, 255, 255, 0.015);
  padding: 0.9rem;
}

.casino-cal__nav {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 0.85rem;
}

.casino-cal__navbtn {
  width: 32px;
  height: 32px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  border: 1px solid rgba(63, 127, 255, 0.25);
  background: transparent;
  color: rgba(246, 240, 228, 0.85);
  cursor: pointer;
  transition: background 0.2s ease, border-color 0.2s ease, opacity 0.2s ease;
}

.casino-cal__navbtn:hover:not(:disabled) {
  background: rgba(63, 127, 255, 0.14);
  border-color: var(--casino-gold);
}

.casino-cal__navbtn:disabled {
  opacity: 0.3;
  cursor: not-allowed;
}

.casino-cal__month {
  font-family: 'Playfair Display', serif;
  font-size: 1.05rem;
  font-weight: 600;
  color: #fff;
}

.casino-cal__weekdays {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 0.25rem;
  margin-bottom: 0.4rem;
}

.casino-cal__weekdays span {
  text-align: center;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: rgba(214, 210, 200, 0.45);
}

.casino-cal__grid {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 0.25rem;
}

.casino-cal__cell {
  aspect-ratio: 1;
  display: grid;
  place-items: center;
  border: 1px solid transparent;
  border-radius: 5px;
  background: transparent;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.82rem;
  font-weight: 500;
  color: rgba(238, 234, 226, 0.9);
  cursor: pointer;
  transition: background 0.18s ease, border-color 0.18s ease, color 0.18s ease, transform 0.18s ease;
}

.casino-cal__cell--empty {
  cursor: default;
}

.casino-cal__cell:not(:disabled):not(.casino-cal__cell--empty):hover {
  border-color: rgba(63, 127, 255, 0.5);
  background: rgba(63, 127, 255, 0.08);
}

.casino-cal__cell:disabled {
  color: rgba(214, 210, 200, 0.22);
  cursor: not-allowed;
}

.casino-cal__cell--selected,
.casino-cal__cell--selected:hover {
  color: #ffffff;
  font-weight: 700;
  background: linear-gradient(135deg, #7ea8ff, var(--casino-gold));
  border-color: transparent;
}

/* ── Time slots ── */
.casino-slots {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0.5rem;
}

.casino-slot {
  padding: 0.7rem 0.5rem;
  border: 1px solid rgba(63, 127, 255, 0.25);
  border-radius: 5px;
  background: rgba(255, 255, 255, 0.02);
  font-family: 'Montserrat', sans-serif;
  font-size: 0.85rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  color: rgba(238, 234, 226, 0.9);
  cursor: pointer;
  transition: background 0.18s ease, border-color 0.18s ease, color 0.18s ease;
}

.casino-slot:hover {
  border-color: rgba(63, 127, 255, 0.55);
  background: rgba(63, 127, 255, 0.08);
}

.casino-slot--selected,
.casino-slot--selected:hover {
  color: #ffffff;
  background: linear-gradient(135deg, #7ea8ff, var(--casino-gold));
  border-color: transparent;
}

/* ── Guest stepper ── */
.casino-stepper {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  border: 1px solid rgba(63, 127, 255, 0.22);
  border-radius: 999px;
  padding: 0.35rem;
}

.casino-stepper__btn {
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  border: none;
  background: rgba(63, 127, 255, 0.12);
  color: var(--casino-gold);
  cursor: pointer;
  transition: background 0.18s ease, opacity 0.18s ease;
}

.casino-stepper__btn:hover:not(:disabled) {
  background: rgba(63, 127, 255, 0.24);
}

.casino-stepper__btn:disabled {
  opacity: 0.35;
  cursor: not-allowed;
}

.casino-stepper__value {
  min-width: 2.25rem;
  text-align: center;
  font-family: 'Playfair Display', serif;
  font-size: 1.25rem;
  font-weight: 700;
  color: #fff;
}

.casino-reserve__summary {
  margin-top: 1.5rem;
  padding: 0.85rem 1rem;
  border-radius: 5px;
  border: 1px dashed rgba(63, 127, 255, 0.3);
  background: rgba(63, 127, 255, 0.05);
}

.casino-reserve__summary p {
  margin: 0;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.82rem;
  font-weight: 600;
  color: rgba(246, 240, 228, 0.92);
}

.casino-reserve__summary--muted {
  color: rgba(214, 210, 200, 0.5) !important;
  font-weight: 500 !important;
  font-style: italic;
}

/* ── Contact fields ── */
.casino-reserve__fields {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1rem;
  padding-top: 1.5rem;
  border-top: 1px solid rgba(63, 127, 255, 0.14);
}

.casino-reserve__field {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}

.casino-reserve__field--full {
  grid-column: 1 / -1;
}

.casino-reserve__field label {
  font-family: 'Montserrat', sans-serif;
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: rgba(214, 210, 200, 0.7);
}

.casino-reserve__field input,
.casino-reserve__field textarea {
  width: 100%;
  padding: 0.75rem 0.9rem;
  border: 1px solid rgba(63, 127, 255, 0.22);
  border-radius: 5px;
  background: rgba(255, 255, 255, 0.02);
  font-family: 'Montserrat', sans-serif;
  font-size: 0.9rem;
  color: #f6f0e4;
  transition: border-color 0.2s ease, background 0.2s ease;
  box-sizing: border-box;
}

.casino-reserve__field textarea {
  resize: vertical;
  min-height: 72px;
}

.casino-reserve__field input::placeholder,
.casino-reserve__field textarea::placeholder {
  color: rgba(214, 210, 200, 0.4);
}

.casino-reserve__field input:focus,
.casino-reserve__field textarea:focus {
  outline: none;
  border-color: var(--casino-gold);
  background: rgba(63, 127, 255, 0.06);
}

.casino-reserve__submit {
  display: flex;
  width: fit-content;
  min-width: 230px;
  margin: 1.75rem auto 0;
  padding: 0.78rem 2.2rem;
  font-size: 0.68rem;
  justify-content: center;
  border: 1px solid rgba(126, 168, 255, 0.75);
  box-shadow: 0 10px 28px rgba(63, 127, 255, 0.32), inset 0 0 0 1px rgba(126, 168, 255, 0.28);
  animation: casino-submit-pulse 2.8s ease-in-out infinite;
}

.casino-reserve__submit:hover {
  border-color: #bcd2ff;
}

@keyframes casino-submit-pulse {
  0%,
  100% {
    box-shadow: 0 10px 28px rgba(63, 127, 255, 0.3), inset 0 0 0 1px rgba(126, 168, 255, 0.28);
  }
  50% {
    box-shadow: 0 12px 34px rgba(63, 127, 255, 0.5), 0 0 20px rgba(63, 127, 255, 0.4),
      inset 0 0 0 1px rgba(126, 168, 255, 0.5);
  }
}

@media (prefers-reduced-motion: reduce) {
  .casino-reserve__submit {
    animation: none;
  }
}

.casino-reserve__error {
  margin: 1.25rem 0 0;
  padding: 0.75rem 1rem;
  border-radius: 5px;
  border: 1px solid rgba(224, 122, 95, 0.4);
  background: rgba(224, 122, 95, 0.1);
  font-family: 'Montserrat', sans-serif;
  font-size: 0.82rem;
  color: #f0b5a5;
}

.casino-reserve__note {
  margin: 0.9rem 0 0;
  text-align: center;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.72rem;
  line-height: 1.5;
  color: rgba(214, 210, 200, 0.5);
}

/* ── Success ── */
.casino-reserve__success {
  text-align: center;
  padding: 1.5rem 1rem 0.5rem;
}

.casino-reserve__success-icon {
  width: 68px;
  height: 68px;
  margin: 0 auto 1.5rem;
  display: grid;
  place-items: center;
  border-radius: 50%;
  color: #ffffff;
  background: linear-gradient(135deg, #7ea8ff, var(--casino-gold));
  box-shadow: 0 14px 36px rgba(63, 127, 255, 0.35);
}

.casino-reserve__success h3 {
  font-family: 'Playfair Display', serif;
  font-weight: 700;
  font-size: clamp(1.4rem, 3.5vw, 1.9rem);
  color: #fff;
  margin: 0 0 0.85rem;
}

.casino-reserve__success p {
  font-family: 'Montserrat', sans-serif;
  font-size: 0.92rem;
  line-height: 1.7;
  color: rgba(214, 210, 200, 0.75);
  margin: 0 auto 1.75rem;
  max-width: 440px;
}

@media (max-width: 720px) {
  .casino-reserve__grid {
    grid-template-columns: 1fr;
  }

  .casino-reserve__fields {
    grid-template-columns: 1fr;
  }
}

@media (prefers-reduced-motion: reduce) {
  .casino-reserve,
  .casino-reserve__dialog {
    animation: none;
  }
}

/* ============================================================
   Onassis — flagship yacht bespoke experience
   ============================================================ */
.onassis-page {
  --onassis-ink: #0a0f1c;
  --onassis-panel: #0f1729;
  --onassis-gold: #8fbaff;
  --onassis-gold-soft: rgba(143, 186, 255, 0.16);
  --onassis-line: rgba(143, 186, 255, 0.3);
  --onassis-text: #eef1f6;
  --onassis-muted: rgba(232, 236, 244, 0.72);
  background: var(--onassis-ink);
  color: var(--onassis-text);
}

.onassis-page .container {
  width: min(1200px, 100% - 2.5rem);
  margin-inline: auto;
}

/* ---- Hero ---- */
.onassis-hero {
  position: relative;
  min-height: min(90vh, 820px);
  display: flex;
  align-items: flex-end;
  overflow: hidden;
  isolation: isolate;
}

.onassis-hero__media {
  position: absolute;
  inset: 0;
  z-index: -1;
}

.onassis-hero__img,
.onassis-cat-hero__img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.onassis-hero__scrim {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(180deg, rgba(10, 15, 28, 0.55) 0%, rgba(10, 15, 28, 0.25) 40%, rgba(10, 15, 28, 0.92) 100%),
    radial-gradient(120% 90% at 15% 90%, rgba(10, 15, 28, 0.7), transparent 60%);
}

.onassis-hero__inner {
  padding-block: clamp(3rem, 8vw, 7rem);
  max-width: 780px;
}

.onassis-hero__eyebrow,
.onassis-eyebrow {
  margin: 0 0 1rem;
  font-size: 0.78rem;
  letter-spacing: 0.32em;
  text-transform: uppercase;
  color: var(--onassis-gold);
  font-weight: 600;
}

.onassis-hero__name {
  margin: 0;
  font-size: clamp(3rem, 9vw, 6.25rem);
  line-height: 0.98;
  font-weight: 300;
  letter-spacing: 0.02em;
  text-shadow: 0 12px 40px rgba(0, 0, 0, 0.45);
}

.onassis-hero__headline {
  margin: 1rem 0 0;
  font-size: clamp(1.15rem, 2.6vw, 1.65rem);
  font-weight: 400;
  color: #fff;
  text-wrap: balance;
}

.onassis-hero__lead {
  margin: 1.1rem 0 0;
  max-width: 60ch;
  font-size: clamp(1rem, 1.4vw, 1.08rem);
  line-height: 1.7;
  color: var(--onassis-muted);
  text-wrap: pretty;
}

.onassis-hero__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.9rem;
  margin-top: 2rem;
}

.onassis-hero__nav {
  position: absolute;
  top: clamp(1rem, 2.5vw, 1.5rem);
  left: 0;
  right: 0;
  z-index: 2;
}

.onassis-hero__nav .container,
.onassis-hero-back {
  pointer-events: auto;
}

.onassis-hero-back {
  margin-left: clamp(1rem, 2.5vw, 1.5rem);
  border: 1px solid rgba(255, 255, 255, 0.35);
  background: rgba(10, 15, 28, 0.35);
  color: #fff;
  font-size: 0.82rem;
  letter-spacing: 0.08em;
  padding: 0.5rem 1rem;
  border-radius: 999px;
  cursor: pointer;
  backdrop-filter: blur(6px);
  transition: background 0.25s ease, border-color 0.25s ease;
}

.onassis-hero-back:hover {
  background: rgba(143, 186, 255, 0.22);
  border-color: var(--onassis-gold);
}

/* ---- Buttons ---- */
.onassis-btn {
  --sweep: rgba(255, 255, 255, 0.28);
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.85rem 1.9rem;
  border-radius: 999px;
  font-size: 0.82rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  font-weight: 600;
  text-decoration: none;
  cursor: pointer;
  overflow: hidden;
  transition: transform 0.3s cubic-bezier(0.22, 1, 0.36, 1), box-shadow 0.3s ease,
    background 0.3s ease, color 0.3s ease, border-color 0.3s ease;
}

.onassis-btn::after {
  content: '';
  position: absolute;
  top: 0;
  left: -120%;
  width: 60%;
  height: 100%;
  background: linear-gradient(100deg, transparent, var(--sweep), transparent);
  transform: skewX(-18deg);
  transition: left 0.6s ease;
}

.onassis-btn:hover::after {
  left: 140%;
}

.onassis-btn--gold {
  background: linear-gradient(135deg, #cfe2ff 0%, var(--onassis-gold) 55%, #4f83e0 100%);
  color: #071630;
  box-shadow: 0 12px 30px rgba(79, 131, 224, 0.32);
}

.onassis-btn--gold:hover {
  transform: translateY(-3px) scale(1.02);
  box-shadow: 0 18px 44px rgba(79, 131, 224, 0.46);
}

.onassis-btn--ghost {
  background: rgba(255, 255, 255, 0.04);
  color: #fff;
  border: 1px solid var(--onassis-line);
}

.onassis-btn--ghost:hover {
  transform: translateY(-3px);
  border-color: var(--onassis-gold);
  background: var(--onassis-gold-soft);
}

.onassis-btn:active {
  transform: translateY(-1px) scale(0.99);
}

/* ---- Section headings ---- */
.onassis-section-title {
  margin: 0.4rem 0 0;
  font-size: clamp(1.8rem, 4vw, 2.75rem);
  font-weight: 300;
  letter-spacing: 0.01em;
  color: #fff;
  text-wrap: balance;
}

/* ---- Intro + stats ---- */
.onassis-intro {
  padding-block: clamp(3.5rem, 8vw, 6rem);
  background: linear-gradient(180deg, var(--onassis-ink), var(--onassis-panel));
}

.onassis-intro__inner {
  display: grid;
  grid-template-columns: 1fr;
  gap: clamp(2rem, 5vw, 4rem);
  align-items: center;
}

/* Only split into copy + stats sidebar when there's genuine room */
@media (min-width: 1024px) {
  .onassis-intro__inner {
    grid-template-columns: minmax(0, 1.4fr) minmax(0, 1fr);
  }
}

.onassis-intro__copy,
.onassis-stats {
  min-width: 0;
}

.onassis-intro__text {
  margin: 1rem 0 0;
  color: var(--onassis-muted);
  line-height: 1.8;
  font-size: 1.02rem;
  text-wrap: pretty;
}

.onassis-stats {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 160px), 1fr));
  gap: 1px;
  margin: 0;
  background: linear-gradient(180deg, rgba(143, 186, 255, 0.34), rgba(143, 186, 255, 0.1));
  border: 1px solid rgba(143, 186, 255, 0.34);
  border-radius: 18px;
  overflow: hidden;
  box-shadow: 0 24px 60px rgba(0, 0, 0, 0.42);
}

.onassis-stat {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: clamp(0.6rem, 1.5vw, 1rem);
  min-width: 0;
  min-height: clamp(130px, 18vw, 180px);
  padding: clamp(1.5rem, 4vw, 2.5rem) clamp(0.85rem, 2vw, 1.35rem);
  text-align: center;
  background:
    radial-gradient(130% 120% at 50% 0%, rgba(143, 186, 255, 0.08), transparent 58%),
    var(--onassis-panel);
  transition: background 0.45s ease, transform 0.45s ease;
}

.onassis-stat:hover {
  transform: translateY(-2px);
  background:
    radial-gradient(130% 120% at 50% 0%, rgba(143, 186, 255, 0.18), transparent 62%),
    #12203a;
}

.onassis-stat__value {
  order: -1;
  display: block;
  max-width: 100%;
  font-family: 'Cormorant Garamond', Georgia, serif;
  font-size: clamp(1.45rem, 2.4vw, 2rem);
  font-weight: 600;
  line-height: 1.1;
  letter-spacing: 0.01em;
  background: linear-gradient(135deg, #eaf3ff 0%, var(--onassis-gold) 52%, #5a8fe6 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  text-wrap: balance;
  overflow-wrap: normal;
  word-break: normal;
  hyphens: none;
}

.onassis-stat__label {
  position: relative;
  display: block;
  padding-top: 0.85rem;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.66rem;
  letter-spacing: 0.24em;
  text-transform: uppercase;
  color: var(--onassis-muted);
}

.onassis-stat__label::before {
  content: '';
  position: absolute;
  top: 0;
  left: 50%;
  transform: translateX(-50%);
  width: 30px;
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--onassis-gold), transparent);
}

/* ---- Category grid ---- */
.onassis-categories {
  padding-block: clamp(3.5rem, 8vw, 6.5rem);
  background: var(--onassis-panel);
}

/* Wider, near full-bleed presentation for the category showcase */
.onassis-categories > .container {
  width: min(1680px, 100% - 3rem);
}

.onassis-categories__head {
  text-align: center;
  max-width: 680px;
  margin: 0 auto clamp(2rem, 4vw, 3.25rem);
}

.onassis-categories__lead {
  margin: 0.9rem 0 0;
  color: var(--onassis-muted);
  font-size: 1.05rem;
}

.onassis-cat-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 360px), 1fr));
  gap: clamp(1.25rem, 2vw, 2rem);
}

.onassis-cat-card {
  position: relative;
  display: flex;
  flex-direction: column;
  min-height: clamp(430px, 40vw, 540px);
  border-radius: 22px;
  overflow: hidden;
  text-decoration: none;
  color: #fff;
  border: 1px solid rgba(255, 255, 255, 0.1);
  background: var(--onassis-ink);
  isolation: isolate;
  transition: transform 0.5s cubic-bezier(0.22, 1, 0.36, 1), box-shadow 0.5s ease,
    border-color 0.5s ease;
}

.onassis-cat-card:hover {
  transform: translateY(-10px);
  border-color: rgba(143, 186, 255, 0.5);
  box-shadow: 0 34px 70px rgba(0, 0, 0, 0.55);
}

.onassis-cat-card__media {
  position: absolute;
  inset: 0;
  z-index: -1;
}

.onassis-cat-card__img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.8s cubic-bezier(0.22, 1, 0.36, 1);
}

.onassis-cat-card:hover .onassis-cat-card__img {
  transform: scale(1.08);
}

.onassis-cat-card__scrim {
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(10, 15, 28, 0.05) 35%, rgba(10, 15, 28, 0.72) 100%);
}

/* Frosted glass info panel */
.onassis-cat-card__body {
  margin: auto 1rem 1rem;
  padding: 1.5rem 1.5rem 1.65rem;
  display: flex;
  flex-direction: column;
  gap: 0.55rem;
  border-radius: 18px;
  background: rgba(12, 20, 38, 0.38);
  -webkit-backdrop-filter: blur(18px) saturate(140%);
  backdrop-filter: blur(18px) saturate(140%);
  border: 1px solid rgba(255, 255, 255, 0.18);
  box-shadow:
    0 10px 34px rgba(0, 0, 0, 0.4),
    inset 0 1px 0 rgba(255, 255, 255, 0.16);
  transition: background 0.4s ease, border-color 0.4s ease;
}

.onassis-cat-card:hover .onassis-cat-card__body {
  background: rgba(18, 30, 54, 0.52);
  border-color: rgba(143, 186, 255, 0.55);
}

.onassis-cat-card__label {
  font-size: clamp(1.4rem, 2vw, 1.7rem);
  font-weight: 400;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.onassis-cat-card__tagline {
  font-size: 0.97rem;
  line-height: 1.55;
  color: rgba(255, 255, 255, 0.85);
}

.onassis-cat-card__cta {
  margin-top: 0.4rem;
  font-size: 0.78rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--onassis-gold);
  opacity: 0;
  transform: translateX(-6px);
  transition: opacity 0.35s ease, transform 0.35s ease;
}

.onassis-cat-card:hover .onassis-cat-card__cta {
  opacity: 1;
  transform: translateX(0);
}

/* ---- CTA band ---- */
.onassis-cta {
  padding-block: clamp(3.5rem, 8vw, 6rem);
  background: linear-gradient(180deg, var(--onassis-panel), var(--onassis-ink));
}

.onassis-cta__inner {
  text-align: center;
  max-width: 720px;
  margin-inline: auto;
}

.onassis-cta__title {
  margin: 0;
  font-size: clamp(1.8rem, 4vw, 2.6rem);
  font-weight: 300;
  color: #fff;
}

.onassis-cta__text {
  margin: 1rem auto 2rem;
  color: var(--onassis-muted);
  line-height: 1.75;
  max-width: 56ch;
}

.onassis-cta__actions,
.onassis-cat-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.9rem;
  justify-content: center;
}

/* ---- Category detail page ---- */
.onassis-cat-hero {
  position: relative;
  min-height: min(70vh, 640px);
  display: flex;
  align-items: flex-end;
  overflow: hidden;
  isolation: isolate;
}

.onassis-cat-hero__media {
  position: absolute;
  inset: 0;
  z-index: -1;
}

.onassis-cat-hero__inner {
  padding-block: clamp(2.5rem, 6vw, 5rem);
  max-width: 760px;
}

.onassis-cat-hero__title {
  margin: 0.6rem 0 0;
  font-size: clamp(2.4rem, 6vw, 4rem);
  font-weight: 300;
  color: #fff;
}

.onassis-cat-hero__tagline {
  margin: 0.9rem 0 0;
  font-size: clamp(1.02rem, 2vw, 1.25rem);
  color: rgba(255, 255, 255, 0.85);
  max-width: 52ch;
}

.onassis-cat-article {
  padding-block: clamp(2.5rem, 6vw, 4.5rem);
  background: var(--onassis-ink);
}

.onassis-breadcrumb {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.85rem;
  color: var(--onassis-muted);
  margin-bottom: 2rem;
}

.onassis-breadcrumb a {
  color: var(--onassis-muted);
  text-decoration: none;
  transition: color 0.2s ease;
}

.onassis-breadcrumb a:hover {
  color: var(--onassis-gold);
}

.onassis-breadcrumb__sep {
  opacity: 0.5;
}

.onassis-breadcrumb__current {
  color: var(--onassis-gold);
}

.onassis-cat-prose {
  max-width: 74ch;
}

.onassis-cat-prose p {
  margin: 0 0 1.1rem;
  font-size: clamp(1.02rem, 1.5vw, 1.14rem);
  line-height: 1.85;
  color: var(--onassis-muted);
  text-wrap: pretty;
}

.onassis-cat-h2 {
  margin: 2.75rem 0 1.25rem;
  font-size: 1.5rem;
  font-weight: 400;
  color: #fff;
  padding-bottom: 0.75rem;
  border-bottom: 1px solid var(--onassis-line);
}

.onassis-cat-highlights__list {
  list-style: none;
  padding: 0;
  margin: 0;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 280px), 1fr));
  gap: 0.75rem 1.5rem;
}

.onassis-cat-highlights__list li {
  position: relative;
  padding-left: 1.6rem;
  color: var(--onassis-text);
  line-height: 1.6;
}

.onassis-cat-highlights__list li::before {
  content: '';
  position: absolute;
  left: 0;
  top: 0.55em;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--onassis-gold);
  box-shadow: 0 0 0 4px var(--onassis-gold-soft);
}

.onassis-cat-specs__grid {
  margin: 0;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 240px), 1fr));
  gap: 1px;
  background: var(--onassis-line);
  border: 1px solid var(--onassis-line);
  border-radius: 14px;
  overflow: hidden;
}

.onassis-cat-specs__row {
  background: var(--onassis-panel);
  padding: 1.1rem 1.25rem;
}

.onassis-cat-specs__row dt {
  font-size: 0.72rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--onassis-muted);
}

.onassis-cat-specs__row dd {
  margin: 0.35rem 0 0;
  font-size: 1.05rem;
  color: #fff;
}

.onassis-cat-gallery__grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 280px), 1fr));
  gap: 0.9rem;
}

.onassis-cat-gallery__cell {
  margin: 0;
  border-radius: 14px;
  overflow: hidden;
  aspect-ratio: 4 / 3;
  border: 1px solid rgba(255, 255, 255, 0.08);
}

.onassis-cat-gallery__cell img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.6s cubic-bezier(0.22, 1, 0.36, 1);
}

.onassis-cat-gallery__cell:hover img {
  transform: scale(1.06);
}

.onassis-cat-actions {
  margin-top: 3rem;
  justify-content: flex-start;
}

.onassis-cat-pager {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  margin-top: 3rem;
  padding-top: 2rem;
  border-top: 1px solid var(--onassis-line);
}

.onassis-cat-pager__link {
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
  text-decoration: none;
  padding: 0.9rem 1.4rem;
  border-radius: 14px;
  border: 1px solid var(--onassis-line);
  background: var(--onassis-panel);
  transition: transform 0.3s ease, border-color 0.3s ease, background 0.3s ease;
}

.onassis-cat-pager__link--next {
  text-align: right;
}

.onassis-cat-pager__link:hover {
  transform: translateY(-3px);
  border-color: var(--onassis-gold);
  background: var(--onassis-gold-soft);
}

.onassis-cat-pager__dir {
  font-size: 0.72rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--onassis-muted);
}

.onassis-cat-pager__label {
  font-size: 1.05rem;
  color: #fff;
}

@media (max-width: 760px) {
  .onassis-intro__inner {
    grid-template-columns: 1fr;
  }
  .onassis-cat-actions {
    justify-content: center;
  }
  .onassis-cat-pager {
    flex-direction: column;
  }
  .onassis-cat-pager__link--next {
    text-align: left;
  }
}

@media (prefers-reduced-motion: reduce) {
  .onassis-cat-card,
  .onassis-cat-card__img,
  .onassis-btn,
  .onassis-cat-gallery__cell img {
    transition: none;
  }
}

/* ══════════════════════════════════════════════════════════════
   Appointment Scheduler Modal (premium, reusable)
   ══════════════════════════════════════════════════════════════ */
.appt {
  position: fixed;
  inset: 0;
  z-index: 1000;
  display: grid;
  place-items: center;
  padding: clamp(1rem, 3vw, 2rem);
  background: radial-gradient(circle at 50% 30%, rgba(9, 24, 48, 0.72), rgba(3, 7, 14, 0.86));
  backdrop-filter: blur(10px) saturate(1.1);
  -webkit-backdrop-filter: blur(10px) saturate(1.1);
  animation: apptFadeIn 0.32s ease both;
}

@keyframes apptFadeIn {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

.appt__dialog {
  position: relative;
  width: min(920px, 100%);
  max-height: min(92vh, 900px);
  overflow-y: auto;
  padding: clamp(1.5rem, 3.4vw, 2.6rem);
  border-radius: 22px;
  color: rgba(238, 243, 252, 0.94);
  background:
    linear-gradient(165deg, rgba(18, 42, 78, 0.96) 0%, rgba(8, 20, 40, 0.98) 60%, rgba(6, 14, 28, 0.99) 100%);
  border: 1px solid rgba(130, 176, 255, 0.28);
  box-shadow:
    0 40px 120px -40px rgba(0, 0, 0, 0.85),
    0 0 0 1px rgba(63, 127, 255, 0.12),
    inset 0 1px 0 rgba(255, 255, 255, 0.06);
  animation: apptRise 0.4s cubic-bezier(0.22, 1, 0.36, 1) both;
  outline: none;
}

@keyframes apptRise {
  from {
    opacity: 0;
    transform: translateY(24px) scale(0.98);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

.appt__close {
  position: absolute;
  top: clamp(0.9rem, 2vw, 1.25rem);
  right: clamp(0.9rem, 2vw, 1.25rem);
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  border-radius: 50%;
  color: rgba(224, 236, 255, 0.8);
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(130, 176, 255, 0.28);
  cursor: pointer;
  transition: background 0.25s ease, color 0.25s ease, transform 0.25s ease;
}

.appt__close:hover {
  color: #fff;
  background: rgba(63, 127, 255, 0.22);
  transform: rotate(90deg);
}

.appt__head {
  margin: 0 0 clamp(1.25rem, 2.6vw, 1.75rem);
  padding-right: 2.5rem;
}

.appt__eyebrow {
  margin: 0 0 0.5rem;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.6rem;
  font-weight: 700;
  letter-spacing: 0.3em;
  text-transform: uppercase;
  color: rgba(232, 215, 175, 0.92);
}

.appt__title {
  margin: 0 0 0.6rem;
  font-family: 'Playfair Display', Georgia, serif;
  font-size: clamp(1.5rem, 3.4vw, 2.15rem);
  font-weight: 500;
  line-height: 1.12;
  color: rgba(252, 250, 246, 0.98);
}

.appt__sub {
  margin: 0;
  max-width: 60ch;
  font-size: clamp(0.9rem, 1.2vw, 1rem);
  line-height: 1.6;
  color: rgba(196, 212, 232, 0.9);
}

.appt__grid {
  display: grid;
  grid-template-columns: minmax(0, 1.1fr) minmax(0, 1fr);
  gap: clamp(1.25rem, 3vw, 2rem);
  margin-bottom: clamp(1.35rem, 3vw, 1.9rem);
}

.appt__label {
  display: flex;
  align-items: center;
  gap: 0.45rem;
  margin: 0 0 0.85rem;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: rgba(180, 205, 240, 0.85);
}

.appt__label svg {
  color: #8fbaff;
}

/* Calendar */
.appt-cal {
  padding: clamp(0.85rem, 1.8vw, 1.15rem);
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(130, 176, 255, 0.2);
}

.appt-cal__nav {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 0.85rem;
}

.appt-cal__navbtn {
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  border-radius: 10px;
  color: rgba(224, 236, 255, 0.85);
  background: rgba(63, 127, 255, 0.1);
  border: 1px solid rgba(130, 176, 255, 0.28);
  cursor: pointer;
  transition: background 0.22s ease, transform 0.22s ease, opacity 0.22s ease;
}

.appt-cal__navbtn:hover:not(:disabled) {
  background: rgba(63, 127, 255, 0.28);
  transform: translateY(-1px);
}

.appt-cal__navbtn:disabled {
  opacity: 0.3;
  cursor: not-allowed;
}

.appt-cal__month {
  font-family: 'Montserrat', sans-serif;
  font-size: 0.95rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  color: rgba(244, 248, 255, 0.95);
}

.appt-cal__weekdays,
.appt-cal__grid {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 0.3rem;
}

.appt-cal__weekdays {
  margin-bottom: 0.45rem;
}

.appt-cal__weekdays span {
  text-align: center;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  color: rgba(150, 178, 216, 0.6);
}

.appt-cal__cell {
  aspect-ratio: 1 / 1;
  display: grid;
  place-items: center;
  border-radius: 10px;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.85rem;
  font-weight: 600;
  color: rgba(226, 236, 250, 0.9);
  background: transparent;
  border: 1px solid transparent;
  cursor: pointer;
  transition: background 0.2s ease, border-color 0.2s ease, color 0.2s ease, transform 0.2s ease;
}

.appt-cal__cell:hover:not(:disabled) {
  background: rgba(63, 127, 255, 0.16);
  border-color: rgba(130, 176, 255, 0.4);
  transform: translateY(-1px);
}

.appt-cal__cell:disabled {
  color: rgba(150, 170, 200, 0.28);
  cursor: not-allowed;
}

.appt-cal__cell--empty {
  cursor: default;
  border: none;
}

.appt-cal__cell--selected,
.appt-cal__cell--selected:hover {
  color: #071630;
  background: linear-gradient(180deg, #cfe2ff 0%, #6f9ee6 100%);
  border-color: rgba(207, 226, 255, 0.9);
  box-shadow: 0 8px 20px -8px rgba(63, 127, 255, 0.7);
}

/* Time slots */
.appt-slots {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0.5rem;
  margin-bottom: 1.1rem;
}

.appt-slot {
  padding: 0.6rem 0.4rem;
  border-radius: 10px;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.82rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  color: rgba(226, 236, 250, 0.9);
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(130, 176, 255, 0.22);
  cursor: pointer;
  transition: background 0.2s ease, border-color 0.2s ease, color 0.2s ease, transform 0.2s ease;
}

.appt-slot:hover {
  background: rgba(63, 127, 255, 0.16);
  border-color: rgba(130, 176, 255, 0.45);
  transform: translateY(-1px);
}

.appt-slot--selected,
.appt-slot--selected:hover {
  color: #071630;
  background: linear-gradient(180deg, #cfe2ff 0%, #6f9ee6 100%);
  border-color: rgba(207, 226, 255, 0.9);
  box-shadow: 0 8px 20px -8px rgba(63, 127, 255, 0.7);
}

.appt__summary {
  padding: 0.8rem 1rem;
  border-radius: 12px;
  background: rgba(63, 127, 255, 0.08);
  border: 1px solid rgba(130, 176, 255, 0.22);
  font-family: 'Montserrat', sans-serif;
  font-size: 0.85rem;
  color: rgba(226, 236, 250, 0.95);
}

.appt__summary p {
  margin: 0;
}

.appt__summary--muted {
  color: rgba(160, 182, 216, 0.6);
}

/* Fields */
.appt__fields {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: clamp(0.85rem, 1.8vw, 1.15rem);
}

.appt__field {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}

.appt__field--full {
  grid-column: 1 / -1;
}

.appt__field label {
  font-family: 'Montserrat', sans-serif;
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: rgba(180, 205, 240, 0.82);
}

.appt__optional {
  font-weight: 500;
  letter-spacing: 0.04em;
  text-transform: none;
  color: rgba(150, 178, 216, 0.6);
}

.appt__field input,
.appt__field textarea {
  width: 100%;
  padding: 0.75rem 0.9rem;
  border-radius: 11px;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.92rem;
  color: rgba(244, 248, 255, 0.96);
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(130, 176, 255, 0.24);
  transition: border-color 0.22s ease, background 0.22s ease, box-shadow 0.22s ease;
}

.appt__field textarea {
  resize: vertical;
  min-height: 3.2rem;
}

.appt__field input::placeholder,
.appt__field textarea::placeholder {
  color: rgba(160, 182, 216, 0.45);
}

.appt__field input:focus,
.appt__field textarea:focus {
  outline: none;
  border-color: rgba(143, 186, 255, 0.7);
  background: rgba(63, 127, 255, 0.08);
  box-shadow: 0 0 0 3px rgba(63, 127, 255, 0.16);
}

.appt__error {
  margin: 1rem 0 0;
  padding: 0.7rem 0.95rem;
  border-radius: 10px;
  font-size: 0.85rem;
  color: #ffd9d9;
  background: rgba(190, 50, 50, 0.16);
  border: 1px solid rgba(230, 90, 90, 0.4);
}

/* Buttons */
.appt__btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.85rem 1.8rem;
  border-radius: 999px;
  font-family: 'Montserrat', sans-serif;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: rgba(248, 252, 255, 0.98);
  background: linear-gradient(155deg, #143d6e 0%, #1e5a9e 30%, #2570bd 52%, #1a5088 100%);
  border: 1px solid rgba(140, 195, 245, 0.55);
  box-shadow: 0 12px 30px -12px rgba(12, 45, 88, 0.7), inset 0 1px 0 rgba(255, 255, 255, 0.12);
  cursor: pointer;
  transition: transform 0.26s cubic-bezier(0.22, 1, 0.36, 1), box-shadow 0.26s ease;
}

.appt__btn:hover:not(:disabled) {
  transform: translateY(-2px) scale(1.02);
  box-shadow: 0 18px 40px -12px rgba(12, 45, 88, 0.85), 0 0 30px -4px rgba(80, 155, 235, 0.4),
    inset 0 1px 0 rgba(255, 255, 255, 0.18);
}

.appt__btn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

.appt__submit {
  display: flex;
  margin: clamp(1.25rem, 3vw, 1.75rem) auto 0;
}

.appt__note {
  margin: 0.9rem 0 0;
  text-align: center;
  font-size: 0.76rem;
  color: rgba(160, 182, 216, 0.6);
}

/* Success */
.appt__success {
  text-align: center;
  padding: clamp(1rem, 3vw, 2rem) 0;
}

.appt__success-icon {
  display: grid;
  place-items: center;
  width: 64px;
  height: 64px;
  margin: 0 auto 1.25rem;
  border-radius: 50%;
  color: #071630;
  background: linear-gradient(180deg, #cfe2ff 0%, #6f9ee6 100%);
  box-shadow: 0 12px 30px -10px rgba(63, 127, 255, 0.7);
}

.appt__success h3 {
  margin: 0 0 0.6rem;
  font-family: 'Playfair Display', Georgia, serif;
  font-size: clamp(1.3rem, 2.6vw, 1.7rem);
  font-weight: 500;
  color: rgba(252, 250, 246, 0.98);
}

.appt__success p {
  margin: 0 auto 1.5rem;
  max-width: 46ch;
  font-size: 0.95rem;
  line-height: 1.6;
  color: rgba(196, 212, 232, 0.9);
}

@media (max-width: 720px) {
  .appt__grid {
    grid-template-columns: 1fr;
  }

  .appt__fields {
    grid-template-columns: 1fr;
  }
}

@media (prefers-reduced-motion: reduce) {
  .appt,
  .appt__dialog {
    animation: none;
  }

  .appt__close:hover,
  .appt__btn:hover:not(:disabled) {
    transform: none;
  }
}
